-- بيانات مقرر كيمياء 2-2 (المقرر 3، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem22-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L3-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بحرارة التبخر المولارية ΔHvap؟', null, '["الحرارة اللازمة لصهر 1 mol من المادة الصلبة","الحرارة اللازمة لتبخر 1 mol من السائل","الحرارة اللازمة لتبخر 1 g من السائل","الحرارة المنطلقة عند تبخر 1 mol من السائل"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 26 — حرارة التبخر المولارية وحرارة الانصهار المولارية'),
('mcq', 2, 'أيّ العبارات الآتية تعرّف حرارة الانصهار المولارية ΔHfus تعريفًا صحيحًا؟', null, '["الحرارة المنطلقة عند تجمد 1 g من المادة السائلة","الحرارة اللازمة لرفع درجة حرارة 1 mol من المادة الصلبة 1 °C","الحرارة اللازمة لصهر 1 kg من المادة الصلبة","الحرارة اللازمة لصهر 1 mol من المادة الصلبة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 26 — حرارة التبخر المولارية وحرارة الانصهار المولارية'),
('mcq', 3, 'لماذا تكون قيمة ΔH موجبة لكل من حرارة التبخر المولارية وحرارة الانصهار المولارية؟', null, '["لأن تبخر السائل وصهر المادة الصلبة عمليتان ماصتان للحرارة","لأن تبخر السائل وصهر المادة الصلبة عمليتان طاردتان للحرارة","لأن قيمتيهما تُقاسان في الظروف القياسية دائمًا","لأن المادة تفقد جزءًا من كتلتها في أثناء العمليتين"]'::jsonb, 'فهم', 'تفسير الإشارة', 'متوسط', 'الكتاب ص 26 — حرارة التبخر المولارية وحرارة الانصهار المولارية'),
('mcq', 4, 'بالاستعانة بالجدول، أيّ المواد الآتية يحتاج 1 mol منها إلى أكبر كمية من الحرارة لكي ينصهر؟', '{"headers":["المادة","الصيغة الكيميائية","ΔH°vap (kJ/mol)","ΔH°fus (kJ/mol)"],"rows":[["الماء","H₂O","40.7","6.01"],["الإيثانول","C₂H₅OH","38.6","4.94"],["الميثانول","CH₃OH","35.2","3.22"],["حمض الإيثانويك","CH₃COOH","23.4","11.7"],["الأمونيا","NH₃","23.3","5.66"]]}'::jsonb, '["الماء H₂O","الإيثانول C₂H₅OH","حمض الإيثانويك CH₃COOH","الأمونيا NH₃"]'::jsonb, 'فهم', 'قراءة جدول بيانات', 'متوسط', 'الكتاب ص 26 — الجدول 1-4 حرارة التبخر والانصهار القياسية'),
('mcq', 5, 'حرارة التبخر المولارية للميثانول 35.2 kJ/mol، وحرارة الانصهار المولارية له 3.22 kJ/mol. ما حرارة التكثف المولارية ΔHcond للميثانول؟', null, '["+35.2 kJ/mol","−35.2 kJ/mol","−3.22 kJ/mol","+3.22 kJ/mol"]'::jsonb, 'تطبيق', 'تطبيق العلاقة بين العملية وعكسها', 'متوسط', 'الكتاب ص 26، 27 — الجدول 1-4، ΔHvap = −ΔHcond'),
('mcq', 6, 'ما كمية الحرارة اللازمة لتبخير 64.1 g من الميثانول CH₃OH عند درجة غليانه؟ (ΔHvap = 35.2 kJ/mol، ΔHfus = 3.22 kJ/mol، الكتلة المولية = 32.04 g/mol)', null, '["35.2 kJ","6.44 kJ","2.26×10³ kJ","70.4 kJ"]'::jsonb, 'تطبيق', 'حساب باستعمال ΔHvap', 'صعب', 'الكتاب ص 26، 29 — الجدول 1-4، مسائل تدريبية'),
('mcq', 7, 'بالاستعانة بالجدول، أيّ عبارة تقارن بين ΔH°vap وΔH°fus للمادة نفسها مقارنة صحيحة؟', '{"headers":["المادة","الصيغة الكيميائية","ΔH°vap (kJ/mol)","ΔH°fus (kJ/mol)"],"rows":[["الماء","H₂O","40.7","6.01"],["الإيثانول","C₂H₅OH","38.6","4.94"],["الميثانول","CH₃OH","35.2","3.22"],["حمض الإيثانويك","CH₃COOH","23.4","11.7"],["الأمونيا","NH₃","23.3","5.66"]]}'::jsonb, '["ΔH°vap أكبر من ΔH°fus لكل مادة في الجدول","ΔH°fus أكبر من ΔH°vap لكل مادة في الجدول","ΔH°vap تساوي ΔH°fus لكل مادة في الجدول","ΔH°vap أكبر من ΔH°fus للماء وحده في الجدول"]'::jsonb, 'تحليل', 'مقارنة بيانات جدول', 'صعب', 'الكتاب ص 26 — الجدول 1-4 حرارة التبخر والانصهار القياسية'),
('essay', 1, 'عرّف كلًّا من حرارة التبخر المولارية وحرارة الانصهار المولارية، واكتب رمز كل منهما ووحدته، واذكر قيمتيهما للماء (40.7 kJ/mol و6.01 kJ/mol) مع تحديد أيهما لأيّ عملية.', null, null, 'تذكر', 'تعريف مصطلحين', 'سهل', 'الكتاب ص 26، 30 — تغيرات الحالة، الخلاصة'),
('essay', 2, 'للأمونيا NH₃: ΔHvap = 23.3 kJ/mol وΔHfus = 5.66 kJ/mol. (أ) فسّر لماذا تكون القيمتان موجبتين. (ب) استنتج قيمتي ΔHcond وΔHsolid للأمونيا، موضحًا العلاقة التي استعملتها.', null, null, 'فهم', 'تفسير واستنتاج', 'متوسط', 'الكتاب ص 26، 27 — الجدول 1-4، الشكل 1-9'),
('essay', 3, 'للإيثانول C₂H₅OH: ΔHvap = 38.6 kJ/mol، وΔHfus = 4.94 kJ/mol، والكتلة المولية 46.07 g/mol. احسب كمية الحرارة اللازمة لصهر 25.0 g من الإيثانول الصلب عند درجة انصهاره، وكمية الحرارة اللازمة لتبخير 25.0 g منه عند درجة غليانه، ثم بيّن أيّ التعريفين (ΔHvap أو ΔHfus) استعملته في كل حساب ولماذا.', null, null, 'تطبيق', 'حساب وتطبيق التعريف', 'صعب', 'الكتاب ص 26 — الجدول 1-4 حرارة التبخر والانصهار القياسية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L3-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'حرارة التبخر المولارية ΔHvap هي الحرارة اللازمة لتبخر 1 mol من السائل.', '["هذا تعريف حرارة الانصهار المولارية ΔHfus.","","الحرارة المولارية تُنسب إلى 1 mol من المادة لا إلى 1 g.","التبخر عملية ماصة للحرارة؛ فالحرارة لازمة (ممتصة) لا منطلقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:38:11.781Z"}'::jsonb),
('mcq', 2, 3, 'حرارة الانصهار المولارية ΔHfus هي الحرارة اللازمة لصهر 1 mol من المادة الصلبة.', '["هذا وصف للتجمد (العملية العكسية)، ثم إن التعريف المولاري يُبنى على 1 mol لا 1 g.","رفع درجة الحرارة دون تغير الحالة لا يتعلق بالانصهار؛ والانصهار تحوّل الصلب إلى سائل.","الحرارة المولارية تُنسب إلى 1 mol من المادة لا إلى 1 kg.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:38:11.782Z"}'::jsonb),
('mcq', 3, 0, 'يحتاج السائل إلى حرارة لكي يتبخر، وتحتاج المادة الصلبة إلى حرارة لكي تنصهر؛ ولأن العمليتين ماصتان للحرارة تكون ΔH لكل منهما موجبة.', '["","العمليات الطاردة إشارة ΔH فيها سالبة، والتبخر والانصهار ماصان للحرارة.","الظروف القياسية لا تحدد إشارة ΔH؛ الإشارة تحددها جهة انتقال الحرارة.","كتلة المادة لا تتغير بتغير حالتها، والإشارة سببها امتصاص الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:38:11.782Z"}'::jsonb),
('mcq', 4, 2, 'الحرارة اللازمة لصهر 1 mol هي ΔH°fus، وأكبر قيمة لها بين المواد المعطاة هي 11.7 kJ/mol لحمض الإيثانويك.', '["للماء أكبر ΔH°vap (40.7 kJ/mol)، لكن ΔH°fus له 6.01 kJ/mol فقط؛ والسؤال عن الانصهار.","ΔH°fus للإيثانول 4.94 kJ/mol، وهي أقل من 11.7 kJ/mol.","","ΔH°fus للأمونيا 5.66 kJ/mol، وهي أقل من 11.7 kJ/mol."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:38:11.782Z"}'::jsonb),
('mcq', 5, 1, 'التكثف عكس التبخر، فقيمتاهما متساويتان رقميًّا ومختلفتان في الإشارة: ΔHcond = −ΔHvap = −35.2 kJ/mol.', '["هذه قيمة ΔHvap نفسها؛ والتكثف طارد للحرارة فإشارته سالبة.","","هذه قيمة ΔHsolid (عكس الانصهار)، لا التكثف.","هذه قيمة ΔHfus للانصهار، لا علاقة لها بالتكثف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:38:11.782Z"}'::jsonb),
('mcq', 6, 3, 'عدد المولات = 64.1 g ÷ 32.04 g/mol = 2.00 mol، والحرارة اللازمة = 2.00 mol × 35.2 kJ/mol = 70.4 kJ.', '["هذه حرارة تبخير 1 mol فقط؛ لم تُحسب مولات العينة.","استُعملت حرارة الانصهار (3.22 kJ/mol) بدلًا من حرارة التبخر: 2.00 × 3.22 = 6.44 kJ.","ضُربت الكتلة بالجرام مباشرة في ΔHvap (64.1 × 35.2) دون تحويلها إلى مولات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:38:11.783Z"}'::jsonb),
('mcq', 7, 0, 'بمقارنة القيم: الماء 40.7 > 6.01، الإيثانول 38.6 > 4.94، الميثانول 35.2 > 3.22، حمض الإيثانويك 23.4 > 11.7، الأمونيا 23.3 > 5.66؛ فـ ΔH°vap أكبر من ΔH°fus لكل مادة في الجدول.', '["","العكس هو الصحيح؛ فـ ΔH°fus أصغر في كل صف (مثلًا 6.01 مقابل 40.7 للماء).","القيمتان مختلفتان في كل صف؛ والمتساويتان رقميًّا هما ΔHvap وΔHcond لا ΔHvap وΔHfus.","ليست الحال للماء وحده؛ فجميع المواد في الجدول ΔH°vap لها أكبر من ΔH°fus."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:38:11.783Z"}'::jsonb),
('essay', 1, null::int, null, null, 'حرارة التبخر المولارية ΔHvap: الحرارة اللازمة لتبخر 1 mol من السائل، ووحدتها kJ/mol، وللماء 40.7 kJ/mol. حرارة الانصهار المولارية ΔHfus: الحرارة اللازمة لصهر 1 mol من المادة الصلبة، ووحدتها kJ/mol، وللماء 6.01 kJ/mol.', '["تعريف ΔHvap: الحرارة اللازمة لتبخر 1 mol من السائل","تعريف ΔHfus: الحرارة اللازمة لصهر 1 mol من المادة الصلبة","الرمزان ΔHvap وΔHfus والوحدة kJ/mol","ΔHvap للماء 40.7 kJ/mol وΔHfus للماء 6.01 kJ/mol"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف حرارة التبخر المولارية","marks":1},{"element":"تعريف حرارة الانصهار المولارية","marks":1},{"element":"الرمزان والوحدة","marks":1},{"element":"نسبة القيمتين إلى العمليتين الصحيحتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان مع الرمزين والوحدة ونسبة القيمتين صحيحة"},{"level":"2–3 درجات","description":"تعريف واحد صحيح مع الرموز، أو التعريفان دون الرموز والقيم"},{"level":"1 درجة","description":"ذكر الرموز أو القيم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال «1 mol» في التعريف","تبديل القيمتين بين التبخر والانصهار","كتابة الوحدة kJ/g"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:38:11.783Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) القيمتان موجبتان لأن تبخر السائل وصهر المادة الصلبة عمليتان ماصتان للحرارة؛ فالمادة تحتاج إلى حرارة لكي تتبخر أو تنصهر. (ب) التكثف عكس التبخر، والتجمد عكس الانصهار، وكمية الحرارة المنطلقة في العملية الطاردة تساوي الكمية الممتصة في العملية الماصة العكسية: ΔHcond = −ΔHvap = −23.3 kJ/mol، وΔHsolid = −ΔHfus = −5.66 kJ/mol.', '["التبخر والانصهار ماصان للحرارة","ΔHvap = −ΔHcond وΔHfus = −ΔHsolid","ΔHcond = −23.3 kJ/mol","ΔHsolid = −5.66 kJ/mol"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الإشارة الموجبة","marks":1},{"element":"ذكر العلاقة بين العملية وعكسها","marks":1},{"element":"قيمة ΔHcond","marks":1},{"element":"قيمة ΔHsolid","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح، والعلاقة مذكورة، والقيمتان صحيحتان بإشارتيهما"},{"level":"2–3 درجات","description":"القيمتان صحيحتان دون تفسير أو دون ذكر العلاقة"},{"level":"1 درجة","description":"قيمة واحدة صحيحة أو تفسير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء ΔHcond إشارة موجبة","ربط ΔHcond بـ ΔHfus","القول إن التبخر طارد للحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-03T20:38:11.785Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدد المولات = 25.0 g ÷ 46.07 g/mol = 0.543 mol. حرارة الصهر = 0.543 mol × 4.94 kJ/mol = 2.68 kJ، واستُعملت ΔHfus لأنها الحرارة اللازمة لصهر 1 mol من المادة الصلبة. حرارة التبخير = 0.543 mol × 38.6 kJ/mol = 20.9 kJ، واستُعملت ΔHvap لأنها الحرارة اللازمة لتبخر 1 mol من السائل. ولأن التعريفين مبنيان على 1 mol، لزم تحويل الكتلة إلى مولات أولًا.', '["تحويل الكتلة إلى مولات 0.543 mol","حرارة الصهر 2.68 kJ","حرارة التبخير 20.9 kJ","ربط كل حساب بالتعريف المناسب","التحويل إلى مولات لأن التعريفين لـ 1 mol"]'::jsonb, '["n = 25.0 g ÷ 46.07 g/mol = 0.543 mol","q(صهر) = 0.543 mol × 4.94 kJ/mol = 2.68 kJ","q(تبخير) = 0.543 mol × 38.6 kJ/mol = 20.9 kJ"]'::jsonb, '[{"element":"حساب عدد المولات","marks":1},{"element":"حساب حرارة الصهر","marks":1},{"element":"حساب حرارة التبخير","marks":1},{"element":"الربط بالتعريفين وتبرير التحويل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة بالوحدات والأرقام المعنوية مع ربط صحيح بالتعريفين"},{"level":"3–4 درجات","description":"حسابات صحيحة دون تبرير كامل، أو خطأ حسابي واحد مع ربط صحيح"},{"level":"1–2 درجة","description":"حساب عدد المولات أو حساب واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل ΔHvap وΔHfus بين الحسابين","ضرب الكتلة مباشرة في ΔH","قسمة عدد المولات على ΔH بدلًا من الضرب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:38:11.785Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
