from (values
('mcq', 1, 'إذا كانت حرارة التبخر المولارية للماء ΔHvap = 40.7 kJ/mol، فما حرارة التكثف المولارية للماء ΔHcond؟', null, '["+40.7 kJ/mol","−40.7 kJ/mol","−6.01 kJ/mol","+6.01 kJ/mol"]'::jsonb, 'فهم', 'تطبيق علاقة ΔHvap = −ΔHcond', 'سهل', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('mcq', 2, 'أيّ العلاقات الآتية تربط ربطًا صحيحًا بين حرارة الانصهار المولارية وحرارة التجمد المولارية لمادة ما؟', null, '["ΔHfus = ΔHsolid","ΔHfus = −ΔHvap","ΔHsolid = −ΔHcond","ΔHfus = −ΔHsolid"]'::jsonb, 'فهم', 'تمييز العلاقة الصحيحة', 'سهل', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('mcq', 3, 'حرارة التبخر المولارية للأمونيا NH₃ تساوي 23.3 kJ/mol. ما حرارة التكثف المولارية للأمونيا؟', null, '["−23.3 kJ/mol","+23.3 kJ/mol","−5.66 kJ/mol","+46.6 kJ/mol"]'::jsonb, 'تطبيق', 'حساب ΔHcond من ΔHvap', 'سهل', 'الكتاب ص 30 — التقويم 1-3 (س30)'),
('mcq', 4, 'لماذا تكون إشارة حرارة التجمد المولارية ΔHsolid لأي مادة سالبة؟', null, '["لأن المادة تمتص حرارة عند تجمدها فيزداد المحتوى الحراري","لأن درجة حرارة المادة تنخفض باستمرار في أثناء تجمدها","لأن المادة تطلق حرارة عند تجمدها فيقل المحتوى الحراري للنظام","لأن قيمتها العددية أصغر دائمًا من حرارة التبخر المولارية"]'::jsonb, 'فهم', 'تفسير إشارة ΔH', 'متوسط', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('mcq', 5, 'حرارة الانصهار المولارية لحمض الإيثانويك CH₃COOH تساوي 11.7 kJ/mol. أيّ المعادلات الحرارية الآتية صحيحة؟', null, '["CH₃COOH(l) → CH₃COOH(s)   ΔH = +11.7 kJ","CH₃COOH(s) → CH₃COOH(l)   ΔH = −11.7 kJ","CH₃COOH(l) → CH₃COOH(g)   ΔH = −11.7 kJ","CH₃COOH(l) → CH₃COOH(s)   ΔH = −11.7 kJ"]'::jsonb, 'تطبيق', 'اختيار معادلة حرارية لتغير حالة', 'متوسط', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('mcq', 6, 'تنطلق 5.66 kJ من الحرارة عند تجمد 1 mol من الأمونيا السائلة NH₃ عند درجة تجمدها. ما حرارة الانصهار المولارية ΔHfus للأمونيا؟ (ΔHvap للأمونيا = 23.3 kJ/mol)', null, '["+5.66 kJ/mol","−5.66 kJ/mol","+23.3 kJ/mol","−23.3 kJ/mol"]'::jsonb, 'فهم', 'تفسير تطبيق حياتي', 'متوسط', 'الكتاب ص 26، 27 — الجدول 1-4، ΔHfus = −ΔHsolid'),
('mcq', 7, 'التغير في المحتوى الحراري لعملية ما يساوي −38.6 kJ لكل 1 mol من الإيثانول. علمًا أن ΔHvap للإيثانول = 38.6 kJ/mol و ΔHfus = 4.94 kJ/mol، فأيّ عملية هذه؟', null, '["C₂H₅OH(l) → C₂H₅OH(g)","C₂H₅OH(l) → C₂H₅OH(s)","C₂H₅OH(g) → C₂H₅OH(l)","C₂H₅OH(s) → C₂H₅OH(l)"]'::jsonb, 'تحليل', 'استنتاج العملية من قيمة ΔH وإشارتها', 'صعب', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('essay', 1, 'اشرح لماذا تتساوى حرارة التبخر المولارية وحرارة التكثف المولارية للماء في القيمة العددية وتختلفان في الإشارة، مستعينًا بمخطط مستويات المحتوى الحراري للماء في حالتيه السائلة والغازية (ΔHvap = 40.7 kJ/mol).', null, null, 'فهم', 'شرح علاقة', 'متوسط', 'الكتاب ص 27 — المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('essay', 2, 'إذا علمت أن لحمض الإيثانويك CH₃COOH القيمتين ΔHvap = 23.4 kJ/mol و ΔHfus = 11.7 kJ/mol. اكتب المعادلة الكيميائية الحرارية لكل من تكثف حمض الإيثانويك وتجمده، مع قيمة ΔH لكل منهما، ثم صنّف كل عملية إلى ماصة للحرارة أو طاردة لها.', null, null, 'تطبيق', 'كتابة معادلات حرارية', 'متوسط', 'الكتاب ص 26، 27 — الجدول 1-4، المعادلات الكيميائية الحرارية لتغيرات الحالة (الشكل 1-9)'),
('essay', 3, 'يرش المزارعون الماء على أشجار البرتقال في الليالي الباردة لحمايتها، بينما يساعد التعرق على تبريد الجسم. فسّر الظاهرتين معًا مبينًا العملية الحرارية في كل منهما، وإشارة ΔH لها، والعلاقة بين حرارتها وحرارة العملية العكسية.', null, null, 'تحليل', 'تفسير ظواهر', 'صعب', 'الكتاب ص 27، 47 — حماية الفاكهة من التجمد، اختبار مقنن (س10، س11)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
