select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'التكثف هو العملية العكسية للتبخر، و ΔHcond = −ΔHvap؛ لذا ΔHcond = −40.7 kJ/mol: القيمة العددية نفسها بإشارة سالبة لأن التكثف عملية طاردة للحرارة.', '["التكثف عكس التبخر؛ فالقيمة العددية نفسها لكن الإشارة سالبة لأن التكثف يطلق الحرارة، لا يمتصها.","","هذه حرارة التجمد المولارية للماء (ΔHsolid)، وهي عكس الانصهار لا عكس التبخر.","هذه حرارة الانصهار المولارية للماء، ولا علاقة لها بالتكثف الذي هو عكس التبخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:38:11.786Z"}'::jsonb),
('mcq', 2, 3, 'التجمد عكس الانصهار، وكمية الحرارة المنطلقة عند تجمد 1 mol تساوي كمية الحرارة الممتصة عند صهره؛ لذا ΔHfus = −ΔHsolid.', '["القيمتان متساويتان عدديًّا لكنهما مختلفتان في الإشارة؛ فالانصهار ماص للحرارة والتجمد طارد لها.","هذه العلاقة تخلط بين الانصهار والتبخر؛ فـ ΔHvap يقابلها ΔHcond لا ΔHfus.","التجمد يقابل الانصهار، والتكثف يقابل التبخر؛ ولا تربط علاقة عكسية بين التجمد والتكثف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:38:11.786Z"}'::jsonb),
('mcq', 3, 0, 'بما أن ΔHcond = −ΔHvap، فإن حرارة التكثف المولارية للأمونيا = −23.3 kJ/mol.', '["","نسي الطالب عكس الإشارة؛ فالتكثف طارد للحرارة فإشارة ΔHcond سالبة.","هذه حرارة التجمد المولارية للأمونيا (عكس حرارة انصهارها 5.66 kJ/mol)، لا حرارة التكثف.","ضاعف الطالب القيمة خطأً؛ فالتكثف يطلق القيمة العددية نفسها التي يمتصها التبخر لا ضعفها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:38:11.787Z"}'::jsonb),
('mcq', 4, 2, 'التجمد عكس الانصهار، وفيه تطلق المادة كمية من الحرارة تساوي ما امتصته عند الانصهار، فيقل المحتوى الحراري للنظام؛ ولذلك تكون ΔHsolid سالبة.', '["التجمد لا يمتص الحرارة؛ فالامتصاص يحدث في الانصهار، والامتصاص يعطي ΔH موجبة لا سالبة.","تبقى درجة الحرارة ثابتة في أثناء التجمد؛ والإشارة السالبة سببها انطلاق الحرارة لا تغير درجة الحرارة.","","مقارنة المقادير العددية لا تحدد الإشارة؛ فـ ΔHfus أصغر من ΔHvap أيضًا ومع ذلك إشارتها موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-03T20:38:11.787Z"}'::jsonb),
('mcq', 5, 3, 'تجمد 1 mol من حمض الإيثانويك يطلق 11.7 kJ لأن ΔHsolid = −ΔHfus = −11.7 kJ؛ فالمعادلة الصحيحة: CH₃COOH(l) → CH₃COOH(s)   ΔH = −11.7 kJ.', '["تحول السائل إلى صلب تجمد، وهو طارد للحرارة؛ فإشارة ΔH يجب أن تكون سالبة.","تحول الصلب إلى سائل انصهار، وهو ماص للحرارة؛ فإشارة ΔH يجب أن تكون موجبة.","هذه معادلة تبخر، والتبخر ماص للحرارة وقيمته ΔHvap لا ΔHfus، فالإشارة والقيمة كلتاهما خطأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:38:11.787Z"}'::jsonb),
('mcq', 6, 0, 'التجمد طارد للحرارة فـ ΔHsolid = −5.66 kJ/mol، والانصهار عكس التجمد؛ ومن العلاقة ΔHfus = −ΔHsolid تكون ΔHfus = +5.66 kJ/mol: القيمة العددية نفسها بإشارة موجبة لأن الانصهار ماص للحرارة.', '["","هذه قيمة ΔHsolid نفسها؛ والانصهار عكس التجمد فإشارته موجبة.","هذه قيمة ΔHvap للأمونيا، وهي تقابل التكثف لا التجمد.","هذه قيمة ΔHcond للأمونيا (عكس التبخر)، لا علاقة لها بالانصهار والتجمد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:38:11.787Z"}'::jsonb),
('mcq', 7, 2, 'القيمة العددية 38.6 kJ تخص التبخر أو عكسه، والإشارة السالبة تعني انطلاق الحرارة؛ فالعملية هي التكثف C₂H₅OH(g) → C₂H₅OH(l) لأن ΔHcond = −ΔHvap = −38.6 kJ/mol.', '["هذا تبخر، وهو ماص للحرارة فقيمته +38.6 kJ لا −38.6 kJ.","هذا تجمد، وقيمته −4.94 kJ لأنه عكس الانصهار لا عكس التبخر.","","هذا انصهار، وهو ماص للحرارة وقيمته +4.94 kJ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:38:11.788Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التبخر والتكثف عمليتان متعاكستان بين المستويين نفسيهما من المحتوى الحراري: H₂O(l) في المستوى الأدنى و H₂O(g) في المستوى الأعلى. عند التبخر ينتقل 1 mol من المستوى الأدنى إلى الأعلى فيمتص النظام 40.7 kJ، فتكون ΔHvap = +40.7 kJ. وعند التكثف ينتقل 1 mol من المستوى الأعلى إلى الأدنى، فيطلق النظام الكمية نفسها لأن الفرق بين المستويين ثابت، فتكون ΔHcond = −40.7 kJ. إذن ΔHvap = −ΔHcond.', '["H₂O(g) محتواه الحراري أعلى من H₂O(l)","التبخر يمتص الحرارة فإشارته موجبة +40.7 kJ","التكثف يطلق الحرارة فإشارته سالبة −40.7 kJ","الفرق بين المستويين ثابت فالقيمة العددية واحدة","العلاقة ΔHvap = −ΔHcond"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد أن محتوى البخار الحراري أعلى من السائل","marks":1},{"element":"تفسير الإشارة الموجبة للتبخر","marks":1},{"element":"تفسير الإشارة السالبة للتكثف","marks":1},{"element":"تعليل تساوي القيمة العددية بثبات الفرق بين المستويين وكتابة العلاقة","marks":1}]'::jsonb, '[{"level":"4","description":"شرح كامل يذكر المستويين وإشارتي العمليتين وسبب تساوي القيمة العددية مع العلاقة"},{"level":"3","description":"يفسر الإشارتين ويذكر العلاقة دون تعليل تساوي القيمة العددية"},{"level":"2","description":"يذكر العلاقة وإشارة إحدى العمليتين فقط"},{"level":"1","description":"يذكر العلاقة دون أي تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التكثف ماصًّا للحرارة","الظن أن القيمة العددية للتكثف أصغر من التبخر","الخلط بين ΔHcond و ΔHsolid"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-03T20:38:11.788Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التكثف: CH₃COOH(g) → CH₃COOH(l)   ΔHcond = −23.4 kJ، وهو طارد للحرارة. التجمد: CH₃COOH(l) → CH₃COOH(s)   ΔHsolid = −11.7 kJ، وهو طارد للحرارة. فكلتا العمليتين طاردتان للحرارة لأنهما عكس التبخر والانصهار الماصين للحرارة (ΔHcond = −ΔHvap، ΔHsolid = −ΔHfus).', '["معادلة التكثف بالحالات الصحيحة g → l","ΔHcond = −23.4 kJ","معادلة التجمد بالحالات الصحيحة l → s","ΔHsolid = −11.7 kJ","تصنيف العمليتين طاردتين للحرارة مع التعليل"]'::jsonb, '["التكثف عكس التبخر: ΔHcond = −ΔHvap = −23.4 kJ","التجمد عكس الانصهار: ΔHsolid = −ΔHfus = −11.7 kJ","الإشارة السالبة تعني أن العمليتين طاردتان للحرارة"]'::jsonb, '[{"element":"معادلة التكثف بحالاتها","marks":1},{"element":"قيمة ΔHcond وإشارتها","marks":1},{"element":"معادلة التجمد بحالاتها","marks":1},{"element":"قيمة ΔHsolid وإشارتها","marks":1},{"element":"التصنيف مع التعليل","marks":1}]'::jsonb, '[{"level":"5","description":"معادلتان صحيحتان بحالاتهما وقيمتان صحيحتان بإشارتيهما وتصنيف معلل"},{"level":"4","description":"خطأ واحد في حالة أو إشارة أو تعليل"},{"level":"3","description":"معادلة واحدة صحيحة كاملة مع التصنيف"},{"level":"1","description":"يصنف العمليتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ΔH موجبة للتكثف أو التجمد","عكس الحالتين في المعادلة","وضع 23.4 مع التجمد و 11.7 مع التكثف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:38:11.789Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عند رش الماء على البرتقال يتجمد الماء (H₂O(l) → H₂O(s))، والتجمد طارد للحرارة: ΔHsolid = −ΔHfus = −6.01 kJ/mol، فتنتقل الحرارة المنطلقة إلى الثمار والهواء المحيط فتمنع تلفها. أما في التعرق فيتبخر الماء عن الجلد (H₂O(l) → H₂O(g))، والتبخر ماص للحرارة: ΔHvap = +40.7 kJ/mol، فيمتص الماء الحرارة من الجلد فيبرد الجسم. فالظاهرتان متعاكستان في اتجاه انتقال الحرارة: الأولى تطلق حرارة مساوية لما يمتصه الانصهار، والثانية تمتص حرارة مساوية لما يطلقه التكثف.', '["رش البرتقال: تجمد الماء","التجمد طارد للحرارة ΔHsolid سالبة وتساوي −ΔHfus","الحرارة المنطلقة تدفئ الثمار","التعرق: تبخر الماء عن الجلد","التبخر ماص للحرارة ΔHvap موجبة وتساوي −ΔHcond","الحرارة تُمتص من الجلد فيبرد الجسم"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد عملية التجمد وإشارتها في رش البرتقال","marks":1},{"element":"ربط ΔHsolid بـ ΔHfus وتفسير الحماية","marks":1},{"element":"تحديد عملية التبخر وإشارتها في التعرق","marks":1},{"element":"ربط ΔHvap بـ ΔHcond وتفسير التبريد","marks":1}]'::jsonb, '[{"level":"4","description":"يفسر الظاهرتين كاملتين مع الإشارتين والعلاقتين"},{"level":"3","description":"يفسر الظاهرتين مع الإشارتين دون إحدى العلاقتين"},{"level":"2","description":"يفسر ظاهرة واحدة تفسيرًا كاملًا"},{"level":"1","description":"يسمي العمليتين دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن الماء المرشوش يحمي الثمار بتبخره","عدّ التبخر طاردًا للحرارة","الظن أن التعرق يبرد الجسم لأن العرق بارد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:38:11.789Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
