('essay', 3, null::int, null, null, 'n = 100. g ÷ 18.02 g/mol = 5.55 mol. حرارة الصهر = 5.55 mol × 6.01 kJ/mol = 33.4 kJ. حرارة التبخر = 5.55 mol × 40.7 kJ/mol = 226 kJ. النسبة = 226 ÷ 33.4 = 6.77؛ فتبخير الكتلة نفسها يحتاج إلى حرارة تزيد نحو 6.77 مرة على صهرها (وهي النسبة نفسها 40.7 ÷ 6.01).', '["n = 5.55 mol","حرارة الصهر 33.4 kJ","حرارة التبخر 226 kJ","النسبة نحو 6.77 مرة لصالح التبخر"]'::jsonb, '["n = 100. g ÷ 18.02 g/mol = 5.55 mol","q(fus) = 5.55 × 6.01 = 33.4 kJ","q(vap) = 5.55 × 40.7 = 226 kJ","226 ÷ 33.4 = 6.77"]'::jsonb, '[{"element":"تحويل الكتلة إلى مولات","marks":1},{"element":"حساب حرارة الصهر","marks":1},{"element":"حساب حرارة التبخر","marks":1},{"element":"حساب النسبة والمقارنة","marks":1}]'::jsonb, '[{"level":"4","description":"حسابات صحيحة ومقارنة بالنسبة"},{"level":"3","description":"الحسابان صحيحان دون نسبة صحيحة"},{"level":"2","description":"حساب واحد صحيح"},{"level":"1","description":"تحويل صحيح إلى مولات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال التحويل إلى مولات","عكس النسبة","الخلط بين القيمتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-03T20:38:11.794Z"}'::jsonb)
