from (values
('mcq', 1, 'سُخنت عينة من الجليد عند −20°C بمعدل ثابت حتى تحولت إلى بخار عند 120°C. في الجزء من منحنى التسخين الذي تبقى فيه درجة الحرارة ثابتة عند 0°C، ما الذي يحدث للعينة؟', null, '["يسخن الجليد وترتفع درجة حرارته","يغلي الماء متحولًا إلى بخار","يتكثف بخار الماء إلى سائل","ينصهر الجليد متحولًا إلى ماء سائل"]'::jsonb, 'فهم', 'تحديد ما يحدث في منطقة', 'سهل', 'الكتاب ص 47 — اختبار مقنن (س9: منحنى تسخين الماء)'),
('mcq', 2, 'في أثناء غليان الماء عند 100°C على منحنى التسخين، كيف تتغير طاقة الحركة وطاقة الوضع لجزيئات الماء؟', null, '["تزداد طاقة الحركة وتبقى طاقة الوضع ثابتة","تبقى طاقة الحركة ثابتة وتزداد طاقة الوضع","تزداد طاقة الحركة وطاقة الوضع معًا","تقل طاقة الوضع وتبقى طاقة الحركة ثابتة"]'::jsonb, 'تحليل', 'تحليل تغير الطاقة في منطقة', 'متوسط', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 3, 'يبين الجدول بيانات تسخين 180 g من الماء بمعدل ثابت من −20°C إلى 120°C. في أيّ فترة زمنية يغلي الماء؟', '{"headers":["الزمن (min)","درجة الحرارة (°C)"],"rows":[["0.0","−20"],["1.0","0"],["2.0","0"],["3.0","9"],["6.0","58"],["9.0","92"],["11.0","100"],["18.0","100"],["24.0","100"],["25.0","120"]]}'::jsonb, '["من 1.0 min إلى 2.0 min","من 3.0 min إلى 11.0 min","من 11.0 min إلى 24.0 min","من 24.0 min إلى 25.0 min"]'::jsonb, 'تحليل', 'تفسير بيانات جدول', 'متوسط', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 4, 'عند تسخين عينة من الماء بمعدل ثابت، يكون الجزء الأفقي عند 100°C في منحنى التسخين أطول كثيرًا من الجزء الأفقي عند 0°C. ما سبب ذلك؟', null, '["لأن ΔHvap للماء (40.7 kJ/mol) أكبر كثيرًا من ΔHfus (6.01 kJ/mol)","لأن الحرارة النوعية للبخار أكبر من الحرارة النوعية للجليد","لأن درجة الغليان أعلى من درجة الانصهار","لأن كتلة الماء تزداد في أثناء الغليان"]'::jsonb, 'تحليل', 'تعليل طول الأجزاء الأفقية', 'متوسط', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 5, 'على منحنى تسخين الماء بمعدل ثابت، يكون ميل الجزء الخاص بتسخين بخار الماء أكبر من ميل الجزء الخاص بتسخين الماء السائل. ما تفسير ذلك؟ (C للسائل = 4.184 J/g·°C، C للبخار = 2.01 J/g·°C)', null, '["الحرارة النوعية للبخار أكبر، فيمتص حرارة أكثر في كل دقيقة","البخار يمتص حرارة التبخر في أثناء تسخينه","الحرارة النوعية للبخار أقل، فترتفع درجة حرارته أسرع بالحرارة نفسها","كتلة البخار أقل من كتلة السائل الذي تكوّن منه"]'::jsonb, 'تحليل', 'تفسير ميل المنحنى', 'صعب', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 6, 'ما كمية الحرارة التي تمتصها عينة كتلتها 90.0 g من الماء السائل في منطقة منحنى التسخين التي ترتفع فيها درجة حرارتها من 0°C إلى 100°C؟ (C للماء السائل = 4.184 J/g·°C، C للجليد = 2.03 J/g·°C)', null, '["18.3 kJ","37.7 kJ","0.418 kJ","203 kJ"]'::jsonb, 'تطبيق', 'حساب الحرارة لمنطقة من المنحنى', 'متوسط', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 7, 'ينصهر الإيثانول عند −114°C ويغلي عند 78°C. إذا سُخنت عينة من الإيثانول الصلب بمعدل ثابت من −120°C إلى 90°C، فعند أيّ درجتي حرارة يظهر جزءا المنحنى الأفقيان؟', null, '["عند −114°C وعند 78°C","عند 0°C وعند 100°C","عند −120°C وعند 90°C","عند −114°C فقط"]'::jsonb, 'تطبيق', 'التنبؤ بشكل منحنى تسخين مادة أخرى', 'سهل', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('essay', 1, 'سُخنت عينة من الجليد عند −20°C بمعدل ثابت حتى أصبحت بخارًا عند 120°C، فتكوّن منحنى تسخين من خمسة أجزاء متتالية: (1) جزء مائل من −20°C إلى 0°C، (2) جزء أفقي عند 0°C، (3) جزء مائل من 0°C إلى 100°C، (4) جزء أفقي عند 100°C، (5) جزء مائل فوق 100°C. حدّد ماذا يحدث للماء في كل جزء، وبيّن أين تُستهلك الحرارة الممتصة: في زيادة طاقة الحركة أم طاقة الوضع.', null, null, 'فهم', 'تفسير أجزاء منحنى', 'سهل', 'الكتاب ص 47 — اختبار مقنن (س9: منحنى تسخين الماء)'),
('essay', 2, 'احسب كمية الحرارة الكلية اللازمة لتحويل 90.0 g من الجليد عند −20.0°C إلى بخار عند 120.0°C، بحساب الحرارة في كل جزء من أجزاء منحنى التسخين الخمسة. (C للجليد = 2.03 J/g·°C، C للماء السائل = 4.184 J/g·°C، C للبخار = 2.01 J/g·°C، ΔHfus = 6.01 kJ/mol، ΔHvap = 40.7 kJ/mol، الكتلة المولية للماء 18.02 g/mol)', null, null, 'تطبيق', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('essay', 3, 'حلّل منحنى تسخين عينة من الماء بمعدل ثابت، مفسرًا: (أ) لماذا يتناسب طول كل جزء من المنحنى (زمنه) مع كمية الحرارة الممتصة فيه؟ (ب) لماذا يكون الجزء الأفقي عند 100°C أطول الأجزاء جميعًا؟ (ج) لماذا يكون ميل جزء تسخين الجليد وميل جزء تسخين البخار أكبر من ميل جزء تسخين الماء السائل؟ (C للجليد = 2.03، C للسائل = 4.184، C للبخار = 2.01 J/g·°C؛ ΔHfus = 6.01، ΔHvap = 40.7 kJ/mol)', null, null, 'تحليل', 'تحليل منحنى', 'صعب', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الجزء الأفقي عند 0°C هو منطقة الانصهار؛ فالحرارة الممتصة تُستهلك في تحويل الجليد إلى ماء سائل دون أن ترتفع درجة الحرارة.', '["ارتفاع درجة حرارة الجليد يحدث في الجزء المائل قبل 0°C، أما عند 0°C فدرجة الحرارة ثابتة.","الغليان يحدث عند الجزء الأفقي الثاني عند 100°C لا عند 0°C.","التكثف يحدث عند التبريد لا عند التسخين، ويكون عند 100°C.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:38:11.795Z"}'::jsonb),
('mcq', 2, 1, 'درجة الحرارة ثابتة في أثناء الغليان، فمتوسط طاقة الحركة ثابت، والحرارة الممتصة (ΔHvap) تُستهلك في التغلب على الروابط الهيدروجينية بين الجزيئات فتزداد طاقة الوضع.', '["زيادة طاقة الحركة تظهر بارتفاع درجة الحرارة، ودرجة الحرارة ثابتة في أثناء الغليان.","","ثبات درجة الحرارة يعني ثبات متوسط طاقة الحركة؛ فالحرارة الممتصة تذهب إلى طاقة الوضع فقط.","الغليان يمتص الحرارة ليتغلب على قوى التجاذب بين الجزيئات، فتزداد طاقة الوضع لا تقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.795Z"}'::jsonb),
('mcq', 3, 2, 'الغليان يحدث عندما تثبت درجة الحرارة عند 100°C مع استمرار التسخين، وهذا يحدث من 11.0 min إلى 24.0 min.', '["في هذه الفترة تبقى درجة الحرارة ثابتة عند 0°C، فهي فترة الانصهار لا الغليان.","في هذه الفترة ترتفع درجة الحرارة من 9°C إلى 100°C، فهي تسخين للماء السائل.","","في هذه الفترة ترتفع درجة الحرارة فوق 100°C، فهي تسخين لبخار الماء بعد انتهاء الغليان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-03T20:38:11.796Z"}'::jsonb),
('mcq', 4, 0, 'مع ثبات معدل التسخين يتناسب الزمن مع كمية الحرارة الممتصة، وتبخير 1 mol يحتاج 40.7 kJ بينما صهره يحتاج 6.01 kJ فقط؛ لذا يكون جزء الغليان أطول نحو سبع مرات.', '["","الحرارة النوعية تتحكم في ميل الأجزاء المائلة لا في طول الأجزاء الأفقية؛ كما أن قيمتيهما متقاربتان (2.01 و 2.03 J/g·°C).","قيمة درجة الحرارة لا تحدد طول الجزء الأفقي؛ فالطول يتناسب مع كمية الحرارة اللازمة لتغير الحالة.","الكتلة ثابتة طوال التسخين؛ والطول يرجع إلى أن تبخير المول يحتاج حرارة أكبر من صهره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-03T20:38:11.796Z"}'::jsonb),
('mcq', 5, 2, 'من q = m × C × ΔT، عندما تكون q و m ثابتتين في كل دقيقة يكون ΔT أكبر كلما قلت C؛ والحرارة النوعية للبخار (2.01) أقل من السائل (4.184)، فيكون ميل جزء البخار أكبر.', '["الحرارة النوعية للبخار 2.01 J/g·°C وهي أقل من السائل؛ والحرارة النوعية الأكبر تعني ارتفاعًا أبطأ لا أسرع.","حرارة التبخر تُمتص في الجزء الأفقي عند 100°C فقط، لا في أثناء تسخين البخار.","","الكتلة محفوظة في أثناء تغير الحالة؛ والفرق في الميل سببه الحرارة النوعية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-03T20:38:11.797Z"}'::jsonb),
('mcq', 6, 1, 'في هذه المنطقة يسخن الماء السائل: q = m × C × ΔT = 90.0 g × 4.184 J/g·°C × 100°C = 37656 J = 37.7 kJ.', '["استعمل الطالب الحرارة النوعية للجليد 2.03 J/g·°C، والعينة في هذه المنطقة سائلة.","","أهمل الطالب الكتلة فحسب C × ΔT فقط (4.184 × 100 = 418 J).","حسب الطالب حرارة تبخر العينة (4.99 mol × 40.7 kJ/mol)، وهي تخص الجزء الأفقي عند 100°C لا هذه المنطقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-03T20:38:11.798Z"}'::jsonb),
('mcq', 7, 0, 'يثبت المنحنى أفقيًّا عند تغير الحالة: عند درجة الانصهار −114°C وعند درجة الغليان 78°C، وكلتاهما داخل مدى التسخين.', '["","هاتان درجتا انصهار الماء وغليانه، والجزءان الأفقيان يظهران عند درجتي انصهار المادة المسخنة وغليانها.","هاتان درجتا البداية والنهاية، ودرجة الحرارة تتغير عندهما ولا تثبت.","التسخين يتجاوز 78°C، فيظهر جزء أفقي ثانٍ عند الغليان أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-03T20:38:11.798Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) يسخن الجليد وترتفع درجة حرارته، فتزداد طاقة حركة الجزيئات. (2) ينصهر الجليد عند 0°C ودرجة الحرارة ثابتة، فتذهب الحرارة (ΔHfus) إلى زيادة طاقة الوضع. (3) يسخن الماء السائل من 0°C إلى 100°C فتزداد طاقة الحركة. (4) يغلي الماء عند 100°C ودرجة الحرارة ثابتة، فتذهب الحرارة (ΔHvap) إلى زيادة طاقة الوضع والتغلب على الروابط الهيدروجينية. (5) يسخن بخار الماء فوق 100°C فتزداد طاقة الحركة.', '["الجزء 1: تسخين الجليد — طاقة حركة","الجزء 2: انصهار — طاقة وضع","الجزء 3: تسخين السائل — طاقة حركة","الجزء 4: غليان — طاقة وضع","الجزء 5: تسخين البخار — طاقة حركة"]'::jsonb, '[]'::jsonb, '[{"element":"الجزء 1","marks":1},{"element":"الجزء 2","marks":1},{"element":"الجزء 3","marks":1},{"element":"الجزء 4","marks":1},{"element":"الجزء 5","marks":1}]'::jsonb, '[{"level":"5","description":"يحدد العملية ونوع الطاقة في الأجزاء الخمسة"},{"level":"4","description":"خطأ في جزء واحد"},{"level":"3","description":"يحدد العمليات صحيحة دون ربطها بنوع الطاقة"},{"level":"1","description":"يحدد جزأي تغير الحالة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن درجة الحرارة ترتفع في أثناء الانصهار أو الغليان","ربط الأجزاء الأفقية بزيادة طاقة الحركة","الخلط بين جزء الانصهار وجزء الغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:38:11.799Z"}'::jsonb),
('essay', 2, null::int, null, null, 'n = 90.0 ÷ 18.02 = 4.99 mol. (1) تسخين الجليد: 90.0 × 2.03 × 20.0 = 3654 J = 3.65 kJ. (2) الانصهار: 4.99 × 6.01 = 30.0 kJ. (3) تسخين السائل: 90.0 × 4.184 × 100. = 37656 J = 37.7 kJ. (4) الغليان: 4.99 × 40.7 = 203 kJ. (5) تسخين البخار: 90.0 × 2.01 × 20.0 = 3618 J = 3.62 kJ. المجموع = 3.65 + 30.0 + 37.7 + 203 + 3.62 = 278 kJ.', '["تحويل الكتلة إلى مولات 4.99 mol","q1 = 3.65 kJ","q2 = 30.0 kJ","q3 = 37.7 kJ","q4 = 203 kJ","q5 = 3.62 kJ","المجموع 278 kJ"]'::jsonb, '["n = 90.0 g ÷ 18.02 g/mol = 4.99 mol","q1 = m × C(s) × ΔT = 90.0 × 2.03 × 20.0 = 3.65 kJ","q2 = n × ΔHfus = 4.99 × 6.01 = 30.0 kJ","q3 = m × C(l) × ΔT = 90.0 × 4.184 × 100. = 37.7 kJ","q4 = n × ΔHvap = 4.99 × 40.7 = 203 kJ","q5 = m × C(g) × ΔT = 90.0 × 2.01 × 20.0 = 3.62 kJ","q الكلية = 278 kJ"]'::jsonb, '[{"element":"تحويل الكتلة إلى مولات","marks":1},{"element":"حساب جزأي تسخين الجليد والبخار","marks":1},{"element":"حساب حرارة الانصهار","marks":1},{"element":"حساب تسخين السائل","marks":1},{"element":"حساب حرارة التبخر","marks":1},{"element":"الجمع بتوحيد الوحدات إلى kJ","marks":1}]'::jsonb, '[{"level":"6","description":"جميع الحسابات صحيحة مع توحيد الوحدات والمجموع"},{"level":"4","description":"خطأ في حساب واحد أو في توحيد الوحدات"},{"level":"2","description":"حسابات أجزاء تغير الحالة فقط أو أجزاء التسخين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع J مع kJ دون تحويل","استعمال حرارة نوعية واحدة لكل الحالات","ضرب الكتلة بالغرام في ΔHvap أو ΔHfus"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:38:11.799Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المعدل ثابت، أي إن الحرارة المضافة في كل دقيقة متساوية، فكلما احتاج الجزء حرارة أكبر استغرق زمنًا أطول. (ب) الغليان يحتاج 40.7 kJ لكل مول، وهي أكبر كمية حرارة بين الأجزاء (نحو سبعة أضعاف الانصهار وأكبر بكثير من حرارة تسخين السائل 100°C)، لأن التبخر يتطلب فصل الجزيئات تمامًا والتغلب على الروابط الهيدروجينية القوية. (ج) من q = m × C × ΔT، مع ثبات q في الدقيقة و m، يكون ΔT أكبر كلما قلت C؛ والحرارة النوعية للجليد (2.03) والبخار (2.01) نحو نصف حرارة السائل (4.184)، فترتفع درجة حرارتهما أسرع فيكون الميل أكبر.', '["ثبات معدل التسخين يجعل الزمن متناسبًا مع الحرارة","ΔHvap أكبر من غيرها فجزء الغليان الأطول","ربط ذلك بالتغلب على الروابط الهيدروجينية","استعمال q = m × C × ΔT لتفسير الميل","مقارنة الحرارة النوعية للحالات الثلاث"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير (أ)","marks":1},{"element":"تفسير (ب) بمقارنة ΔHvap","marks":1},{"element":"ربط (ب) بالتجاذب بين الجزيئات","marks":1},{"element":"تفسير (ج) بالعلاقة والقيم","marks":1}]'::jsonb, '[{"level":"4","description":"تفسيرات صحيحة للأجزاء الثلاثة مع العلاقات والقيم"},{"level":"3","description":"خطأ أو نقص في تفسير واحد"},{"level":"2","description":"تفسير جزأين فقط"},{"level":"1","description":"تفسير جزء واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن الحرارة النوعية الأكبر تعني ميلًا أكبر","تعليل طول جزء الغليان بارتفاع درجة حرارته","إهمال شرط ثبات معدل التسخين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:38:11.800Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
