insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L3-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'عند احتراق 1 mol من الجلوكوز في مسعر ينطلق 2808 kJ من الحرارة. ما كمية الطاقة التي تنطلق من أيض 1 mol من الجلوكوز في جسم الإنسان خلال عملية التنفس الخلوي؟', null, '["أقل من 2808 kJ لأن الجسم لا يحرق الجلوكوز بالأكسجين","أكثر من 2808 kJ لأن التفاعل في الجسم يحدث في خطوات كثيرة","2808 kJ، أي الكمية نفسها المنطلقة في المسعر","صفر، لأن الطاقة تُخزن كلها ولا تنطلق"]'::jsonb, 'فهم', 'مقارنة الطاقة في المسعر والجسم', 'سهل', 'الكتاب ص 29 — الربط بعلم الأحياء: التنفس الخلوي و ATP'),
('mcq', 2, 'في أي صورة تُخزن الطاقة الناتجة عن تكسير الجلوكوز في خلايا الجسم خلال التنفس الخلوي؟', null, '["طاقة حركية في جزيئات ثاني أكسيد الكربون","حرارة مخزنة في جزيئات الماء الناتجة","طاقة وضع كيميائية في روابط جزيئات الجلوكوز","طاقة وضع كيميائية في روابط جزيئات ATP"]'::jsonb, 'تذكر', 'تذكر صورة تخزين الطاقة', 'سهل', 'الكتاب ص 29 — الربط بعلم الأحياء: التنفس الخلوي و ATP'),
('mcq', 3, 'ما نواتج تكسير الجلوكوز في خلايا الجسم خلال التنفس الخلوي؟', null, '["ثاني أكسيد الكربون والماء","الأكسجين والماء","الجلوكوز والأكسجين","ثاني أكسيد الكربون والهيدروجين"]'::jsonb, 'تذكر', 'تذكر النواتج', 'سهل', 'الكتاب ص 29 — الربط بعلم الأحياء: التنفس الخلوي و ATP'),
('mcq', 4, 'ما الفرق الرئيس بين احتراق الجلوكوز في المسعر وأيضه في خلايا الجسم؟', null, '["ينتج في الخلايا نواتج مختلفة عن نواتج المسعر","يحدث في الخلايا في سلسلة من الخطوات المعقدة لا في خطوة واحدة","يحتاج في الخلايا إلى غاز غير الأكسجين","يمتص في الخلايا حرارة بدلًا من إطلاقها"]'::jsonb, 'فهم', 'المقارنة بين عمليتين', 'متوسط', 'الكتاب ص 29 — الربط بعلم الأحياء: التنفس الخلوي و ATP'),
('mcq', 5, 'ما كمية الطاقة المنطلقة من أيض 90.1 g من الجلوكوز C₆H₁₂O₆ في الجسم؟ (ΔHcomb = −2808 kJ/mol، الكتلة المولية 180.18 g/mol)', null, '["1.40×10³ kJ","2.53×10⁵ kJ","5.62×10³ kJ","2.81×10³ kJ"]'::jsonb, 'تطبيق', 'حساب الطاقة من كتلة الجلوكوز', 'متوسط', 'الكتاب ص 29 — مثال 1-4 (حرارة احتراق الجلوكوز)'),
('mcq', 6, 'عندما تحتاج عضلة في الجسم إلى طاقة لتنقبض، فما الذي يحدث؟', null, '["يحترق الجلوكوز مباشرة داخل العضلة في خطوة واحدة","تمتص جزيئات ATP الطاقة من العضلة","يتحول الماء الناتج من التنفس إلى طاقة","تطلق جزيئات ATP كمية الطاقة المطلوبة"]'::jsonb, 'فهم', 'تفسير دور ATP', 'متوسط', 'الكتاب ص 29 — الربط بعلم الأحياء: التنفس الخلوي و ATP'),
('mcq', 7, 'لماذا تُعد الأغذية التي تحتوي على الكربوهيدرات وقودًا لجسم الإنسان؟', null, '["لأنها تمتص الحرارة من الجسم فتنظم درجة حرارته","لأنها تتحول إلى جلوكوز يحترق في الجسم فيزوده بالطاقة","لأنها تتحول مباشرة إلى جزيئات ATP دون تفاعل","لأنها تحتوي على الأكسجين اللازم للاحتراق"]'::jsonb, 'فهم', 'تفسير مفهوم الغذاء وقودًا', 'صعب', 'الكتاب ص 30 — تفاعلات الاحتراق (الشكل 1-10)'),
('essay', 1, 'وضّح بالتسلسل كيف تصل الطاقة المخزنة في الجلوكوز إلى عضلة تحتاج إليها، بدءًا من تناول الغذاء، مبينًا دور التنفس الخلوي ودور جزيئات ATP.', null, null, 'فهم', 'توضيح تسلسل', 'متوسط', 'الكتاب ص 29 — الربط بعلم الأحياء: التنفس الخلوي و ATP'),
('essay', 2, 'تناول شخص طعامًا يحتوي على 45.0 g من الجلوكوز C₆H₁₂O₆. احسب كمية الطاقة التي يمكن أن تنطلق من أيضه كاملًا في الجسم، ثم بيّن هل تختلف هذه الكمية عن الطاقة المنطلقة عند حرق الكتلة نفسها في مسعر، مع التعليل. (ΔHcomb = −2808 kJ/mol، الكتلة المولية 180.18 g/mol)', null, null, 'تطبيق', 'مسألة مع تعليل', 'سهل', 'الكتاب ص 29 — مثال 1-4 (حرارة احتراق الجلوكوز)'),
('essay', 3, 'قارن بين احتراق الجلوكوز في المسعر وأيضه في خلايا الجسم من حيث: المتفاعلات، والنواتج، وكمية الطاقة المنطلقة لكل 1 mol، وعدد خطوات التفاعل، ومصير الطاقة الناتجة. ثم اكتب المعادلة الكيميائية الحرارية المشتركة بينهما.', null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 30 — تفاعلات الاحتراق (الشكل 1-10)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
