select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تنطلق الكمية نفسها (2808 kJ) من أيض كتلة مساوية من الجلوكوز في الجسم، لأن المتفاعلات (الجلوكوز والأكسجين) والنواتج (CO₂ و H₂O) نفسها في الحالتين.', '["الجسم يؤكسد الجلوكوز بالأكسجين أيضًا وينتج CO₂ و H₂O، فتنطلق الكمية نفسها.","تعدد الخطوات لا يغير الطاقة الكلية المنطلقة ما دامت المتفاعلات والنواتج نفسها.","","الطاقة تنطلق من الجلوكوز ثم يُخزن جزء منها في ATP؛ فهي لا تبقى في الجلوكوز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:38:11.804Z"}'::jsonb),
('mcq', 2, 3, 'تُخزن الحرارة الناتجة في صورة طاقة وضع كيميائية في روابط جزيئات ثلاثي فوسفات الأدينوسين ATP.', '["CO₂ ناتج يطرحه الجسم، ولا تُخزن فيه الطاقة للاستعمال لاحقًا.","الماء ناتج من نواتج التنفس، والطاقة تُخزن في روابط ATP لا في الماء.","الجلوكوز هو الذي يتكسر ويطلق الطاقة، فلا تُخزن الطاقة الناتجة فيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-03T20:38:11.804Z"}'::jsonb),
('mcq', 3, 0, 'يتكسر الجلوكوز في الخلايا فينطلق ثاني أكسيد الكربون والماء، وهما الناتجان نفساهما عند حرق الجلوكوز في المسعر: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O.', '["","الأكسجين متفاعل يستهلكه التنفس الخلوي، لا ناتج منه.","هاتان هما المادتان المتفاعلتان، لا النواتج.","ناتج الهيدروجين في الاحتراق هو الماء، لا غاز الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-03T20:38:11.804Z"}'::jsonb),
('mcq', 4, 1, 'يحدث التنفس الخلوي في كل خلية في سلسلة من الخطوات المعقدة، بينما يحترق الجلوكوز في المسعر مباشرة؛ أما المتفاعلات والنواتج والطاقة الكلية فواحدة.', '["النواتج في الحالتين واحدة: ثاني أكسيد الكربون والماء.","","الأكسجين متفاعل في الحالتين؛ والفرق في عدد الخطوات لا في المتفاعلات.","الأيض في الحالتين طارد للحرارة (ΔH سالبة)، ويطلق الكمية نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:38:11.805Z"}'::jsonb),
('mcq', 5, 0, 'n = 90.1 g ÷ 180.18 g/mol = 0.500 mol، والطاقة = 0.500 mol × 2808 kJ/mol = 1.40×10³ kJ، وهي الكمية نفسها المنطلقة عند حرقه في المسعر.', '["","ضرب الطالب الكتلة بالغرام في 2808 مباشرة دون تحويلها إلى مولات.","قسم الطالب 2808 على عدد المولات (0.500 mol) بدلًا من ضربه فيها.","افترض الطالب أن العينة 1 mol دون حساب عدد مولاتها الفعلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-03T20:38:11.805Z"}'::jsonb),
('mcq', 6, 3, 'عندما يحتاج أي جزء من الجسم إلى الطاقة تقوم جزيئات ATP بإطلاق كمية الطاقة المطلوبة من روابطها.', '["أيض الجلوكوز يحدث في سلسلة من الخطوات، والطاقة المخزنة في ATP هي التي تُطلق عند الحاجة.","ATP يخزن الطاقة ثم يطلقها عند الحاجة، ولا يمتصها من الجزء المحتاج إليها.","الماء ناتج من نواتج التنفس الخلوي، ولا يتحول إلى طاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:38:11.805Z"}'::jsonb),
('mcq', 7, 1, 'تتحول الكربوهيدرات في الغذاء إلى جلوكوز، ويحترق الجلوكوز داخل الجسم (يتفاعل مع الأكسجين) فيطلق الطاقة التي يحتاج إليها الجسم في أنشطته الحيوية؛ لذا فالغذاء وقود الجسم.', '["الكربوهيدرات مصدر للطاقة لا ماصة لها؛ فاحتراق الجلوكوز طارد للحرارة.","","الجلوكوز يتكسر أولًا بتفاعله مع الأكسجين، ثم تُخزن الطاقة الناتجة في ATP.","الأكسجين اللازم يأتي من التنفس؛ والغذاء يزود الجسم بالوقود (الجلوكوز)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-03T20:38:11.805Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تتحول الكربوهيدرات في الغذاء إلى جلوكوز داخل الجسم. في التنفس الخلوي يتكسر الجلوكوز في كل خلية بتفاعله مع الأكسجين في سلسلة من الخطوات المعقدة، فينطلق CO₂ والماء وتنطلق طاقة (2808 kJ لكل 1 mol). تُخزن هذه الطاقة في صورة طاقة وضع كيميائية في روابط جزيئات ATP. وعندما تحتاج العضلة إلى طاقة تطلق جزيئات ATP كمية الطاقة المطلوبة.', '["الغذاء يتحول إلى جلوكوز","التنفس الخلوي: تكسير الجلوكوز مع الأكسجين في خطوات","النواتج CO₂ و H₂O وانطلاق الطاقة","تخزين الطاقة طاقة وضع كيميائية في روابط ATP","ATP يطلق الطاقة عند حاجة العضلة"]'::jsonb, '[]'::jsonb, '[{"element":"تحول الغذاء إلى جلوكوز","marks":1},{"element":"وصف التنفس الخلوي ونواتجه","marks":1},{"element":"تخزين الطاقة في ATP","marks":1},{"element":"إطلاق ATP للطاقة عند الحاجة","marks":1}]'::jsonb, '[{"level":"4","description":"تسلسل كامل صحيح بأدوار التنفس الخلوي و ATP"},{"level":"3","description":"تسلسل صحيح مع نقص عنصر واحد"},{"level":"2","description":"يذكر دور ATP فقط أو التنفس الخلوي فقط"},{"level":"1","description":"عبارات متفرقة صحيحة دون تسلسل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن الجلوكوز يعطي الطاقة للعضلة مباشرة","الظن أن ATP يمتص الطاقة عند حاجة العضلة","نسيان دور الأكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-03T20:38:11.805Z"}'::jsonb),
('essay', 2, null::int, null, null, 'n = 45.0 g ÷ 180.18 g/mol = 0.250 mol. الطاقة = 0.250 mol × 2808 kJ/mol = 701 kJ تنطلق (ΔH = −701 kJ). لا تختلف عن الطاقة المنطلقة في المسعر، لأن الجلوكوز في الحالتين يتفاعل مع الأكسجين وينتج CO₂ و H₂O، فالمتفاعلات والنواتج واحدة، والاختلاف فقط في أن الجسم ينفذ التفاعل في سلسلة خطوات ويخزن الطاقة في ATP.', '["n = 0.250 mol","الطاقة 701 kJ","لا تختلف الكمية","التعليل بتماثل المتفاعلات والنواتج"]'::jsonb, '["n = 45.0 g ÷ 180.18 g/mol = 0.250 mol","q = 0.250 mol × 2808 kJ/mol = 701 kJ","المقارنة بالمسعر: الكمية نفسها"]'::jsonb, '[{"element":"تحويل الكتلة إلى مولات","marks":1},{"element":"حساب الطاقة بالوحدة الصحيحة","marks":1},{"element":"الحكم بعدم الاختلاف","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4","description":"حساب صحيح وحكم صحيح معلل"},{"level":"3","description":"حساب صحيح وحكم صحيح دون تعليل"},{"level":"2","description":"حساب صحيح فقط"},{"level":"1","description":"تحويل صحيح إلى مولات فقط أو حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة مباشرة في 2808","الظن أن الجسم يطلق طاقة أقل لأن التفاعل بطيء","إهمال الأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-03T20:38:11.806Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المتفاعلات في الحالتين: الجلوكوز والأكسجين. النواتج في الحالتين: CO₂ و H₂O. الطاقة لكل 1 mol في الحالتين: 2808 kJ. الخطوات: في المسعر يحترق الجلوكوز مباشرة، وفي الخلايا يتكسر في سلسلة من الخطوات المعقدة. مصير الطاقة: في المسعر تنطلق حرارة يقيسها المسعر، وفي الخلايا تُخزن في صورة طاقة وضع كيميائية في روابط ATP لتطلقها عند الحاجة. المعادلة: C₆H₁₂O₆(s) + 6O₂(g) → 6CO₂(g) + 6H₂O(l)   ΔHcomb = −2808 kJ.', '["المتفاعلات واحدة","النواتج واحدة","الطاقة 2808 kJ لكل مول في الحالتين","المسعر خطوة مباشرة والخلايا سلسلة خطوات","الطاقة في الخلايا تُخزن في ATP","المعادلة الحرارية الموزونة بالحالات وإشارة ΔH"]'::jsonb, '[]'::jsonb, '[{"element":"المتفاعلات والنواتج","marks":1},{"element":"كمية الطاقة","marks":1},{"element":"عدد الخطوات","marks":1},{"element":"مصير الطاقة","marks":1},{"element":"المعادلة الحرارية","marks":1}]'::jsonb, '[{"level":"5","description":"مقارنة كاملة في الجوانب الخمسة مع معادلة صحيحة"},{"level":"4","description":"نقص جانب واحد أو خطأ في المعادلة"},{"level":"3","description":"مقارنة صحيحة في ثلاثة جوانب"},{"level":"1","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن نواتج التنفس الخلوي تختلف عن نواتج الاحتراق","الظن أن الجسم يطلق طاقة أقل","إشارة ΔH موجبة في المعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:38:11.806Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
