from (values
('mcq', 1, 'يحترق 90.0 g من الجلوكوز C₆H₁₂O₆ (الكتلة المولية 180.16 g/mol) احتراقًا كاملًا وفق المعادلة: C₆H₁₂O₆(s) + 6O₂(g) → 6CO₂(g) + 6H₂O(l)، ΔHcomb = −2808 kJ. ما كمية الحرارة المنطلقة؟', null, '["2.53×10⁵ kJ","1.40×10³ kJ","2808 kJ","5.62×10³ kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 29 — مثال 1-4: الحرارة المنطلقة من تفاعل'),
('mcq', 2, 'ما كمية الحرارة المنطلقة عند احتراق 32.0 g من غاز الميثان CH₄ (الكتلة المولية 16.04 g/mol) احتراقًا كاملًا، علمًا بأن ΔHcomb للميثان = −891 kJ/mol؟', null, '["2.85×10⁴ kJ","447 kJ","891 kJ","1.78×10³ kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 26 — جدول حرارة الاحتراق القياسية'),
('mcq', 3, 'ما كتلة البروبان C₃H₈ (الكتلة المولية 44.09 g/mol) التي يجب حرقها لإطلاق 5000 kJ من الحرارة، علمًا بأن ΔHcomb للبروبان = −2219 kJ/mol؟', null, '["99.4 g","2.25 g","19.6 g","0.0511 g"]'::jsonb, 'تطبيق', 'مسألة حسابية عكسية', 'صعب', 'الكتاب ص 43 — مسائل حرارة الاحتراق (73–76)'),
('mcq', 4, 'يتكثف 51.1 g من غاز الأمونيا NH₃ (الكتلة المولية 17.03 g/mol) إلى سائل عند درجة غليانه، علمًا بأن ΔHvap للأمونيا = 23.3 kJ/mol. ما كمية الحرارة المصاحبة لذلك؟', null, '["تُمتص 69.9 kJ","تنطلق 1.19×10³ kJ","تنطلق 69.9 kJ","تنطلق 17.0 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 29 — مسائل تدريبية (24)، وص 26 جدول حرارة التبخر والانصهار'),
('mcq', 5, 'يحترق 10.0 g من غاز الهيدروجين H₂ (الكتلة المولية 2.016 g/mol) وفق المعادلة: H₂(g) + ½O₂(g) → H₂O(l)، ΔHcomb = −286 kJ/mol. ما كمية الحرارة المنطلقة؟', null, '["2.86×10³ kJ","1.42×10³ kJ","57.7 kJ","14.2 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 30 — تقويم 1-3 (29)'),
('mcq', 6, 'لديك كتلة معلومة من مادة تحترق، وقيمة ΔHcomb لها بوحدة kJ/mol. ما الخطوة الأولى لحساب كمية الحرارة المنطلقة؟', null, '["ضرب الكتلة مباشرة في قيمة ΔHcomb","ضرب الكتلة في الكتلة المولية لإيجاد عدد المولات","قسمة قيمة ΔHcomb على كتلة المادة","قسمة الكتلة على الكتلة المولية لإيجاد عدد المولات"]'::jsonb, 'فهم', 'خطوات الحل', 'سهل', 'الكتاب ص 29 — مثال 1-4: الحرارة المنطلقة من تفاعل'),
('mcq', 7, 'يُحرق 10.0 g من الهيدروجين H₂ (2.016 g/mol؛ ΔHcomb = −286 kJ/mol) و10.0 g من الميثان CH₄ (16.04 g/mol؛ ΔHcomb = −891 kJ/mol) كلٌّ على حدة. أيّ العبارات الآتية صحيحة؟', null, '["الهيدروجين يطلق حرارة أكبر بنحو 2.6 مرة","الميثان يطلق حرارة أكبر بنحو 3.1 مرات","تنطلق من المادتين كمية الحرارة نفسها","الهيدروجين يطلق حرارة أكبر بنحو 8.0 مرات"]'::jsonb, 'تحليل', 'مقارنة حسابية', 'صعب', 'الكتاب ص 26 — جدول حرارة الاحتراق القياسية'),
('essay', 1, 'تُستعمل عينة من الفحم كتلتها 2.00 kg في التدفئة، ونسبة الكربون فيها 90.0% بالكتلة، والمواد الأخرى فيها لا تتفاعل. احسب كمية الحرارة المنطلقة عند احتراق الكربون الموجود فيها احتراقًا كاملًا، علمًا بأن ΔHcomb للكربون = −394 kJ/mol، والكتلة المولية للكربون 12.01 g/mol.', null, null, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'متوسط', 'الكتاب ص 43 — مسألة 74 (التدفئة باستعمال الفحم)'),
('essay', 2, 'تحتاج إلى 1.00×10³ kJ من الطاقة. احسب كتلة الجلوكوز C₆H₁₂O₆ (الكتلة المولية 180.16 g/mol) التي يلزم حرقها لإطلاق هذه الكمية، علمًا بأن ΔHcomb للجلوكوز = −2808 kJ/mol، ووضح خطوات الحل.', null, null, 'تطبيق', 'مسألة حسابية عكسية', 'متوسط', 'الكتاب ص 29 — مثال 1-4 ومسألة 25'),
('essay', 3, 'قارن بين الميثان CH₄ (16.04 g/mol؛ ΔHcomb = −891 kJ/mol) والبروبان C₃H₈ (44.09 g/mol؛ ΔHcomb = −2219 kJ/mol) من حيث الحرارة المنطلقة من احتراق 1 g من كل منهما. أيهما يطلق حرارة أكبر لكل مول، وأيهما يطلق حرارة أكبر لكل جرام؟ فسّر الفرق.', null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 26 — جدول حرارة الاحتراق القياسية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
