from (values
('mcq', 1, 'أيّ العبارات الآتية تعبّر عن قانون هس؟', null, '["حرارة التفاعل تتوقف على عدد الخطوات التي يتم فيها التفاعل، لا على طبيعة المواد المتفاعلة","الطاقة لا تفنى ولا تُستحدث، ولكن يمكن تحويلها من شكل إلى آخر في التفاعلات الكيميائية","حرارة التفاعل تتوقف على طبيعة المواد المتفاعلة والناتجة، لا على المسار الذي يتم فيه التفاعل","حرارة التفاعل تساوي دائمًا كمية الحرارة اللازمة لرفع درجة حرارة 1 g من الماء 1°C"]'::jsonb, 'تذكر', 'تذكر نص قانون', 'سهل', 'الكتاب ص 31 — قانون هس'),
('mcq', 2, 'وفق قانون هس، على أيّ مما يأتي تتوقف قيمة ΔH لتفاعل ما؟', null, '["طبيعة المواد المتفاعلة والمواد الناتجة","عدد الخطوات التي يمر بها التفاعل","سرعة حدوث التفاعل في المختبر","الأداة المستعملة في قياس الحرارة"]'::jsonb, 'تذكر', 'تذكر مضمون القانون', 'سهل', 'الكتاب ص 31 — قانون هس'),
('mcq', 3, 'يتحول الكربون من صورة الجرافيت إلى صورة الألماس تحولًا بطيئًا جدًا: C(s, جرافيت) → C(s, ألماس). لماذا يُلجأ إلى قانون هس لإيجاد ΔH لهذا التحول؟', null, '["لأن التحول يطلق كمية كبيرة جدًا من الحرارة تتلف المسعر","لأن الجرافيت والألماس عنصران مختلفان كيميائيًّا","لأن ΔH لهذا التحول تساوي صفرًا دائمًا","لأن بطء التحول الشديد يجعل قياس ΔH له عمليًّا مستحيلًا"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 31 — قانون هس'),
('mcq', 4, 'لماذا لا تُقاس ΔH لتفاعل 2S(s) + 3O₂(g) → 2SO₃(g) مباشرة في المختبر، ويُستعمل قانون هس بدلًا من ذلك؟', null, '["لأن الكبريت لا يتفاعل مع الأكسجين إطلاقًا","لأن التفاعل ينتج مخلوطًا من النواتج معظمه SO₂","لأن SO₃ مادة صلبة لا يمكن تسخينها","لأن ΔH لهذا التفاعل موجبة وكبيرة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 31 — قانون هس'),
('mcq', 5, 'يتحول المركب A إلى المركب C مباشرة بتغير في المحتوى الحراري ΔH، أو على خطوتين: A → B بتغير ΔH₁، ثم B → C بتغير ΔH₂. وفق قانون هس، ما العلاقة الصحيحة؟', null, '["ΔH = ΔH₁ − ΔH₂","ΔH = ΔH₁ × ΔH₂","ΔH = ΔH₁ + ΔH₂","ΔH = 2(ΔH₁ + ΔH₂)"]'::jsonb, 'فهم', 'تطبيق مفهوم القانون', 'متوسط', 'الكتاب ص 32 — تطبيق قانون هس (تكوين SO₃)'),
('mcq', 6, 'أيّ مما يأتي يمكن تحقيقه باستعمال قانون هس؟', null, '["حساب ΔH لتفاعل بجمع معادلتين حراريتين أو أكثر مع تغيرات المحتوى الحراري لها","حساب سرعة التفاعل الكيميائي بجمع سرعات تفاعلات أبسط منه","تحويل التفاعل الطارد للحرارة إلى تفاعل ماص للحرارة في الظروف نفسها","قياس الحرارة النوعية للمادة بالمسعر دون معرفة كتلتها"]'::jsonb, 'تذكر', 'تذكر استعمال القانون', 'سهل', 'الكتاب ص 41 — دليل مراجعة الفصل (1-4)'),
('mcq', 7, 'يُحضَّر غاز CO₂ من الكربون والأكسجين بطريقتين: الأولى حرق الكربون مباشرة إلى CO₂، والثانية حرقه أولًا إلى CO ثم حرق CO إلى CO₂. ما العلاقة بين كميتي الحرارة المنطلقتين في الطريقتين عند إنتاج الكمية نفسها من CO₂؟', null, '["الطريقة الثانية تطلق حرارة أكبر؛ لأنها تتم على خطوتين","الطريقة الأولى تطلق حرارة أكبر؛ لأنها أسرع وأكثر مباشرة","لا يمكن المقارنة إلا بقياس الطريقتين بالمسعر","متساويتان؛ لأن المواد الابتدائية والنهائية واحدة في الطريقتين"]'::jsonb, 'فهم', 'تفسير ظاهرة بالقانون', 'صعب', 'الكتاب ص 31 — قانون هس'),
('essay', 1, 'عرّف قانون هس، واذكر سببين يدفعان الكيميائيين إلى استعماله بدلًا من قياس ΔH للتفاعل مباشرة، مع مثال لكل سبب.', null, null, 'تذكر', 'تعريف وتعليل', 'سهل', 'الكتاب ص 31 — قانون هس'),
('essay', 2, 'يتكوّن SO₃ من الكبريت على خطوتين: 2S(s) + 2O₂(g) → 2SO₂(g)، ΔH = −594 kJ، ثم 2SO₂(g) + O₂(g) → 2SO₃(g)، ΔH = −198 kJ. والتفاعل الكلي: 2S(s) + 3O₂(g) → 2SO₃(g)، ΔH = −792 kJ. وضّح كيف تمثل هذه البيانات قانون هس، وماذا تتوقع لقيمة ΔH لو أمكن إجراء التفاعل الكلي في خطوة واحدة؟', null, null, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 32 — تطبيق قانون هس (تكوين SO₃)'),
('essay', 3, 'تُعطى المعادلات الحرارية الآتية: C(s) + ½O₂(g) → CO(g)، ΔH = −111 kJ؛ CO(g) + ½O₂(g) → CO₂(g)، ΔH = −283 kJ؛ C(s) + O₂(g) → CO₂(g)، ΔH = −394 kJ. ادّعى طالب أن تحويل الكربون إلى CO₂ على خطوتين عبر CO يطلق حرارة أكبر من حرق الكربون مباشرة؛ لأن هناك تفاعلين يطلق كل منهما حرارة. قوّم ادعاء الطالب مستعينًا بقانون هس والبيانات.', null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 31–32 — قانون هس وتطبيقه')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
