from (values
('mcq', 1, 2, 'ينص قانون هس على أن حرارة التفاعل أو التغير في المحتوى الحراري تتوقف على طبيعة المواد الداخلة في التفاعل والمواد الناتجة منه، وليس على الخطوات أو المسار الذي يتم فيه التفاعل.', '["هذا عكس القانون؛ فالحرارة لا تتوقف على عدد الخطوات أو المسار.","هذا نص قانون حفظ الطاقة، وليس قانون هس.","","هذا تعريف السُّعر (cal)، ولا علاقة له بقانون هس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.811Z"}'::jsonb),
('mcq', 2, 0, 'ΔH تتوقف على طبيعة المواد الداخلة في التفاعل والناتجة منه فقط؛ فإذا تساوت المواد الابتدائية والنهائية تساوت ΔH مهما اختلف المسار.', '["","قانون هس ينص صراحة على أن ΔH لا تتوقف على الخطوات أو المسار.","سرعة التفاعل لا تغير ΔH؛ فتحول الجرافيت إلى ألماس بطيء جدًا ومع ذلك له ΔH محددة.","ΔH خاصية للتفاعل نفسه، ولا تتغير بتغير أداة القياس أو طريقة الحساب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.812Z"}'::jsonb),
('mcq', 3, 3, 'يحدث تحول الجرافيت إلى ألماس ببطء شديد، مما يجعل من المستحيل قياس التغير في محتواه الحراري مباشرة بالمسعر؛ لذا تُحسب ΔH نظريًا بقانون هس من تفاعلات أخرى معروفة.', '["سبب اللجوء إلى قانون هس هو بطء التحول، لا كبر الحرارة المنطلقة.","الجرافيت والألماس صورتان متآصلتان لعنصر واحد هو الكربون، لا عنصران مختلفان.","ΔH لهذا التحول ليست صفرًا؛ فالجرافيت والألماس صورتان مختلفتان في المحتوى الحراري، وتختلف حرارة احتراق كل منهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:38:11.812Z"}'::jsonb),
('mcq', 4, 1, 'التجارب المخبرية لإنتاج SO₃ من الكبريت ينتج عنها مخلوط من النواتج معظمه SO₂، فلا يمكن قياس ΔH للتفاعل المطلوب وحده؛ لذا تُحسب بجمع معادلات حرارية معروفة وفق قانون هس.', '["الكبريت يتفاعل مع الأكسجين، لكنه ينتج في الغالب SO₂ بدل SO₃.","","SO₃ في هذا التفاعل غاز، والسبب الحقيقي هو تكوّن مخلوط من النواتج.","ΔH لهذا التفاعل سالبة (−792 kJ)، وليست الإشارة سبب صعوبة القياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.812Z"}'::jsonb),
('mcq', 5, 2, 'لأن ΔH لا تتوقف على المسار، فإن جمع المعادلتين A → B وB → C يعطي A → C، وتكون ΔH للتفاعل المباشر مساوية لمجموع ΔH₁ وΔH₂.', '["المعادلتان تُجمعان كما هما للحصول على A → C، فتُجمع قيمتا ΔH لا تُطرحان.","لا تُضرب قيم ΔH في بعضها؛ بل تُجمع عند جمع المعادلات.","","لا يوجد ما يستدعي الضرب في 2؛ فالمعادلتان تُجمعان مرة واحدة لتعطيا A → C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:38:11.813Z"}'::jsonb),
('mcq', 6, 0, 'يمكن حساب التغير في المحتوى الحراري لتفاعل بجمع معادلتين كيميائيتين حراريتين أو أكثر مع تغيرات المحتوى الحراري لها، وهذا هو تطبيق قانون هس.', '["","قانون هس يتعلق بالتغير في المحتوى الحراري لا بسرعة التفاعل.","قانون هس أداة حسابية لإيجاد ΔH، ولا يغير طبيعة التفاعل.","الحرارة النوعية تُحسب من q = c × m × ΔT وتحتاج إلى الكتلة، ولا علاقة لقانون هس بها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.813Z"}'::jsonb),
('mcq', 7, 3, 'وفق قانون هس تتوقف ΔH على طبيعة المواد المتفاعلة (C وO₂) والناتجة (CO₂) فقط، وهي واحدة في الطريقتين، فتتساوى كميتا الحرارة المنطلقتين.', '["زيادة عدد الخطوات لا تزيد الحرارة؛ فـ ΔH لا تتوقف على المسار.","سرعة الطريقة أو كونها مباشرة لا تغير ΔH ما دامت المواد الابتدائية والنهائية واحدة.","قانون هس يتيح المقارنة دون قياس؛ فالحرارتان متساويتان حتمًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:38:11.813Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قانون هس: حرارة التفاعل أو التغير في المحتوى الحراري تتوقف على طبيعة المواد الداخلة في التفاعل والمواد الناتجة منه، وليس على الخطوات أو المسار الذي يتم فيه التفاعل. من أسباب استعماله: (1) بعض التفاعلات بطيئة جدًا فيستحيل قياس ΔH لها، مثل تحول الجرافيت إلى ألماس. (2) بعض التفاعلات تعطي نواتج غير مطلوبة أو مخلوطًا من النواتج، مثل تفاعل الكبريت مع الأكسجين الذي ينتج معظمه SO₂ بدل SO₃. وقد يصعب إيجاد الظروف المناسبة لبعض التفاعلات في المختبر.', '["نص قانون هس كاملًا (المواد المتفاعلة والناتجة، لا المسار)","السبب الأول: بطء التفاعل الشديد","مثال: الجرافيت → الألماس","السبب الثاني: تكوّن نواتج غير مطلوبة أو مخلوط","مثال: الكبريت مع الأكسجين ينتج معظمه SO₂"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":2},{"element":"السبب الأول ومثاله","marks":1},{"element":"السبب الثاني ومثاله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وسببان صحيحان مع مثالين."},{"level":"2–3 درجات","description":"تعريف صحيح مع سبب واحد، أو سببان مع تعريف ناقص."},{"level":"1 درجة","description":"تعريف ناقص فقط أو سبب واحد دون تعريف."},{"level":"صفر","description":"لا إجابة أو تعريف قانون آخر."}]'::jsonb, '["الخلط بين قانون هس وقانون حفظ الطاقة","القول إن ΔH تتوقف على عدد الخطوات","ذكر أسباب لا علاقة لها بصعوبة القياس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-03T20:38:11.813Z"}'::jsonb),
('essay', 2, null::int, null, null, 'جمع الخطوتين يلغي 2SO₂ من الطرفين فيعطي التفاعل الكلي، ومجموع قيمتي ΔH (−594 kJ) + (−198 kJ) = −792 kJ يساوي ΔH للتفاعل الكلي. ولو أُجري التفاعل في خطوة واحدة لكانت ΔH = −792 kJ أيضًا؛ لأن المواد المتفاعلة (2S و3O₂) والناتجة (2SO₃) هي نفسها، وΔH وفق قانون هس لا تتوقف على المسار.', '["جمع المعادلتين وحذف SO₂ المشترك","جمع قيمتي ΔH يساوي −792 kJ","توقع ΔH = −792 kJ للخطوة الواحدة","التعليل بعدم اعتماد ΔH على المسار"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن جمع المعادلتين يعطي التفاعل الكلي","marks":1},{"element":"بيان أن مجموع ΔH يساوي ΔH الكلية","marks":1},{"element":"التوقع الصحيح","marks":1},{"element":"التعليل بقانون هس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شرح كامل للجمع والتوقع والتعليل."},{"level":"2–3 درجات","description":"شرح الجمع صحيح مع تعليل ناقص أو توقع دون تعليل."},{"level":"1 درجة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["توقع قيمة مختلفة لأن التفاعل في خطوة واحدة","طرح القيمتين بدل جمعهما","عدم ملاحظة حذف 2SO₂ من الطرفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:38:11.814Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الادعاء خاطئ. جمع الخطوتين يلغي CO فيعطي C(s) + O₂(g) → CO₂(g)، ومجموع الحرارة (−111 kJ) + (−283 kJ) = −394 kJ، وهي القيمة نفسها لحرق الكربون مباشرة. فالحرارة الكلية واحدة في المسارين؛ لأن ΔH وفق قانون هس تتوقف على طبيعة المواد المتفاعلة والناتجة فقط لا على عدد الخطوات، وكل خطوة تطلق جزءًا من الحرارة الكلية فقط.', '["الحكم بأن الادعاء خاطئ","جمع المعادلتين وحذف CO","حساب المجموع −394 kJ ومقارنته بالحرق المباشر","التعليل بقانون هس (عدم الاعتماد على المسار)"]'::jsonb, '["(−111 kJ) + (−283 kJ) = −394 kJ","مقارنة: −394 kJ للمسارين"]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"الجمع والحساب","marks":2},{"element":"التعليل بقانون هس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مدعوم بالحساب والتعليل بقانون هس."},{"level":"2–3 درجات","description":"حكم صحيح مع حساب دون تعليل، أو تعليل دون حساب."},{"level":"1 درجة","description":"حكم صحيح دون دعم."},{"level":"صفر","description":"لا إجابة أو تأييد الادعاء."}]'::jsonb, '["تأييد الادعاء لأن عدد الخطوات أكبر","جمع القيم الثلاث كلها","طرح القيمتين بدل جمعهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:38:11.814Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
