from (values
('mcq', 1, 'استعمل المعادلتين الحراريتين: (a) S(s) + O₂(g) → SO₂(g)، ΔH = −297 kJ؛ (b) 2SO₃(g) → 2SO₂(g) + O₂(g)، ΔH = +198 kJ. ما قيمة ΔH للتفاعل: S(s) + 3/2O₂(g) → SO₃(g)؟', null, '["−495 kJ","−198 kJ","−792 kJ","−396 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 32 — تطبيق قانون هس (تكوين SO₃)'),
('mcq', 2, 'استعمل المعادلتين: (a) C(s, جرافيت) + O₂(g) → CO₂(g)، ΔH = −394 kJ؛ (b) C(s, ألماس) + O₂(g) → CO₂(g)، ΔH = −396 kJ. ما قيمة ΔH للتحول: C(s, جرافيت) → C(s, ألماس)؟', null, '["−2 kJ","+2 kJ","−790 kJ","0 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 44 — تقويم الفصل (80، 83، 84)'),
('mcq', 3, 'استعمل المعادلتين: (a) P₄(s) + 6Cl₂(g) → 4PCl₃(l)، ΔH = −1280 kJ؛ (b) P₄(s) + 10Cl₂(g) → 4PCl₅(s)، ΔH = −1774 kJ. ما قيمة ΔH للتفاعل: PCl₃(l) + Cl₂(g) → PCl₅(s)؟', null, '["−494 kJ","+123.5 kJ","−123.5 kJ","−763.5 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'صعب', 'الكتاب ص 44 — تقويم الفصل (80، 83، 84)'),
('mcq', 4, 'استعمل المعادلتين: (a) 2H₂(g) + O₂(g) → 2H₂O(l)، ΔH = −572 kJ؛ (b) H₂(g) + O₂(g) → H₂O₂(l)، ΔH = −188 kJ. ما قيمة ΔH للتفاعل: H₂O₂(l) → H₂O(l) + ½O₂(g)؟', null, '["−98 kJ","−196 kJ","−384 kJ","−474 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 33 — مثال 1-5: تحلل فوق أكسيد الهيدروجين'),
('mcq', 5, 'يُراد حساب ΔH للتفاعل C₂H₄(g) + H₂(g) → C₂H₆(g) من المعادلات: (a) C₂H₄(g) + 3O₂(g) → 2CO₂(g) + 2H₂O(l)؛ (b) C₂H₆(g) + 7/2O₂(g) → 2CO₂(g) + 3H₂O(l)؛ (c) H₂(g) + ½O₂(g) → H₂O(l). ما الإجراء الصحيح؟', null, '["استعمال a وb كما هما، وعكس c","عكس a وc، واستعمال b كما هي","استعمال المعادلات الثلاث كما هي","استعمال a وc كما هما، وعكس b"]'::jsonb, 'تحليل', 'تخطيط الحل', 'سهل', 'الكتاب ص 32 — تطبيق قانون هس (تكوين SO₃)'),
('mcq', 6, 'استعمل المعادلتين: (a) ½N₂(g) + ½O₂(g) → NO(g)، ΔH = +91.3 kJ؛ (b) NO(g) + ½O₂(g) → NO₂(g)، ΔH = −58.1 kJ. ما قيمة ΔH للتفاعل: ½N₂(g) + O₂(g) → NO₂(g)؟', null, '["−33.2 kJ","+149.4 kJ","+33.2 kJ","−149.4 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 38 — مسائل تدريبية (37) وتقويم 1-4 (42)'),
('mcq', 7, 'استعمل المعادلتين: (a) 2A + 3/2C₂ → A₂C₃، ΔH = −1874 kJ؛ (b) 2B + 3/2C₂ → B₂C₃، ΔH = −285 kJ. ما قيمة ΔH للتفاعل: 2A + B₂C₃ → 2B + A₂C₃؟', null, '["−2159 kJ","−1589 kJ","+1589 kJ","−1304 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 44 — تقويم الفصل (80، 83، 84)'),
('essay', 1, 'استعمل المعادلتين الحراريتين: (a) 2CO(g) + O₂(g) → 2CO₂(g)، ΔH = −566.0 kJ؛ (b) N₂(g) + O₂(g) → 2NO(g)، ΔH = −180.6 kJ، لحساب ΔH للتفاعل: 2CO(g) + 2NO(g) → 2CO₂(g) + N₂(g). وضح كل خطوة.', null, null, 'تطبيق', 'مسألة حسابية بالخطوات', 'متوسط', 'الكتاب ص 34 — مسائل تدريبية (32–33)'),
('essay', 2, 'إذا علمت أن: 4Al(s) + 3MnO₂(s) → 2Al₂O₃(s) + 3Mn(s)، ΔH = −1789 kJ، وأن (a) 4Al(s) + 3O₂(g) → 2Al₂O₃(s)، ΔH = −3352 kJ، فاحسب ΔH للتفاعل: (b) Mn(s) + O₂(g) → MnO₂(s).', null, null, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'صعب', 'الكتاب ص 34 — مسائل تدريبية (32–33)'),
('essay', 3, 'استعمل قانون هس لإيجاد ΔH للتفاعل: NO(g) + O(g) → NO₂(g)، مستعينًا بالتفاعلات الآتية: O₂(g) → 2O(g)، ΔH = +495 kJ؛ 2O₃(g) → 3O₂(g)، ΔH = −427 kJ؛ NO(g) + O₃(g) → NO₂(g) + O₂(g)، ΔH = −199 kJ.', null, null, 'تحليل', 'مسألة حسابية متعددة الخطوات', 'صعب', 'الكتاب ص 38 — مسائل تدريبية (37) وتقويم 1-4 (42)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'نستعمل a كما هي (−297 kJ)، ونعكس b ونقسمها على 2: SO₂(g) + ½O₂(g) → SO₃(g)، ΔH = −99 kJ. وبالجمع: ΔH = −297 kJ + (−99 kJ) = −396 kJ.', '["عُكست المعادلة b دون قسمتها على 2؛ والمطلوب 1 mol من SO₃ فقط، أي نصف المعادلة b معكوسة (−99 kJ).","قُسمت المعادلة b على 2 دون عكسها (+99 kJ)؛ وSO₃ ناتج في المعادلة المطلوبة فيجب عكس b وتغيير الإشارة.","هذه ΔH لتكوين 2 mol من SO₃؛ والمعادلة المطلوبة لمول واحد فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.815Z"}'::jsonb),
('mcq', 2, 1, 'نستعمل a كما هي، ونعكس b: CO₂(g) → C(s, ألماس) + O₂(g)، ΔH = +396 kJ. وبالجمع يُحذف CO₂ وO₂: ΔH = −394 kJ + 396 kJ = +2 kJ.', '["عُكست المعادلة a بدل b؛ والجرافيت مادة متفاعلة في المعادلة المطلوبة فتُستعمل a كما هي وتُعكس b.","","جُمعت المعادلتان كما هما دون عكس b؛ وهذا لا يعطي المعادلة المطلوبة.","الجرافيت والألماس صورتان للكربون لكن محتواهما الحراري مختلف، فالفرق بين حرارتي احتراقهما ليس صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:38:11.815Z"}'::jsonb),
('mcq', 3, 2, 'نعكس a: 4PCl₃(l) → P₄(s) + 6Cl₂(g)، ΔH = +1280 kJ، ونجمعها مع b فنحصل على 4PCl₃ + 4Cl₂ → 4PCl₅، ΔH = −494 kJ، ثم نقسم على 4: ΔH = −123.5 kJ.', '["هذه ΔH للتفاعل 4PCl₃ + 4Cl₂ → 4PCl₅؛ ولم تُقسم على 4 للحصول على مول واحد.","عُكست المعادلة b بدل a؛ وPCl₅ ناتج فتُستعمل b كما هي وتُعكس a.","","جُمعت المعادلتان كما هما ثم قُسم الناتج على 4، دون عكس المعادلة a."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-03T20:38:11.815Z"}'::jsonb),
('mcq', 4, 0, 'نقسم a على 2: H₂ + ½O₂ → H₂O(l)، ΔH = −286 kJ، ونعكس b: H₂O₂(l) → H₂ + O₂، ΔH = +188 kJ. وبالجمع: ΔH = −286 kJ + 188 kJ = −98 kJ.', '["","هذه ΔH لتحلل 2 mol من H₂O₂؛ والمعادلة المطلوبة لمول واحد.","عُكست b لكن لم تُقسم a على 2؛ والمطلوب 1 mol من H₂O فقط.","قُسمت a على 2 لكن لم تُعكس b؛ وH₂O₂ مادة متفاعلة فيجب عكس b وتغيير إشارتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-03T20:38:11.816Z"}'::jsonb),
('mcq', 5, 3, 'C₂H₄ وH₂ متفاعلان في المعادلة المطلوبة كما في a وc فتُستعملان كما هما، وC₂H₆ ناتج بينما هو متفاعل في b فتُعكس b. وعند الجمع يُحذف 2CO₂ و3H₂O و7/2O₂ من الطرفين.', '["C₂H₆ ناتج في المعادلة المطلوبة، وهو متفاعل في b، فيجب عكس b لا c.","C₂H₄ وH₂ متفاعلان في المعادلة المطلوبة وهما متفاعلان في a وc، فلا تُعكسان.","جمع المعادلات كما هي يجعل C₂H₆ متفاعلًا، والمطلوب أن يكون ناتجًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:38:11.816Z"}'::jsonb),
('mcq', 6, 2, 'تُجمع المعادلتان كما هما فيُحذف NO: ½N₂ + O₂ → NO₂، وΔH = 91.3 kJ + (−58.1 kJ) = +33.2 kJ.', '["الإشارة معكوسة؛ فالمعادلتان تُجمعان كما هما، ومجموعهما 91.3 + (−58.1) قيمة موجبة.","عُكست المعادلة b (+58.1 kJ) دون داعٍ؛ فـ NO₂ ناتج فيها كما في المعادلة المطلوبة.","","عُكست المعادلة a (−91.3 kJ) دون داعٍ؛ فـ N₂ متفاعل فيها كما في المعادلة المطلوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-03T20:38:11.816Z"}'::jsonb),
('mcq', 7, 1, 'نستعمل a كما هي، ونعكس b: B₂C₃ → 2B + 3/2C₂، ΔH = +285 kJ. وبالجمع يُحذف 3/2C₂: ΔH = −1874 kJ + 285 kJ = −1589 kJ.', '["جُمعت المعادلتان كما هما؛ وB₂C₃ متفاعل في المعادلة المطلوبة فيجب عكس b.","","عُكست المعادلة a بدل b؛ وA₂C₃ ناتج فتُستعمل a كما هي.","ضُربت المعادلة b المعكوسة في 2 دون داعٍ؛ فالمعادلة المطلوبة تحتوي 1 mol من B₂C₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-03T20:38:11.816Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المعادلة a تحتوي 2CO متفاعلًا و2CO₂ ناتجًا كما في المعادلة المطلوبة، فتُستعمل كما هي (ΔH = −566.0 kJ). وNO متفاعل في المطلوبة لكنه ناتج في b، فتُعكس b: 2NO(g) → N₂(g) + O₂(g)، ΔH = +180.6 kJ. وبالجمع يُحذف O₂ من الطرفين: 2CO + 2NO → 2CO₂ + N₂، ΔH = −566.0 kJ + 180.6 kJ = −385.4 kJ.', '["استعمال a كما هي مع التعليل","عكس b وتغيير إشارة ΔH إلى +180.6 kJ","جمع المعادلتين وحذف O₂","الناتج ΔH = −385.4 kJ"]'::jsonb, '["a كما هي: ΔH = −566.0 kJ","عكس b: 2NO → N₂ + O₂، ΔH = +180.6 kJ","الجمع: 2CO + 2NO → 2CO₂ + N₂","ΔH = −566.0 + 180.6 = −385.4 kJ"]'::jsonb, '[{"element":"التعامل الصحيح مع a","marks":1},{"element":"عكس b وتغيير الإشارة","marks":1},{"element":"الجمع وحذف المواد المشتركة","marks":1},{"element":"القيمة النهائية مع الوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات صحيحة كاملة والناتج −385.4 kJ."},{"level":"2–3 درجات","description":"عكس صحيح مع خطأ حسابي أو حذف ناقص."},{"level":"1 درجة","description":"تحديد المعادلة التي تُعكس فقط."},{"level":"صفر","description":"لا إجابة أو جمع المعادلتين دون أي معالجة."}]'::jsonb, '["عكس b دون تغيير الإشارة (−746.6 kJ)","عكس a بدل b","نسيان حذف O₂ من الطرفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:38:11.817Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نعكس التفاعل المعطى: 2Al₂O₃(s) + 3Mn(s) → 4Al(s) + 3MnO₂(s)، ΔH = +1789 kJ، ونجمعه مع a كما هي فيُحذف 4Al و2Al₂O₃: 3Mn(s) + 3O₂(g) → 3MnO₂(s)، ΔH = −3352 kJ + 1789 kJ = −1563 kJ. ثم نقسم على 3: Mn(s) + O₂(g) → MnO₂(s)، ΔH = −521 kJ.', '["عكس التفاعل المعطى وتغيير إشارته","جمعه مع a وحذف Al وAl₂O₃","الحصول على 3Mn + 3O₂ → 3MnO₂ بـ ΔH = −1563 kJ","القسمة على 3 والناتج −521 kJ"]'::jsonb, '["عكس التفاعل المعطى: ΔH = +1789 kJ","الجمع مع a: ΔH = −3352 + 1789 = −1563 kJ لـ 3 mol MnO₂","القسمة على 3: ΔH = −1563 ÷ 3 = −521 kJ"]'::jsonb, '[{"element":"العكس وتغيير الإشارة","marks":1},{"element":"الجمع والحذف","marks":1},{"element":"القيمة −1563 kJ","marks":1},{"element":"القسمة على 3 والناتج −521 kJ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح بالخطوات والناتج −521 kJ."},{"level":"2–3 درجات","description":"الوصول إلى −1563 kJ دون القسمة على 3، أو خطأ في الإشارة في خطوة واحدة."},{"level":"1 درجة","description":"عكس صحيح للتفاعل فقط."},{"level":"صفر","description":"لا إجابة أو حل خاطئ كليًا."}]'::jsonb, '["نسيان القسمة على 3","عكس a بدل التفاعل المعطى","عدم تغيير الإشارة عند العكس (−1714 kJ)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-03T20:38:11.817Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نستعمل المعادلة الثالثة كما هي (ΔH = −199 kJ). نعكس الثانية ونقسمها على 2: 3/2O₂(g) → O₃(g)، ΔH = +213.5 kJ. نعكس الأولى ونقسمها على 2: O(g) → ½O₂(g)، ΔH = −247.5 kJ. وبالجمع يُحذف O₃ و3/2O₂ فيبقى: NO(g) + O(g) → NO₂(g)، ΔH = −199 + 213.5 − 247.5 = −233 kJ.', '["استعمال المعادلة الثالثة كما هي","عكس الثانية وقسمتها على 2 (+213.5 kJ)","عكس الأولى وقسمتها على 2 (−247.5 kJ)","الجمع والتحقق من حذف O₃ وO₂","الناتج −233 kJ"]'::jsonb, '["NO + O₃ → NO₂ + O₂، ΔH = −199 kJ","3/2O₂ → O₃، ΔH = +427 ÷ 2 = +213.5 kJ","O → ½O₂، ΔH = −495 ÷ 2 = −247.5 kJ","المجموع: NO + O → NO₂، ΔH = −199 + 213.5 − 247.5 = −233 kJ"]'::jsonb, '[{"element":"معالجة المعادلة الثالثة","marks":1},{"element":"معالجة المعادلة الثانية","marks":1},{"element":"معالجة المعادلة الأولى","marks":1},{"element":"الجمع والحذف","marks":1},{"element":"القيمة النهائية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معالجة صحيحة للمعادلات الثلاث والناتج −233 kJ."},{"level":"3–4 درجات","description":"معالجة صحيحة لمعادلتين مع خطأ في الثالثة أو في الحساب."},{"level":"1–2 درجة","description":"معالجة صحيحة لمعادلة واحدة."},{"level":"صفر","description":"لا إجابة أو حل خاطئ."}]'::jsonb, '["عكس المعادلة دون قسمتها على 2","عدم تغيير الإشارة عند العكس","عدم التحقق من حذف O₂ وO₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-03T20:38:11.818Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
