from (values
('mcq', 1, 'احسب ΔH°rxn للتفاعل: CO(g) + ½O₂(g) → CO₂(g)، علمًا بأن ΔH°f(CO) = −111 kJ/mol وΔH°f(CO₂) = −394 kJ/mol.', null, '["+283 kJ","−283 kJ","−505 kJ","−394 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 37 — معادلة التجميع ومثال 1-6'),
('mcq', 2, 'احسب ΔH°rxn للتفاعل: 2SO₂(g) + O₂(g) → 2SO₃(g)، علمًا بأن ΔH°f(SO₂) = −297 kJ/mol وΔH°f(SO₃) = −396 kJ/mol.', null, '["−99 kJ","+198 kJ","−1386 kJ","−198 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 37 — معادلة التجميع ومثال 1-6'),
