from (values
('mcq', 1, 1, 'ΔH°rxn = ΔH°f(CO₂) − [ΔH°f(CO) + ½ΔH°f(O₂)] = −394 − [−111 + 0.0] = −283 kJ.', '["طُرحت حرارة تكوين النواتج من المتفاعلات؛ والصحيح Σ(النواتج) − Σ(المتفاعلات).","","جُمعت حرارة تكوين CO مع CO₂ بدل طرحها.","أُهملت حرارة تكوين المتفاعل CO، واعتُبرت ΔH°rxn مساوية لحرارة تكوين CO₂ وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-03T20:38:11.821Z"}'::jsonb),
('mcq', 2, 3, 'ΔH°rxn = 2ΔH°f(SO₃) − [2ΔH°f(SO₂) + ΔH°f(O₂)] = 2(−396) − [2(−297) + 0.0] = −792 + 594 = −198 kJ.', '["لم تُضرب حرارة التكوين في المعامل 2 لكل من SO₂ وSO₃؛ وهذه قيمة تكوين 1 mol من SO₃.","طُرحت حرارة تكوين النواتج من المتفاعلات، فانعكست الإشارة.","جُمعت حرارة تكوين المتفاعلات والنواتج معًا بدل طرح المتفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-03T20:38:11.822Z"}'::jsonb),
('mcq', 3, 2, 'ΔH°rxn = [2(−273) + (−1220)] − [(−21) + 4(0.0)] = −1766 + 21 = −1745 kJ؛ وحرارة تكوين F₂ صفر لأنه عنصر في حالته القياسية.', '["لم تُضرب حرارة تكوين HF في معامله 2.","أُضيفت حرارة تكوين H₂S إلى النواتج بدل طرحها.","","طُرحت النواتج من المتفاعلات فانعكست الإشارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-03T20:38:11.822Z"}'::jsonb),
('mcq', 4, 0, 'ΔH°rxn = [4(+33.2) + 6(−286)] − [4(−46) + 7(0.0)] = (132.8 − 1716) − (−184) = −1583.2 + 184 = −1399 kJ.', '["","أُضيفت حرارة تكوين NH₃ بدل طرحها (خطأ في إشارة طرح المتفاعلات).","أُهملت المعاملات (4 و6 و4) واستُعملت حرارة تكوين مول واحد من كل مادة.","طُرحت النواتج من المتفاعلات فانعكست الإشارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.822Z"}'::jsonb),
('mcq', 5, 2, 'وفق معادلة التجميع: ΔH°rxn = ΣΔH°f(النواتج) − ΣΔH°f(المتفاعلات)، مع ضرب كل قيمة في معامل المادة في المعادلة الموزونة.', '["هذه العلاقة تطرح النواتج من المتفاعلات، وهي عكس معادلة التجميع.","أُهملت المعاملات؛ وكل حرارة تكوين يجب أن تُضرب في معامل المادة في المعادلة الموزونة.","","تُطرح حرارة تكوين المتفاعلات ولا تُجمع مع النواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-03T20:38:11.823Z"}'::jsonb),
('mcq', 6, 3, 'من معادلة التجميع: −1367 = [2(−394) + 3(−286)] − [ΔH°f(C₂H₅OH) + 3(0.0)]، أي −1367 = −1646 − ΔH°f(C₂H₅OH)، فتكون ΔH°f(C₂H₅OH) = −1646 + 1367 = −279 kJ/mol.', '["طُرحت ΣΔH°f للنواتج من ΔH°comb بدل العكس، فانعكست الإشارة.","هذه ΣΔH°f للنواتج فقط [2(−394) + 3(−286)]، ولم تُستعمل قيمة ΔH°comb.","جُمعت ΔH°comb مع ΣΔH°f للنواتج بدل طرحها منها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.823Z"}'::jsonb),
('mcq', 7, 0, 'ΔH°rxn = ΔH°f(P₄O₁₀) − [ΔH°f(P₄O₆) + 2(0.0)] = −2984 − (−1640) = −1344 kJ.', '["","جُمعت حرارتا التكوين بدل طرح حرارة تكوين المتفاعل.","طُرحت النواتج من المتفاعلات فانعكست الإشارة.","أُهملت حرارة تكوين المتفاعل P₄O₆ واعتُبرت صفرًا كأنه عنصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-03T20:38:11.823Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ΔH°rxn = [4ΔH°f(CO₂) + 4ΔH°f(H₂O)] − [ΔH°f(C₃H₇COOH) + 5ΔH°f(O₂)] = [4(−394) + 4(−286)] − [(−534) + 5(0.0)] = (−1576 − 1144) + 534 = −2720 + 534 = −2186 kJ. إذن ΔH°comb لحمض البيوتانويك = −2186 kJ/mol.', '["كتابة معادلة التجميع","ΔH°f لـ O₂ = 0","حساب مجموع النواتج −2720 kJ","طرح المتفاعلات والناتج −2186 kJ/mol"]'::jsonb, '["ΣΔH°f(النواتج) = 4(−394) + 4(−286) = −2720 kJ","ΣΔH°f(المتفاعلات) = −534 + 5(0.0) = −534 kJ","ΔH°comb = −2720 − (−534) = −2186 kJ"]'::jsonb, '[{"element":"معادلة التجميع","marks":1},{"element":"مجموع النواتج","marks":1},{"element":"مجموع المتفاعلات","marks":1},{"element":"الناتج النهائي بالوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح والناتج −2186 kJ/mol."},{"level":"2–3 درجات","description":"طريقة صحيحة مع خطأ حسابي أو في معامل."},{"level":"1 درجة","description":"كتابة معادلة التجميع فقط."},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة."}]'::jsonb, '["جمع حرارة تكوين الحمض بدل طرحها (−3254 kJ)","إهمال المعاملات 4","إعطاء O₂ قيمة غير الصفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-03T20:38:11.823Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ΔH°rxn = [4(−394) + 6(−286)] − [2(−84) + 7(0.0)] = (−1576 − 1716) + 168 = −3292 + 168 = −3124 kJ. وهذه القيمة لاحتراق 2 mol من الإيثان، فحرارة الاحتراق لمول واحد = −3124 ÷ 2 = −1562 kJ/mol.', '["تطبيق معادلة التجميع مع المعاملات","مجموع النواتج −3292 kJ","مجموع المتفاعلات −168 kJ","ΔH°rxn = −3124 kJ","القسمة على 2: −1562 kJ/mol"]'::jsonb, '["ΣΔH°f(النواتج) = 4(−394) + 6(−286) = −3292 kJ","ΣΔH°f(المتفاعلات) = 2(−84) + 7(0.0) = −168 kJ","ΔH°rxn = −3292 − (−168) = −3124 kJ","ΔH°comb = −3124 ÷ 2 = −1562 kJ/mol"]'::jsonb, '[{"element":"مجموع النواتج","marks":1},{"element":"مجموع المتفاعلات","marks":1},{"element":"ΔH°rxn للمعادلة","marks":1},{"element":"حرارة الاحتراق لمول واحد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان بالوحدات."},{"level":"2–3 درجات","description":"ΔH°rxn صحيحة دون القسمة على 2، أو خطأ حسابي واحد."},{"level":"1 درجة","description":"معادلة التجميع مكتوبة مع تعويض جزئي."},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة."}]'::jsonb, '["نسيان القسمة على 2 لمول واحد","عدم ضرب ΔH°f(C₂H₆) في 2","طرح النواتج من المتفاعلات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.824Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عند تكوّن ماء سائل: ΔH°rxn = [−394 + 2(−286)] − [−75 + 2(0.0)] = −966 + 75 = −891 kJ. عند تكوّن ماء غازي: ΔH°rxn = [−394 + 2(−242)] − [−75] = −878 + 75 = −803 kJ. الفرق 88 kJ، فالاحتراق المنتج للماء السائل يطلق حرارة أكبر؛ لأن تكثف 2 mol من بخار الماء إلى سائل يطلق حرارة إضافية مقدارها 2 × 44 kJ = 88 kJ. لذا يجب تحديد الحالة الفيزيائية للماء في المعادلة الحرارية.', '["حساب ΔH°rxn مع الماء السائل −891 kJ","حساب ΔH°rxn مع الماء الغازي −803 kJ","المقارنة: السائل يطلق حرارة أكبر بـ 88 kJ","التفسير بحرارة تكثف 2 mol من الماء"]'::jsonb, '["سائل: [−394 + 2(−286)] − [−75 + 0] = −891 kJ","غاز: [−394 + 2(−242)] − [−75 + 0] = −803 kJ","الفرق: −803 − (−891) = 88 kJ = 2 × 44 kJ"]'::jsonb, '[{"element":"الحساب مع الماء السائل","marks":1},{"element":"الحساب مع الماء الغازي","marks":1},{"element":"المقارنة","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان ومقارنة وتفسير بالتكثف."},{"level":"3–4 درجات","description":"حسابان صحيحان مع تفسير ناقص."},{"level":"1–2 درجة","description":"حساب واحد صحيح."},{"level":"صفر","description":"لا إجابة أو حسابات خاطئة."}]'::jsonb, '["عدم ضرب ΔH°f للماء في 2","القول إن الماء الغازي يعطي حرارة أكبر","إهمال الحالة الفيزيائية واستعمال قيمة واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-03T20:38:11.825Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
