from (values
('mcq', 1, 'إذا علمت أن: H₂(g) + ½O₂(g) → H₂O(l)، ΔH = −286 kJ، فما قيمة ΔH للتفاعل: H₂O(l) → H₂(g) + ½O₂(g)؟', null, '["−286 kJ","+572 kJ","+286 kJ","−143 kJ"]'::jsonb, 'فهم', 'أثر عكس المعادلة', 'سهل', 'الكتاب ص 32 — تطبيق قانون هس (الخطوتان 2 و3)'),
('mcq', 2, 'يتكوّن مول واحد من الماء السائل بإطلاق 286 kJ. ما التغير في المحتوى الحراري المصاحب لتكوين الماء وفق المعادلة الموزونة 2H₂(g) + O₂(g) → 2H₂O(l)؟', null, '["−572 kJ","−286 kJ","−143 kJ","+572 kJ"]'::jsonb, 'فهم', 'أثر ضرب المعادلة', 'سهل', 'الكتاب ص 32 — تطبيق قانون هس (الخطوتان 2 و3)'),
('mcq', 3, 'لماذا تُضاعف قيمة ΔH عند ضرب معاملات المعادلة الكيميائية الحرارية في 2؟', null, '["لأن ضرب المعاملات يجعل التفاعل أسرع فتزداد الحرارة","لأن تفاعل ضعف كمية المواد بالمولات يطلق أو يمتص ضعف كمية الحرارة","لأن ضرب المعاملات يغير طبيعة المواد المتفاعلة والناتجة","لأن ضرب المعاملات يعكس اتجاه انتقال الحرارة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 32 — تطبيق قانون هس (الخطوتان 2 و3)'),
('mcq', 4, 'لماذا تتغير إشارة ΔH عند عكس المعادلة الكيميائية الحرارية دون أن تتغير قيمتها العددية؟', null, '["لأن التفاعل العكسي يحتاج دائمًا إلى ضعف الطاقة المنطلقة","لأن عكس المعادلة يقلل عدد المولات المتفاعلة إلى النصف","لأن التفاعل العكسي يتم دائمًا في ظروف غير قياسية","لأن ما ينطلق من حرارة في اتجاه يُمتص مثله في الاتجاه المعاكس"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 27 وص 32 — عكس المعادلات الحرارية'),
('mcq', 5, 'للتفاعل: A → B، ΔH = −120 kJ. ما قيمة ΔH للتفاعل: 3B → 3A؟', null, '["−360 kJ","+360 kJ","+120 kJ","+40 kJ"]'::jsonb, 'تطبيق', 'عكس وضرب', 'متوسط', 'الكتاب ص 44 — تقويم الفصل (78)'),
('mcq', 6, 'إذا علمت أن: 2SO₃(g) → 2SO₂(g) + O₂(g)، ΔH = +198 kJ، فما قيمة ΔH للتفاعل: SO₂(g) + ½O₂(g) → SO₃(g)؟', null, '["−99 kJ","−198 kJ","+99 kJ","−396 kJ"]'::jsonb, 'تطبيق', 'عكس وقسمة', 'صعب', 'الكتاب ص 32 — تطبيق قانون هس (الخطوتان 2 و3)'),
('mcq', 7, 'إذا علمت أن: ½N₂(g) + O₂(g) → NO₂(g)، ΔH = +33.2 kJ، فما قيمة ΔH للتفاعل: 2NO₂(g) → N₂(g) + 2O₂(g)؟', null, '["+66.4 kJ","−33.2 kJ","−16.6 kJ","−66.4 kJ"]'::jsonb, 'تطبيق', 'عكس وضرب', 'صعب', 'الكتاب ص 35 — تكوين NO₂، وص 32 قواعد التعامل مع ΔH'),
('essay', 1, 'للتبخر: H₂O(l) → H₂O(g)، ΔH = +40.7 kJ. وضّح ما يحدث لقيمة ΔH وإشارتها عند: (1) عكس المعادلة، (2) ضرب المعادلة الأصلية في 3، مع كتابة المعادلة الناتجة وقيمة ΔH لكل حالة، وتعليل كل تغير.', null, null, 'فهم', 'توضيح قاعدة', 'سهل', 'الكتاب ص 27 — المعادلات الحرارية لتغيرات الحالة، وص 32'),
('essay', 2, 'إذا علمت أن: C(s) + O₂(g) → CO₂(g)، ΔH = −394 kJ، فاكتب المعادلة الحرارية واحسب ΔH لكل مما يأتي، مبينًا القاعدة المستعملة: (1) 2CO₂(g) → 2C(s) + 2O₂(g)؛ (2) ½C(s) + ½O₂(g) → ½CO₂(g).', null, null, 'تطبيق', 'تطبيق القواعد', 'متوسط', 'الكتاب ص 32 — تطبيق قانون هس (الخطوتان 2 و3)'),
('essay', 3, 'أراد طالب حساب ΔH للتفاعل 2S(s) + 3O₂(g) → 2SO₃(g) من المعادلتين: (a) S(s) + O₂(g) → SO₂(g)، ΔH = −297 kJ؛ (b) 2SO₃(g) → 2SO₂(g) + O₂(g)، ΔH = +198 kJ. فكتب: 2S + 2O₂ → 2SO₂، ΔH = −297 kJ؛ و2SO₂ + O₂ → 2SO₃، ΔH = +198 kJ، ثم جمع فحصل على ΔH = −99 kJ. قوّم حل الطالب، وحدد خطأيه، ثم صححه.', null, null, 'تقويم', 'تقويم حل', 'صعب', 'الكتاب ص 32 — تطبيق قانون هس (الخطوتان 2 و3)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
