select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'المعادلة المطلوبة هي عكس المعادلة المعطاة بالمعاملات نفسها، فتبقى القيمة العددية 286 kJ وتتغير الإشارة: ΔH = +286 kJ.', '["عند عكس المعادلة يجب تغيير إشارة ΔH؛ وهنا بقيت الإشارة كما هي.","عُكست الإشارة لكن ضُوعفت القيمة دون داعٍ؛ فالمعاملات لم تتغير.","","قُسمت القيمة على 2 دون تغيير الإشارة؛ والمعادلة معكوسة فقط ولم تتغير معاملاتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-03T20:38:11.825Z"}'::jsonb),
('mcq', 2, 0, 'معادلة تكوين مول واحد هي H₂(g) + ½O₂(g) → H₂O(l)، ΔH = −286 kJ، والمعادلة الموزونة هي هذه المعادلة مضروبة في 2 (تكوين 2 mol)، فتُضرب ΔH في 2: ΔH = 2(−286 kJ) = −572 kJ.', '["","ضُربت المعاملات في 2، فيجب ضرب ΔH في 2 أيضًا؛ لأن ضعف كمية المواد يطلق ضعف الحرارة.","قُسمت ΔH على 2 بدل ضربها؛ والمعاملات تضاعفت لا تنصفت.","ضُوعفت القيمة صحيحًا لكن غُيرت الإشارة؛ والمعادلة لم تُعكس فتبقى الإشارة سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:38:11.826Z"}'::jsonb),
('mcq', 3, 1, 'ΔH تتناسب مع كمية المواد المتفاعلة؛ فعند تفاعل 2 mol من الكبريت مثلًا بدل 1 mol تتضاعف الحرارة، لذا تُضرب ΔH في المعامل نفسه.', '["السرعة لا علاقة لها بقيمة ΔH؛ التضاعف سببه تضاعف عدد المولات المتفاعلة.","","طبيعة المواد لا تتغير بضرب المعاملات؛ تتغير الكميات فقط.","الضرب لا يغير إشارة ΔH؛ الذي يغير الإشارة هو عكس المعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-03T20:38:11.826Z"}'::jsonb),
('mcq', 4, 3, 'إذا أطلق تفاعل كمية من الحرارة فإن التفاعل العكسي يمتص الكمية نفسها (مثل ΔHcond = −ΔHvap)؛ أي أن ما ينطلق من حرارة في اتجاه يُمتص مثله في الاتجاه المعاكس، لذا تبقى القيمة العددية وتتغير الإشارة.', '["التفاعل العكسي يمتص أو يطلق المقدار نفسه من الطاقة لا ضعفه.","عكس المعادلة لا يغير المعاملات ولا عدد المولات، بل يبدل المتفاعلات والنواتج.","تغير الإشارة لا علاقة له بالظروف؛ سببه أن الطاقة المنطلقة في اتجاه تُمتص في الاتجاه الآخر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-03T20:38:11.826Z"}'::jsonb),
('mcq', 5, 1, 'المعادلة المطلوبة هي عكس المعادلة المعطاة مضروبة في 3، فتُضرب ΔH في 3 وتُعكس إشارتها: ΔH = −3(−120 kJ) = +360 kJ.', '["ضُربت القيمة في 3 دون تغيير الإشارة؛ والمعادلة معكوسة أيضًا.","","غُيرت الإشارة للعكس لكن لم تُضرب القيمة في 3.","قُسمت القيمة على 3 بدل ضربها؛ فالمعاملات تضاعفت ثلاث مرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:38:11.826Z"}'::jsonb),
('mcq', 6, 0, 'المعادلة المطلوبة هي عكس المعطاة مقسومة على 2، فتُعكس الإشارة وتُقسم القيمة على 2: ΔH = −198 kJ ÷ 2 = −99 kJ.', '["","عُكست المعادلة وغُيرت الإشارة، لكن لم تُقسم القيمة على 2 مع أن المعاملات نُصّفت.","قُسمت القيمة على 2 لكن لم تُغير الإشارة مع أن المعادلة معكوسة.","ضُربت القيمة في 2 بدل قسمتها؛ والمعاملات في المعادلة المطلوبة نصف المعطاة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-03T20:38:11.827Z"}'::jsonb),
('mcq', 7, 3, 'المعادلة المطلوبة هي عكس المعطاة مضروبة في 2، فتُضرب ΔH في 2 وتُعكس إشارتها: ΔH = −2(+33.2 kJ) = −66.4 kJ.', '["ضُربت القيمة في 2 لكن لم تُغير الإشارة مع أن المعادلة معكوسة.","غُيرت الإشارة لكن لم تُضرب في 2، مع أن المعادلة المطلوبة لـ 2 mol من NO₂.","قُسمت القيمة على 2 بدل ضربها؛ والمعاملات تضاعفت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-03T20:38:11.827Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) العكس: H₂O(g) → H₂O(l)، ΔH = −40.7 kJ؛ تتغير الإشارة وتبقى القيمة؛ لأن الحرارة التي تُمتص عند تبخر 1 mol من الماء تنطلق نفسها عند تكثفه (ΔHcond = −ΔHvap). (2) الضرب في 3: 3H₂O(l) → 3H₂O(g)، ΔH = 3(+40.7 kJ) = +122.1 kJ؛ تُضرب القيمة في 3 وتبقى الإشارة؛ لأن تبخر 3 mol يحتاج إلى ثلاثة أمثال الحرارة.', '["معادلة العكس وΔH = −40.7 kJ","تعليل تغير الإشارة","معادلة الضرب وΔH = +122.1 kJ","تعليل تضاعف القيمة"]'::jsonb, '["العكس: ΔH = −(+40.7 kJ) = −40.7 kJ","الضرب: ΔH = 3 × 40.7 kJ = +122.1 kJ"]'::jsonb, '[{"element":"حالة العكس","marks":1},{"element":"تعليل العكس","marks":1},{"element":"حالة الضرب","marks":1},{"element":"تعليل الضرب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحالتان صحيحتان مع التعليل."},{"level":"2–3 درجات","description":"الحالتان صحيحتان دون تعليل كافٍ، أو حالة واحدة مع تعليلها."},{"level":"1 درجة","description":"قيمة واحدة صحيحة فقط."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["تغيير الإشارة عند الضرب","ضرب القيمة عند العكس","نسيان الحالة الفيزيائية في المعادلة الناتجة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:38:11.827Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) المعادلة معكوسة ومضروبة في 2، فتُعكس الإشارة وتُضرب القيمة في 2: ΔH = −2(−394 kJ) = +788 kJ. (2) المعادلة مضروبة في ½ دون عكس، فتُقسم القيمة على 2 وتبقى الإشارة: ΔH = ½(−394 kJ) = −197 kJ.', '["(1) تحديد العكس والضرب في 2","(1) ΔH = +788 kJ","(2) تحديد الضرب في ½ دون عكس","(2) ΔH = −197 kJ"]'::jsonb, '["(1) ΔH = −2 × (−394 kJ) = +788 kJ","(2) ΔH = ½ × (−394 kJ) = −197 kJ"]'::jsonb, '[{"element":"القاعدة في (1)","marks":1},{"element":"القيمة في (1)","marks":1},{"element":"القاعدة في (2)","marks":1},{"element":"القيمة في (2)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القيمتان والقاعدتان صحيحة."},{"level":"2–3 درجات","description":"قيمة صحيحة مع قاعدتها وخطأ في الأخرى."},{"level":"1 درجة","description":"قاعدة واحدة صحيحة دون حساب صحيح."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["إعطاء (1) القيمة −788 kJ بنسيان عكس الإشارة","إعطاء (1) القيمة +394 kJ بنسيان الضرب في 2","تغيير الإشارة في (2) مع أن المعادلة لم تُعكس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-03T20:38:11.827Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطالب أصاب في ضرب المعادلة a في 2 وعكس المعادلة b وجمعهما، لكنه أخطأ مرتين: (1) ضرب معاملات a في 2 ولم يضرب ΔH في 2؛ والصحيح ΔH = 2(−297 kJ) = −594 kJ. (2) عكس المعادلة b ولم يغير إشارة ΔH؛ والصحيح ΔH = −198 kJ. وبعد التصحيح: ΔH = −594 kJ + (−198 kJ) = −792 kJ.', '["بيان ما أصاب فيه الطالب (معالجة المعادلات وجمعها)","الخطأ الأول: لم يضرب ΔH في 2","الخطأ الثاني: لم يغير الإشارة عند العكس","التصحيح: −594 kJ و−198 kJ","الناتج الصحيح −792 kJ"]'::jsonb, '["2 × a: ΔH = 2(−297) = −594 kJ","عكس b: ΔH = −198 kJ","الجمع: ΔH = −594 + (−198) = −792 kJ"]'::jsonb, '[{"element":"تحديد الخطأ الأول","marks":1},{"element":"تحديد الخطأ الثاني","marks":1},{"element":"تصحيح القيمتين","marks":1},{"element":"الناتج الصحيح","marks":1},{"element":"الحكم العام على الحل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد الخطأين وتصحيحهما والناتج −792 kJ مع حكم واضح."},{"level":"3–4 درجات","description":"تحديد الخطأين مع خطأ في التصحيح أو الناتج."},{"level":"1–2 درجة","description":"تحديد خطأ واحد فقط."},{"level":"صفر","description":"لا إجابة أو قبول حل الطالب."}]'::jsonb, '["اكتشاف خطأ واحد فقط","تغيير إشارة a أيضًا","الحصول على −495 kJ أو −396 kJ بعد تصحيح جزئي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:38:11.828Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
