('mcq', 1, 1, 'الظروف القياسية في الكيمياء الحرارية ضغط 1 atm ودرجة حرارة 25°C (298 K)، أما STP فضغط 1 atm ودرجة حرارة 0°C (273 K)؛ فالضغط واحد، والاختلاف في درجة الحرارة فقط.', '["الضغط واحد في الحالتين (1 atm)، والاختلاف في درجة الحرارة.","","الظروف القياسية 1 atm و25°C (298 K)، لا 2 atm و100°C.","STP عند 0°C، أما الظروف القياسية في الكيمياء الحرارية فعند 25°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-03T20:38:11.829Z"}'::jsonb),
('mcq', 2, 3, 'الزئبق فلز سائل عند 25°C و 1 atm، فحالته القياسية Hg(l). أما الحديد فصلب، والأكسجين والنيتروجين غازان ثنائيا الذرة.', '["الحديد صلب في الحالة القياسية Fe(s)، ولا يكون سائلًا إلا عند درجات حرارة عالية جدًّا.","الأكسجين في الحالة القياسية غاز ثنائي الذرة O₂(g)، لا ذرات منفردة O(g).","النيتروجين في الحالة القياسية غاز ثنائي الذرة N₂(g)، لا ذرات منفردة N(g).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.829Z"}'::jsonb),
('mcq', 3, 0, 'الكبريت الصلب S(s) عنصر في حالته القياسية، والعناصر في حالاتها القياسية يكون لها ΔH°f = 0.0 kJ/mol.', '["","SO₃(g) مركب يتكون من عناصره بانطلاق حرارة، و ΔH°f له تساوي −396 kJ/mol.","O(g) ليس الحالة القياسية للأكسجين؛ فحالته القياسية O₂(g)، لذا لا تساوي ΔH°f لـ O(g) صفرًا.","H₂O(l) مركب وليس عنصرًا، و ΔH°f له تساوي −286 kJ/mol."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:38:11.829Z"}'::jsonb),
('mcq', 4, 2, 'تعتمد حرارة التكوين القياسية على فرضية أن ΔH°f للعناصر في حالاتها القياسية تساوي 0.0 kJ/mol؛ فهي نقطة بداية (مرجع) تُنظَّم بالنسبة إليها قيم حرارة تكوين المركبات، كما يُتخذ 0.0°C نقطة صفر لتدريج درجة الحرارة المئوية.', '["الصفر هنا قيمة مرجعية متفق عليها، ولا يعني أن العنصر خالٍ من الطاقة؛ فالمحتوى الحراري المطلق لا يُقاس.","العنصر في حالته القياسية لا يتكون من مواد أخرى، فلا يوجد تفاعل تكوين يطلق حرارة؛ والقيمة صفر تمامًا لا قيمة صغيرة.","","العناصر تتفاعل مع غيرها في الظروف القياسية، مثل تفاعل الكبريت مع الأكسجين، وهذا لا علاقة له بكون ΔH°f لها صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.829Z"}'::jsonb),
('mcq', 5, 1, 'المتفاعلات C(s) و H₂(g) و O₂(g) كلها عناصر في حالاتها القياسية، فحرارة تكوين كل منها 0.0 kJ/mol، ومجموعها مهما كانت المعاملات 0.0 kJ.', '["−534 kJ هي ΔH للتفاعل كله، أي حرارة تكوين الناتج C₃H₇COOH، وليست مجموع حرارة تكوين المتفاعلات.","","هذه قيمة ΔH للتفاعل بعد عكس إشارتها، ولا علاقة لها بالمتفاعلات التي هي عناصر حرارة تكوينها صفر.","هذا ناتج قسمة −534 kJ على معامل الكربون 4، وهو خطأ؛ فحرارة تكوين كل عنصر في حالته القياسية صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:38:11.829Z"}'::jsonb),
('mcq', 6, 0, 'الأكسجين في الحالة القياسية غاز ثنائي الذرة O₂(g)، فتكون ΔH°f له صفرًا. أما الصور الأخرى مثل O(g) فليست الحالة القياسية، ويلزم طاقة لتكوينها من O₂(g) (مثل O₂(g) → 2O(g) ΔH = +495 kJ)، فلا تساوي حرارة تكوينها صفرًا.', '["","الأكسجين يوجد في الظروف القياسية جزيئات ثنائية الذرة O₂ لا ذرات منفردة.","قاعدة الصفر تخص الحالة القياسية للعنصر فقط (O₂(g))، لا كل صوره؛ فتكوين O(g) أو O₃(g) من O₂(g) يصاحبه تغير في المحتوى الحراري.","الأكسجين غاز عند 25°C و 1 atm، ولا يكون سائلًا إلا عند درجات حرارة منخفضة جدًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.829Z"}'::jsonb),
('mcq', 7, 3, 'NO₂(g) مركب لا عنصر، ويتكون من N₂(g) و O₂(g) بامتصاص 33.2 kJ لكل مول، فقيمة ΔH°f له +33.2 kJ/mol لا صفر. أما Fe(s) و Hg(l) و O₂(g) فعناصر في حالاتها القياسية قيمتها 0.0، وقيمة SO₃(g) صحيحة.', '["الزئبق سائل في الحالة القياسية، فـ Hg(l) هي حالته القياسية وقيمتها 0.0 صحيحة رغم أنه فلز.","O₂(g) هي الحالة القياسية للأكسجين، فقيمة 0.0 صحيحة.","حرارة التكوين القياسية لـ SO₃(g) تساوي −396 kJ/mol فعلًا، فهذه القيمة صحيحة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:38:11.830Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحالة القياسية: ضغط جوي واحد 1 atm ودرجة حرارة 25°C (298 K). الحديد صلب Fe(s)، والزئبق سائل Hg(l)، والأكسجين غاز ثنائي الذرة O₂(g)، والنيتروجين غاز ثنائي الذرة N₂(g). وحرارة التكوين القياسية لكل منها في هذه الحالات تساوي 0.0 kJ/mol؛ لأنها عناصر في حالاتها القياسية.', '["الحالة القياسية: 1 atm و 25°C (298 K)","Fe(s) و Hg(l)","O₂(g) و N₂(g) غازان ثنائيا الذرة","ΔH°f لكل منها = 0.0 kJ/mol"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الحالة القياسية (الضغط ودرجة الحرارة)","marks":1},{"element":"تحديد الحالة القياسية للعناصر الأربعة (نصف درجة لكل عنصر)","marks":2},{"element":"ذكر أن ΔH°f لكل منها = 0.0 kJ/mol","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وحالات العناصر الأربعة صحيحة، وقيمة ΔH°f صحيحة"},{"level":"2–3 درجات","description":"خطأ في حالة عنصر أو عنصرين، أو نقص في التعريف"},{"level":"1 درجة","description":"ذكر جزء من التعريف أو قيمة الصفر فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الحالة القياسية (25°C) والظروف المعيارية STP (0°C)","كتابة الزئبق صلبًا لأنه فلز","كتابة الأكسجين أو النيتروجين ذرات منفردة O(g) أو N(g)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:38:11.830Z"}'::jsonb),
('essay', 2, null::int, null, null, 'حرارة التكوين القياسية هي التغير في المحتوى الحراري عند تكوين 1 mol من مادة من عناصرها في حالاتها القياسية، والعنصر في حالته القياسية لا يتكون من شيء آخر، لذا اتُّفق (فرضًا) على أن ΔH°f له 0.0 kJ/mol. ولا يعني الصفر أن العنصر بلا طاقة، بل هو مرجع. وفائدته أنه نقطة بداية تُنظَّم بالنسبة إليها قيم حرارة تكوين المركبات التي تُقاس عمليًّا: فالمركب الذي يمتص حرارة عند تكوينه (مثل NO₂: +33.2 kJ/mol) يقع فوق الصفر، والذي يطلق حرارة (مثل SO₃: −396 kJ/mol) يقع تحته. وهذا يشبه تدريج درجة الحرارة المئوية الذي يتخذ 0.0°C (تجمد الماء) صفرًا، فتكون المواد الأدفأ فوقه والأبرد تحته.', '["العنصر في حالته القياسية لا يتكون من مواد أخرى، فاتُّفق على ΔH°f = 0.0","الصفر قيمة مرجعية وليس انعدامًا للطاقة","الفائدة: نقطة بداية تُقاس بالنسبة إليها حرارة تكوين المركبات","التشبيه: مركبات فوق الصفر (ماصة) وتحته (طاردة) كما في التدريج المئوي"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير كون ΔH°f للعنصر صفرًا","marks":1},{"element":"بيان أن الصفر مرجع لا انعدام للطاقة","marks":1},{"element":"فائدة نقطة البداية مع مثال لمركب فوق الصفر وآخر تحته","marks":1},{"element":"المقارنة الصحيحة بالتدريج المئوي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح، وبيان معنى المرجع، وفائدة واضحة بمثالين، ومقارنة سليمة"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في الفائدة أو المقارنة"},{"level":"1 درجة","description":"ذكر أن القيمة صفر دون تفسير مقبول"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن العناصر لا تمتلك طاقة","القول إن العناصر لا تتفاعل لذا حرارتها صفر","عكس موضع المركبات الماصة والطاردة بالنسبة إلى الصفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.830Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تساوي صفرًا: Fe(s) و Hg(l) و O₂(g) و N₂(g)؛ لأنها عناصر في حالاتها القياسية عند 1 atm و 25°C (الحديد صلب، والزئبق سائل، والأكسجين والنيتروجين غازان ثنائيا الذرة). لا تساوي صفرًا: O(g) و O₃(g)؛ فهما صورتان للأكسجين لكنهما ليستا حالته القياسية، وتكوين أي منهما من O₂(g) يصاحبه تغير في المحتوى الحراري. و NO₂(g) مركب يتكون من عناصره بامتصاص 33.2 kJ لكل مول، فقيمة ΔH°f له +33.2 kJ/mol.', '["صفر: Fe(s)، Hg(l)، O₂(g)، N₂(g) — عناصر في حالاتها القياسية","ليس صفرًا: O(g)، O₃(g) — ليستا الحالة القياسية للأكسجين","ليس صفرًا: NO₂(g) — مركب، ΔH°f = +33.2 kJ/mol","التعليل مرتبط بالحالة القياسية لا بنوع العنصر فقط"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف المواد الأربع ذات القيمة صفر مع التعليل","marks":2},{"element":"تصنيف O(g) و O₃(g) مع التعليل","marks":2},{"element":"تصنيف NO₂(g) مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف المواد السبع صحيح مع تعليل سليم لكل مجموعة"},{"level":"3–4 درجات","description":"خطأ في تصنيف مادة واحدة أو نقص في أحد التعليلات"},{"level":"1–2 درجة","description":"تصنيف بعض المواد صحيحًا دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ O(g) و O₃(g) صفرًا لأنهما من عنصر الأكسجين","عدّ NO₂ صفرًا لأنه يتكون من غازين ثنائيي الذرة","الحكم على Hg(l) بأنه ليس في حالته القياسية لأنه فلز سائل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-03T20:38:11.830Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
