insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L4-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في مخطط تدريج حرارة التكوين القياسية، أين توضع العناصر في حالاتها القياسية مثل N₂(g) و O₂(g) و S(s)؟', null, '["في أعلى المخطط فوق جميع المركبات","في أسفل المخطط تحت جميع المركبات","عند خط الصفر (0.0 kJ/mol) من المخطط","في منتصف المسافة بين أعلى مركب وأدناه"]'::jsonb, 'فهم', 'قراءة مخطط', 'سهل', 'الكتاب ص 35 — الشكل 1-14 تدريج حرارة التكوين القياسية'),
('mcq', 2, 'في مخطط حرارة التكوين القياسية يُرسم سهم ΔH°f لكل مركب من خط العناصر (الصفر) إلى مستوى المركب؛ فيتجه سهم NO₂(g) إلى أعلى، ويتجه سهم SO₃(g) إلى أسفل. علامَ يدل اتجاه السهم؟', null, '["السهم الصاعد يدل على امتصاص الطاقة عند التكوين، والهابط على انطلاقها","السهم الصاعد يدل على انطلاق الطاقة عند التكوين، والهابط على امتصاصها","السهم الصاعد يدل على مركب غازي، والهابط على مركب صلب أو سائل","السهم الصاعد يدل على تفاعل سريع، والهابط على تفاعل بطيء"]'::jsonb, 'فهم', 'تفسير مخطط', 'سهل', 'الكتاب ص 35 — الشكل 1-14 تدريج حرارة التكوين القياسية'),
('mcq', 3, 'اعتمادًا على قيم حرارة التكوين القياسية الآتية، أيّ المركبات يقع في المخطط على أكبر بُعد تحت عناصره، فيكون الأكثر استقرارًا مقارنة بعناصره؟', '{"headers":["المركب","ΔH°f (kJ/mol)"],"rows":[["H₂S(g)","−21"],["HF(g)","−273"],["SO₃(g)","−396"],["SF₆(g)","−1220"]]}'::jsonb, '["H₂S(g)","HF(g)","SO₃(g)","SF₆(g)"]'::jsonb, 'تحليل', 'مقارنة الاستقرار من البيانات', 'متوسط', 'الكتاب ص 35 و ص 38 — الجدول 1-5 وسؤال التقويم 41'),
('mcq', 4, 'تبين القيم الآتية حرارة التكوين القياسية لأربعة مركبات. ما الاستنتاج الصحيح عن استقرارها مقارنة بالعناصر المكونة لها في حالاتها القياسية؟', '{"headers":["المركب","ΔH°f (kJ/mol)"],"rows":[["CO₂(g)","−394"],["H₂O(l)","−286"],["CH₄(g)","−75"],["HF(g)","−273"]]}'::jsonb, '["جميعها أقل استقرارًا من عناصرها؛ لأن قيم ΔH°f لها سالبة","جميعها أكثر استقرارًا من عناصرها؛ لأن قيم ΔH°f لها سالبة","جميعها مستقرة بالقدر نفسه؛ لأنها كلها تقع تحت خط الصفر","لا يمكن الحكم على استقرارها دون معرفة حرارة احتراقها"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'متوسط', 'الكتاب ص 37–38 — مثال 1-6 وسؤال التقويم 41 (الاستقرار والطاقة المنخفضة)'),
('mcq', 5, 'في مخطط لحرارة التكوين القياسية رُسم H₂O(l) عند −285.8 kJ/mol و H₂O(g) عند −241.8 kJ/mol. ما قيمة ΔH للتحول H₂O(l) → H₂O(g) عند 298 K التي تمثلها المسافة بينهما؟', null, '["−44.0 kJ","−527.6 kJ","+44.0 kJ","+527.6 kJ"]'::jsonb, 'تطبيق', 'حساب من مخطط', 'متوسط', 'الكتاب ص 38 — سؤال التقويم 43 (تفسير الرسوم العلمية)'),
('mcq', 6, 'إذا علمت أن ΔH°f لـ NO(g) = +91.3 kJ/mol، و ΔH°f لـ NO₂(g) = +33.2 kJ/mol، وأن المادة تكون أكثر استقرارًا كلما انخفض محتواها الحراري، فما الترتيب الصحيح من الأكثر استقرارًا إلى الأقل استقرارًا؟', null, '["NO ثم NO₂ ثم العنصران N₂ و O₂","NO₂ ثم العنصران N₂ و O₂ ثم NO","العنصران N₂ و O₂ ثم NO ثم NO₂","العنصران N₂ و O₂ ثم NO₂ ثم NO"]'::jsonb, 'تحليل', 'ترتيب الاستقرار', 'صعب', 'الكتاب ص 38 — مسألة 37 وسؤال التقويم 41'),
('mcq', 7, 'مخطط لحرارة التكوين القياسية فيه خط الصفر للعناصر، و NO₂(g) عند +33.2 kJ/mol، و SO₃(g) عند −396 kJ/mol. أين يقع تقريبًا H₂O(l) الذي ΔH°f له −286 kJ/mol؟', null, '["تحت خط الصفر بين الصفر و SO₃(g)، وأقرب إلى SO₃(g) منه إلى الصفر","فوق خط الصفر بين العناصر و NO₂(g)، لأن الماء سائل مستقر","تحت SO₃(g) مباشرة، لأن الماء أكثر استقرارًا من SO₃","تحت خط الصفر بين الصفر و SO₃(g)، وأقرب إلى الصفر منه إلى SO₃(g)"]'::jsonb, 'تحليل', 'توقع موقع على مخطط', 'صعب', 'الكتاب ص 35 — الشكل 1-14 (توقع موقع الماء على الرسم)'),
('essay', 1, 'مخطط لحرارة التكوين القياسية يبين: العناصر N₂(g) و O₂(g) و S(s) عند 0.0 kJ/mol، و NO₂(g) عند +33.2 kJ/mol، و SO₃(g) عند −396 kJ/mol. فسّر ما يدل عليه موقع كل من NO₂ و SO₃ بالنسبة إلى خط الصفر من حيث نوع تفاعل التكوين (ماصّ أم طارد)، ثم قارن استقرار كل منهما بعناصره.', null, null, 'تحليل', 'تفسير مخطط ومقارنة', 'سهل', 'الكتاب ص 35 — الشكل 1-14 وإيجاد حرارة التكوين بالتجارب'),
('essay', 2, 'ΔH°f للماء السائل H₂O(l) = −285.8 kJ/mol، و ΔH°f لبخار الماء H₂O(g) = −241.8 kJ/mol. صف مخططًا لحرارة التكوين القياسية يضم العنصرين H₂(g) و O₂(g) وصورتي الماء، ثم استعمله لحساب حرارة تبخر الماء عند 298 K، وبيّن أيّ صورتي الماء أكثر استقرارًا.', null, null, 'تحليل', 'رسم مخطط وحساب', 'صعب', 'الكتاب ص 38 — سؤال التقويم 43 (تفسير الرسوم العلمية)'),
('essay', 3, 'قال طالب: «المركب الذي حرارة تكوينه القياسية موجبة وكبيرة يكون أكثر استقرارًا؛ لأنه يختزن طاقة أكبر». قوّم هذه العبارة مستعينًا بالقيم الآتية (kJ/mol): NO(g) = +91.3، NO₂(g) = +33.2، HF(g) = −273، SF₆(g) = −1220.', null, null, 'تقويم', 'تقويم عبارة', 'متوسط', 'الكتاب ص 35 و ص 38 — الجدول 1-5، ومسألة 37، وسؤال التقويم 41')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
