('mcq', 1, 2, 'حرارة التكوين القياسية للعناصر في حالاتها القياسية 0.0 kJ/mol، لذا توضع عند خط الصفر، وتوضع المركبات فوقه أو تحته بحسب إشارة ΔH°f لها.', '["العناصر عند الصفر، وتوجد مركبات فوقها (ΔH°f موجبة) مثل NO₂ عند +33.2 kJ/mol.","العناصر عند الصفر، وتوجد مركبات تحتها (ΔH°f سالبة) مثل SO₃ عند −396 kJ/mol.","","موضع العناصر ثابت عند الصفر، ولا يتحدد بموقع المركبات في المخطط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:38:11.831Z"}'::jsonb),
('mcq', 2, 0, 'يقع NO₂ فوق الصفر (ΔH°f = +33.2 kJ/mol) فسهمه صاعد، أي أن تكوينه يمتص الطاقة؛ ويقع SO₃ تحت الصفر (ΔH°f = −396 kJ/mol) فسهمه هابط، أي أن تكوينه يطلق الطاقة. فالسهم الصاعد يدل على امتصاص الطاقة عند التكوين، والهابط على انطلاقها.', '["","الصعود يعني أن المحتوى الحراري للمركب أعلى من عناصره (ΔH°f موجبة)، أي امتصاص الطاقة لا انطلاقها.","اتجاه السهم تحدده إشارة ΔH°f لا الحالة الفيزيائية؛ فـ NO₂ وSO₃ كلاهما غاز.","المخطط يبين التغير في المحتوى الحراري، ولا يدل على سرعة التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-03T20:38:11.832Z"}'::jsonb),
('mcq', 3, 3, 'أصغر قيمة (أكثرها سالبية) هي ΔH°f لـ SF₆ = −1220 kJ/mol، فهو أدنى المركبات طاقة مقارنة بعناصره، والاستقرار يرتبط بالطاقة المنخفضة.', '["H₂S له أقرب قيمة إلى الصفر (−21 kJ/mol)، فهو أقل هذه المركبات استقرارًا مقارنة بعناصره.","−273 kJ/mol أعلى من −1220 kJ/mol، فـ HF أقرب إلى خط الصفر من SF₆.","−396 kJ/mol أعلى من −1220 kJ/mol، فـ SO₃ ليس الأدنى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:38:11.832Z"}'::jsonb),
('mcq', 4, 1, 'القيم السالبة تعني أن كل مركب أدنى في المحتوى الحراري من عناصره (يقع تحت الصفر)، وانخفاض الطاقة يرتبط بزيادة الاستقرار؛ لذا كلها أكثر استقرارًا من عناصرها.', '["الإشارة السالبة تعني طاقة أقل من العناصر، والطاقة الأقل تعني استقرارًا أكبر لا أقل.","","القيم مختلفة (من −75 إلى −394 kJ/mol)، فدرجة انخفاض طاقتها عن عناصرها ليست واحدة.","قيمة ΔH°f وحدها تكفي للمقارنة بالعناصر؛ لأنها تقيس فرق المحتوى الحراري بين المركب وعناصره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:38:11.833Z"}'::jsonb),
('mcq', 5, 2, 'ΔH = ΔH°f(H₂O(g)) − ΔH°f(H₂O(l)) = (−241.8) − (−285.8) = +44.0 kJ؛ فالبخار أعلى في المخطط من السائل، والتبخر ماصّ للحرارة.', '["طُرحت قيمة الناتج من المتفاعل (عكس الترتيب)، فانعكست الإشارة؛ والتبخر ماصّ للحرارة.","جُمعت القيمتان بدل طرحهما.","","جُمعت القيمتان وأُخذت الإشارة موجبة؛ والصحيح طرح ΔH°f للمتفاعل من ΔH°f للناتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:38:11.833Z"}'::jsonb),
('mcq', 6, 3, 'العنصران عند 0.0 kJ/mol (الأدنى)، ثم NO₂ عند +33.2، ثم NO عند +91.3 (الأعلى). الأدنى طاقة أكثر استقرارًا، فالترتيب: N₂ و O₂ ثم NO₂ ثم NO.', '["هذا ترتيب من الأقل استقرارًا إلى الأكثر؛ عُدّت القيمة الأكبر أكثر استقرارًا وهو عكس الصحيح.","NO₂ قيمته +33.2، أي فوق الصفر، فهو أقل استقرارًا من العنصرين الواقعين عند الصفر.","NO (+91.3) أعلى من NO₂ (+33.2)، فهو أقل استقرارًا منه لا أكثر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:38:11.834Z"}'::jsonb),
('mcq', 7, 0, 'القيمة −286 سالبة، فيقع تحت الصفر، وهي أعلى من −396 فيقع فوق SO₃. وبُعده عن الصفر 286 kJ وعن SO₃ مقدار 396 − 286 = 110 kJ، فهو أقرب إلى SO₃(g).', '["","القيمة السالبة تعني موقعًا تحت الصفر لا فوقه؛ وما فوق الصفر قيمه موجبة مثل NO₂.","−286 أعلى من −396، فالماء فوق SO₃ لا تحته، وهو أقل استقرارًا منه مقارنة بعناصره.","بُعده عن الصفر 286 kJ وعن SO₃ مقدار 110 kJ فقط، فهو أقرب إلى SO₃ لا إلى الصفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-03T20:38:11.834Z"}'::jsonb),
('essay', 1, null::int, null, null, 'NO₂ فوق الصفر بمقدار 33.2 kJ: تفاعل تكوينه ½N₂(g) + O₂(g) → NO₂(g) ماصّ للحرارة يمتص 33.2 kJ لكل مول، ومحتواه الحراري أعلى من عناصره، فهو أقل استقرارًا منها. SO₃ تحت الصفر بمقدار 396 kJ: تفاعل تكوينه S(s) + 3/2O₂(g) → SO₃(g) طارد للحرارة يطلق 396 kJ لكل مول، ومحتواه الحراري أقل من عناصره، فهو أكثر استقرارًا منها؛ لأن الاستقرار يرتبط بالطاقة المنخفضة.', '["NO₂ فوق الصفر: تكوينه ماصّ (+33.2 kJ/mol)","NO₂ أقل استقرارًا من عناصره","SO₃ تحت الصفر: تكوينه طارد (−396 kJ/mol)","SO₃ أكثر استقرارًا من عناصره؛ الاستقرار يرتبط بالطاقة المنخفضة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير موقع NO₂ ونوع تفاعل تكوينه","marks":1},{"element":"مقارنة استقرار NO₂ بعناصره","marks":1},{"element":"تفسير موقع SO₃ ونوع تفاعل تكوينه","marks":1},{"element":"مقارنة استقرار SO₃ بعناصره مع ربطه بالطاقة المنخفضة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح لموقعي المركبين ونوع التفاعل، ومقارنة استقرار سليمة مع التعليل"},{"level":"2–3 درجات","description":"تفسير صحيح لمركب واحد، أو مقارنة استقرار دون تعليل"},{"level":"1 درجة","description":"تحديد نوع تفاعل واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المركب الواقع فوق الصفر طاردًا للحرارة","ربط الاستقرار بالمحتوى الحراري الأعلى","إغفال أن القيم لكل 1 mol من المركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-03T20:38:11.835Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المخطط: خط الصفر (0.0 kJ/mol) للعنصرين H₂(g) و O₂(g)، وتحته H₂O(g) عند −241.8 kJ/mol، وتحته أكثر H₂O(l) عند −285.8 kJ/mol، وسهمان متجهان إلى أسفل من الصفر إلى كل منهما. التبخر H₂O(l) → H₂O(g) يمثله سهم صاعد من H₂O(l) إلى H₂O(g): ΔHvap = (−241.8) − (−285.8) = +44.0 kJ/mol. والماء السائل أكثر استقرارًا لأنه أدنى طاقة.', '["العنصران عند الصفر، والصورتان تحته","H₂O(l) أدنى من H₂O(g)","ΔHvap = ΔH°f(g) − ΔH°f(l) = +44.0 kJ/mol","H₂O(l) أكثر استقرارًا لأنه أدنى طاقة"]'::jsonb, '["ارسم خط الصفر للعنصرين H₂(g) و O₂(g)","ضع H₂O(g) عند −241.8 kJ/mol و H₂O(l) عند −285.8 kJ/mol تحت الصفر","ΔHvap = ΔH°f(H₂O(g)) − ΔH°f(H₂O(l))","ΔHvap = (−241.8 kJ) − (−285.8 kJ) = +44.0 kJ لكل 1 mol","القيمة موجبة: التبخر ماصّ، والسائل الأدنى طاقة أكثر استقرارًا"]'::jsonb, '[{"element":"وصف المخطط بمواقع صحيحة للعنصرين وصورتي الماء","marks":2},{"element":"كتابة العلاقة الصحيحة لحساب ΔHvap","marks":1},{"element":"الناتج +44.0 kJ/mol بالإشارة والوحدة","marks":1},{"element":"تحديد الصورة الأكثر استقرارًا مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مخطط صحيح، وحساب صحيح بالإشارة والوحدة، واستنتاج استقرار معلل"},{"level":"3–4 درجات","description":"حساب صحيح مع خطأ في المخطط أو الاستنتاج"},{"level":"1–2 درجة","description":"مخطط جزئي أو علاقة صحيحة بناتج خاطئ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح القيمتين بترتيب معكوس فتنتج −44.0 kJ","جمع القيمتين بدل طرحهما","وضع بخار الماء تحت الماء السائل في المخطط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:38:11.835Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة. الاستقرار يرتبط بالطاقة المنخفضة لا بالطاقة المختزنة الكبيرة. فـ NO (+91.3) و NO₂ (+33.2) يقعان فوق الصفر، أي محتواهما الحراري أعلى من عناصرهما، فهما أقل استقرارًا منها، و NO أقل استقرارًا من NO₂ لأنه أعلى. أما HF (−273) و SF₆ (−1220) فيقعان تحت الصفر، فهما أكثر استقرارًا من عناصرهما، و SF₆ الأكثر استقرارًا بين هذه المركبات مقارنة بعناصره. فالترتيب من الأكثر استقرارًا: SF₆ ثم HF ثم NO₂ ثم NO، وهو عكس ما ادعاه الطالب.', '["الحكم: العبارة خاطئة","الاستقرار يرتبط بالطاقة المنخفضة","NO و NO₂ أقل استقرارًا من عناصرهما (فوق الصفر)","HF و SF₆ أكثر استقرارًا من عناصرهما، و SF₆ الأكثر","ترتيب صحيح: SF₆ > HF > NO₂ > NO"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة مع ذكر أن الاستقرار يرتبط بالطاقة المنخفضة","marks":2},{"element":"تحليل المركبين ذوي القيم الموجبة","marks":1},{"element":"تحليل المركبين ذوي القيم السالبة","marks":1},{"element":"الترتيب الصحيح للاستقرار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح معلل، وتحليل سليم لجميع القيم، وترتيب صحيح"},{"level":"3–4 درجات","description":"حكم صحيح معلل مع نقص في تحليل بعض القيم أو الترتيب"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل كافٍ"},{"level":"صفر","description":"تأييد العبارة أو لا إجابة"}]'::jsonb, '["تأييد الطالب بحجة أن الطاقة المختزنة الكبيرة تعني قوة المركب","مقارنة القيم المطلقة دون مراعاة الإشارة","عدّ −273 أكثر استقرارًا من −1220 لأنها أقرب إلى الصفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-03T20:38:11.836Z"}'::jsonb)
