('mcq', 5, 'أيّ التفاعلات الآتية تساوي ΔH له حرارة التكوين القياسية ΔH°f للميثان CH₄(g)؟', null, '["CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)","C(g) + 4H(g) → CH₄(g)","C(s) + 2H₂(g) → CH₄(g)","2C(s) + 4H₂(g) → 2CH₄(g)"]'::jsonb, 'تطبيق', 'تمييز معادلة التكوين', 'متوسط', 'الكتاب ص 37 — مثال 1-6 (ΔH°f(CH₄) = −75 kJ)'),
('mcq', 6, 'كتب طالب معادلة تكوين الماء السائل على النحو: 2H₂(g) + O₂(g) → 2H₂O(l). ما الحكم الصحيح على معادلته؟', null, '["الخطأ في حالة الماء، والصواب أن يكون بخارًا H₂O(g) لأن المتفاعلات غازات","تكوّن 2 mol من الماء، والصواب H₂(g) + ½O₂(g) → H₂O(l)","الخطأ في استعمال O₂، والصواب استعمال ذرات الأكسجين O(g)","صحيحة؛ لأنها موزونة وتبدأ بالعناصر في حالاتها القياسية"]'::jsonb, 'تحليل', 'اكتشاف خطأ', 'صعب', 'الكتاب ص 30 و ص 34 — H₂ + ½O₂ → H₂O، وتعريف حرارة التكوين القياسية'),
('mcq', 7, 'أيّ المعادلات الآتية هي معادلة تكوين حمض البيوتانويك C₃H₇COOH(l) من عناصره في حالاتها القياسية؟', null, '["4C(s) + 8H₂(g) + O₂(g) → C₃H₇COOH(l)","4C(s) + 4H₂(g) + 2O₂(g) → C₃H₇COOH(l)","4C(g) + 4H₂(g) + O₂(g) → C₃H₇COOH(l)","4C(s) + 4H₂(g) + O₂(g) → C₃H₇COOH(l)"]'::jsonb, 'تطبيق', 'اختيار معادلة تكوين', 'صعب', 'الكتاب ص 38 — مسألة 36 (تكوين حمض البيوتانويك)'),
('essay', 1, 'اكتب معادلة تكوين قياسية (تنتج 1 mol من المركب من عناصره في حالاتها القياسية) لكل من: H₂O(l)، CO₂(g)، NH₃(g)، SF₆(g).', null, null, 'تطبيق', 'كتابة معادلات تكوين', 'سهل', 'الكتاب ص 35–37 — الجدول 1-5 ومثال 1-6'),
('essay', 2, 'بيّن كيف يعطي جمع معادلات حرارة التكوين التفاعل الآتي دون استعمال قيم ΔH: 2NO(g) + O₂(g) → 2NO₂(g). اكتب معادلتي تكوين NO(g) و NO₂(g)، ووضح ما تفعله بكل منهما.', null, null, 'تحليل', 'دمج معادلات التكوين', 'صعب', 'الكتاب ص 38 — مسألة 34 (a)'),
('essay', 3, 'علّل استعمال معاملات كسرية في كثير من معادلات التكوين القياسية، ثم اكتب معادلة تكوين SO₃(g) ومعادلة تكوين C₂H₅OH(l)، وبيّن لماذا لا تُعدّ المعادلة 2S(s) + 3O₂(g) → 2SO₃(g)  ΔH = −792 kJ معادلة تكوين قياسية.', null, null, 'تطبيق', 'تعليل وكتابة معادلات', 'متوسط', 'الكتاب ص 32–34 — المعاملات الكسرية وتكوين SO₃')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'حرارة التكوين القياسية هي التغير في المحتوى الحراري المرافق لتكوين مول واحد من المركب من عناصره في حالاتها القياسية؛ لذا يجب أن يكون معامل المركب 1 والمتفاعلات عناصر في حالاتها القياسية.', '["كثيرًا ما تحتاج معادلة التكوين إلى معاملات كسرية حتى يكون معامل المركب 1، مثل S(s) + 3/2O₂(g) → SO₃(g).","المطلوب 1 mol من الناتج، أما العناصر فمعاملاتها تتحدد بالموازنة وقد تكون كسرية أو أكبر من 1.","المتفاعلات في معادلة التكوين عناصر لا مركبات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.837Z"}'::jsonb),
('mcq', 2, 2, 'الهيدروجين والفلور غازان ثنائيا الذرة في الحالة القياسية، ولتكوين 1 mol من HF يلزم ½ mol من كل منهما: ½H₂(g) + ½F₂(g) → HF(g).', '["المعادلة موزونة لكنها تكوّن 2 mol من HF، وحرارة التكوين تخص 1 mol.","H(g) و F(g) ذرات منفردة وليست الحالة القياسية للعنصرين؛ فحالتهما القياسية H₂(g) و F₂(g).","","هذه معادلة تحلل HF إلى عناصره، أي عكس معادلة التكوين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-03T20:38:11.837Z"}'::jsonb),
('mcq', 3, 1, 'معادلة التكوين تنتج 1 mol من NO₂ من النيتروجين والأكسجين في حالتيهما القياسيتين (غازين ثنائيي الذرة): ½N₂(g) + O₂(g) → NO₂(g)، ولها ΔH°f = +33.2 kJ.', '["المعادلة تكوّن 2 mol من NO₂، فتكون ΔH لها ضعف ΔH°f.","","NO مركب وليس عنصرًا، ومعادلة التكوين تبدأ بالعناصر فقط.","N(g) و O(g) ذرات منفردة وليست الحالة القياسية للعنصرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.838Z"}'::jsonb),
('mcq', 4, 0, 'يحتوي 1 mol من C₂H₅OH على 2 mol من C و 6 mol من H و 1 mol من ذرات O، فالمعادلة: 2C(s) + 3H₂(g) + ½O₂(g) → C₂H₅OH(l)، ومعامل O₂ هو 1/2.', '["","عُدّت ذرة الأكسجين الواحدة جزيء O₂ كاملًا؛ وجزيء O₂ فيه ذرتان، فيلزم نصف جزيء.","3 هو معامل O₂ في معادلة احتراق الإيثانول C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O، لا في معادلة تكوينه.","لا يوجد في جزيء الإيثانول إلا ذرة أكسجين واحدة، فمعامل O₂ لا يمكن أن يكون 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:38:11.838Z"}'::jsonb),
('mcq', 5, 2, 'يتكون 1 mol من CH₄ من الكربون الصلب والهيدروجين الغازي ثنائي الذرة، وهما حالتا العنصرين القياسيتان: C(s) + 2H₂(g) → CH₄(g)، فتكون ΔH له هي ΔH°f = −75 kJ.', '["هذه معادلة احتراق الميثان (ΔH = −891 kJ)، والميثان فيها متفاعل لا ناتج.","C(g) و H(g) ليستا الحالتين القياسيتين للكربون والهيدروجين.","","المعادلة تكوّن 2 mol من CH₄، فتكون ΔH لها ضعف ΔH°f."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-03T20:38:11.838Z"}'::jsonb),
('mcq', 6, 1, 'معادلة التكوين يجب أن تنتج 1 mol من المركب، والمعادلة المكتوبة تنتج 2 mol، فقسمة المعاملات على 2 تعطي H₂(g) + ½O₂(g) → H₂O(l) و ΔH°f = −286 kJ.', '["الماء السائل مركب صحيح وله حرارة تكوين قياسية (−286 kJ/mol)؛ وحالة الناتج لا تُفرض من حالة المتفاعلات.","","O₂(g) هو الحالة القياسية للأكسجين، فاستعماله صحيح.","الموازنة والبدء بالعناصر لا يكفيان؛ فلا بد أن يكون الناتج 1 mol فقط من المركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:38:11.838Z"}'::jsonb),
('mcq', 7, 3, 'في C₃H₇COOH أربع ذرات C وثماني ذرات H وذرتا O، فيلزم 4C(s) و 4H₂(g) (8 ذرات H) و O₂(g) واحد (ذرتا O)، والكربون صلب في حالته القياسية: 4C(s) + 4H₂(g) + O₂(g) → C₃H₇COOH(l).', '["عُدّت كل ذرة H جزيء H₂؛ فثماني ذرات H تحتاج إلى 4H₂ لا 8H₂.","عُدّت كل ذرة O جزيء O₂؛ فذرتا O تحتاجان إلى O₂ واحد لا 2O₂.","الكربون في حالته القياسية صلب C(s) لا غاز C(g).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-03T20:38:11.839Z"}'::jsonb),
('essay', 1, null::int, null, null, 'H₂(g) + ½O₂(g) → H₂O(l)
C(s) + O₂(g) → CO₂(g)
½N₂(g) + 3/2H₂(g) → NH₃(g)
S(s) + 3F₂(g) → SF₆(g)', '["H₂(g) + ½O₂(g) → H₂O(l)","C(s) + O₂(g) → CO₂(g)","½N₂(g) + 3/2H₂(g) → NH₃(g)","S(s) + 3F₂(g) → SF₆(g)"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة تكوين H₂O(l)","marks":1},{"element":"معادلة تكوين CO₂(g)","marks":1},{"element":"معادلة تكوين NH₃(g)","marks":1},{"element":"معادلة تكوين SF₆(g)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلات الأربع صحيحة بالمعاملات والحالات الفيزيائية"},{"level":"2–3 درجات","description":"معادلتان أو ثلاث صحيحة، أو خطأ في الحالات الفيزيائية"},{"level":"1 درجة","description":"معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تكوين 2 mol من الناتج لتجنب المعاملات الكسرية","كتابة العناصر ذرات منفردة مثل N(g) أو H(g)","كتابة الكربون أو الكبريت في الحالة الغازية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:38:11.839Z"}'::jsonb),
('essay', 2, null::int, null, null, 'معادلتا التكوين: ½N₂(g) + ½O₂(g) → NO(g)، و ½N₂(g) + O₂(g) → NO₂(g). NO متفاعل في المعادلة المطلوبة، فنعكس معادلة تكوينه ونضربها في 2: 2NO(g) → N₂(g) + O₂(g). و NO₂ ناتج بمعامل 2، فنضرب معادلة تكوينه في 2: N₂(g) + 2O₂(g) → 2NO₂(g). بالجمع: 2NO(g) + N₂(g) + 2O₂(g) → N₂(g) + O₂(g) + 2NO₂(g)، وبحذف N₂(g) من الطرفين وحذف O₂(g) واحد من الطرفين نحصل على 2NO(g) + O₂(g) → 2NO₂(g).', '["معادلة تكوين NO: ½N₂(g) + ½O₂(g) → NO(g)","معادلة تكوين NO₂: ½N₂(g) + O₂(g) → NO₂(g)","عكس معادلة NO وضربها في 2","ضرب معادلة NO₂ في 2","الجمع وحذف المواد المشتركة للوصول إلى المعادلة المطلوبة"]'::jsonb, '["½N₂(g) + ½O₂(g) → NO(g)  و  ½N₂(g) + O₂(g) → NO₂(g)","عكس الأولى وضربها في 2: 2NO(g) → N₂(g) + O₂(g)","ضرب الثانية في 2: N₂(g) + 2O₂(g) → 2NO₂(g)","الجمع: 2NO(g) + N₂(g) + 2O₂(g) → N₂(g) + O₂(g) + 2NO₂(g)","الحذف: 2NO(g) + O₂(g) → 2NO₂(g)"]'::jsonb, '[{"element":"كتابة معادلتي التكوين صحيحتين","marks":2},{"element":"عكس معادلة NO وضربها في 2","marks":1},{"element":"ضرب معادلة NO₂ في 2","marks":1},{"element":"الجمع والحذف الصحيحان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتا تكوين صحيحتان، ومعالجة صحيحة لكل منهما، وجمع وحذف صحيحان"},{"level":"3–4 درجات","description":"معادلتا تكوين صحيحتان مع خطأ في العكس أو الضرب أو الحذف"},{"level":"1–2 درجة","description":"معادلة تكوين واحدة صحيحة أو فكرة الجمع دون تنفيذ صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم عكس معادلة NO مع أنه متفاعل","نسيان ضرب المعادلتين في 2","حذف O₂ كله من الطرفين بدل حذف المقدار المشترك فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-03T20:38:11.839Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تُكتب معادلة التكوين لتكوين 1 mol من المركب، فإذا احتاج ذلك إلى عدد غير صحيح من جزيئات العناصر ثنائية الذرة استُعملت معاملات كسرية. معادلة تكوين SO₃: S(s) + 3/2O₂(g) → SO₃(g)  ΔH°f = −396 kJ. ومعادلة تكوين الإيثانول: 2C(s) + 3H₂(g) + ½O₂(g) → C₂H₅OH(l). أما المعادلة 2S(s) + 3O₂(g) → 2SO₃(g) فتكوّن 2 mol من SO₃، فقيمة ΔH لها (−792 kJ) ضعف ΔH°f، لذا ليست معادلة تكوين قياسية.', '["التعليل: معادلة التكوين تخص 1 mol من المركب","S(s) + 3/2O₂(g) → SO₃(g)","2C(s) + 3H₂(g) + ½O₂(g) → C₂H₅OH(l)","المعادلة المعطاة تكوّن 2 mol، و −792 kJ ضعف ΔH°f (−396 kJ)"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل استعمال المعاملات الكسرية","marks":1},{"element":"معادلة تكوين SO₃(g)","marks":1},{"element":"معادلة تكوين C₂H₅OH(l)","marks":1},{"element":"بيان سبب عدم عدّ المعادلة المعطاة معادلة تكوين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل صحيح، ومعادلتان صحيحتان، وبيان صحيح لسبب رفض المعادلة المعطاة"},{"level":"2–3 درجات","description":"نقص في أحد العناصر أو خطأ في معادلة واحدة"},{"level":"1 درجة","description":"معادلة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن المعاملات الكسرية خطأ في الموازنة","كتابة 3O₂ بدل ½O₂ في معادلة تكوين الإيثانول","عدّ المعادلة المعطاة معادلة تكوين لأنها تبدأ بالعناصر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-03T20:38:11.840Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O09') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L4-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'عندما يتحد ثالث أكسيد الكبريت SO₃ مع الماء في الجو يتكون حمض. ما هذا الحمض؟', null, '["حمض الكبريتيك H₂SO₄","حمض الكبريتوز H₂SO₃","كبريتيد الهيدروجين H₂S","حمض النيتريك HNO₃"]'::jsonb, 'تذكر', 'تذكر ناتج', 'سهل', 'الكتاب ص 34 — الشكل 1-13 (SO₃ وحمض الكبريتيك)'),
('mcq', 2, 'ما التفاعل الذي ينتج عنه ثالث أكسيد الكبريت SO₃ المسبب للمطر الحمضي؟', null, '["تفاعل الكبريت مع الهيدروجين","تفاعل الكبريت مع الفلور","تفاعل الكبريت مع الأكسجين","تحلل حمض الكبريتيك في التربة"]'::jsonb, 'تذكر', 'تذكر مصدر', 'سهل', 'الكتاب ص 34 — تكوّن ثالث أكسيد الكبريت'),
('mcq', 3, 'أيّ مما يأتي يصف ثالث أكسيد الكبريت SO₃ وصفًا صحيحًا؟', null, '["غاز خامل لا أثر له في البيئة","سائل يتجمع على سطح التربة","غاز نبيل في طبقات الجو العليا","غاز خانق يسبب المطر الحمضي"]'::jsonb, 'تذكر', 'تذكر صفة', 'متوسط', 'الكتاب ص 34 — «وهو غاز خانق يتسبب في إنتاج المطر الحمضي»'),
('mcq', 4, 'أيّ المعادلات الآتية تمثل تكوّن الحمض من ثالث أكسيد الكبريت ورطوبة الجو؟', null, '["SO₂(g) + H₂O(l) → H₂SO₄(aq)","SO₃(g) + H₂O(l) → H₂SO₄(aq)","SO₃(g) + H₂(g) → H₂SO₄(aq)","S(s) + 3/2O₂(g) → SO₃(g)"]'::jsonb, 'فهم', 'اختيار معادلة', 'متوسط', 'الكتاب ص 34 و ص 38 — الشكل 1-13 ومسألة 34 (b)'),
('mcq', 5, 'ما الأثر الذي يُحدثه المطر الحمضي الناتج عن حمض الكبريتيك عند وصوله إلى الأرض؟', null, '["يدمّر الأشجار والممتلكات ببطء","يزيد خصوبة التربة ونمو الغابات","يكوّن طبقة تحمي المباني من التآكل","يخفض حرارة الجو ويمنع الاحتباس الحراري"]'::jsonb, 'تذكر', 'تذكر أثر بيئي', 'متوسط', 'الكتاب ص 34 — الشكل 1-13 (أثر المطر الحمضي في الأشجار)'),
('mcq', 6, 'كيف يوصف حمض الكبريتيك H₂SO₄ الذي يتكون من ثالث أكسيد الكبريت في الجو؟', null, '["حمض ضعيف لا يؤثر في الأشجار والمباني","مادة متعادلة ليست حمضية ولا قاعدية","حمض قوي يصل إلى الأرض مطرًا حمضيًّا","قاعدة قوية تتفاعل مع الأشجار فتتلفها"]'::jsonb, 'تذكر', 'تذكر صفة', 'متوسط', 'الكتاب ص 34 — الشكل 1-13 (حمض الكبريتيك حمض قوي)'),
('mcq', 7, 'أيّ تسلسل مما يأتي يصف مراحل تكوّن المطر الحمضي الناتج عن ثالث أكسيد الكبريت وصفًا صحيحًا؟', null, '["يتحلل H₂SO₄ في الجو ← يتكون منه SO₃ ← يسقط SO₃ على الأرض مطرًا حمضيًّا","يتفاعل S مع O₂ فيتكون SO₃ ← يختلط SO₃ برطوبة الجو فيتكون H₂SO₄ ← يسقط مطرًا حمضيًّا","يتحد SO₃ مع O₂ في الجو ← يتكون S ← يذوب S في الماء فيسقط مطرًا حمضيًّا","يتفاعل S مع الماء فيتكون H₂S ← يتأكسد H₂S إلى SO₃ في التربة ← يتبخر مطرًا حمضيًّا"]'::jsonb, 'فهم', 'ترتيب مراحل', 'صعب', 'الكتاب ص 34 — تكوّن SO₃ والمطر الحمضي (الشكل 1-13)'),
('essay', 1, 'اذكر التفاعل الذي ينتج عنه ثالث أكسيد الكبريت، واسم الحمض الذي يتكون عندما يختلط برطوبة الجو، وأثر المطر الحمضي الناتج في البيئة.', null, null, 'تذكر', 'ذكر حقائق', 'سهل', 'الكتاب ص 34 — حرارة التكوين القياسية (SO₃ والمطر الحمضي)'),
('essay', 2, 'اكتب المعادلة الكيميائية الحرارية لتكوين 1 mol من SO₃(g) من عناصره، علمًا بأن ΔH°f له −396 kJ، ثم اكتب معادلة اتحاده مع الماء، وصف بالاستعانة بالمعادلتين دور SO₃ في تكوين المطر الحمضي.', null, null, 'فهم', 'كتابة معادلات ووصف', 'صعب', 'الكتاب ص 34 و ص 38 — تكوّن SO₃ والشكل 1-13 ومسألة 34 (b)'),
('essay', 3, 'غابة تقع قرب منطقة صناعية ينبعث منها ثالث أكسيد الكبريت بكثرة، ولوحظ بعد سنوات موت كثير من أشجارها وتآكل بعض المنشآت المجاورة. صف بالتسلسل ما حدث كيميائيًّا وأدى إلى هذه النتائج.', null, null, 'فهم', 'وصف تسلسل في موقف', 'صعب', 'الكتاب ص 34 — الشكل 1-13 (المطر الحمضي والأشجار)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'يتحد SO₃ مع الماء في الجو مكونًا حمض الكبريتيك H₂SO₄: SO₃ + H₂O → H₂SO₄.', '["","H₂SO₃ يحتوي على ثلاث ذرات أكسجين، ويتكون من SO₂ لا من SO₃؛ فاتحاد SO₃ مع H₂O يعطي أربع ذرات أكسجين.","H₂S لا يحتوي على أكسجين، ويتكون من الهيدروجين والكبريت لا من SO₃ والماء.","HNO₃ حمض يحتوي على النيتروجين، ولا يمكن أن يتكون من SO₃ والماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.840Z"}'::jsonb),
('mcq', 2, 2, 'ينتج SO₃ من تفاعل الكبريت مع الأكسجين: S(s) + 3/2O₂(g) → SO₃(g)  ΔH°f = −396 kJ.', '["تفاعل الكبريت مع الهيدروجين ينتج كبريتيد الهيدروجين H₂S لا SO₃.","تفاعل الكبريت مع الفلور ينتج سادس فلوريد الكبريت SF₆.","","SO₃ ينتج من اتحاد الكبريت بالأكسجين، وحمض الكبريتيك ناتج عن SO₃ لا مصدر له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:38:11.841Z"}'::jsonb),
('mcq', 3, 3, 'SO₃ غاز خانق، يتسبب في إنتاج المطر الحمضي عندما يختلط بالرطوبة الموجودة في الجو.', '["SO₃ ليس خاملًا؛ فهو يتحد مع الماء مكونًا حمضًا قويًّا يضر بالبيئة.","SO₃ يُنتج في التفاعل S(s) + 3/2O₂(g) → SO₃(g) في الحالة الغازية، ويختلط برطوبة الجو.","SO₃ مركب من الكبريت والأكسجين، والغازات النبيلة عناصر لا مركبات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-03T20:38:11.841Z"}'::jsonb),
('mcq', 4, 1, 'يتحد SO₃ مع الماء مكونًا حمض الكبريتيك: SO₃(g) + H₂O(l) → H₂SO₄(aq)، وهي معادلة موزونة (S واحدة، و H اثنتان، و O أربع في كل طرف).', '["المتفاعل في المطر الحمضي المقصود هو SO₃ لا SO₂، والمعادلة غير موزونة (ثلاث ذرات O مقابل أربع).","","الحمض يتكون من اتحاد SO₃ بالماء (الرطوبة) لا بغاز الهيدروجين، والمعادلة غير موزونة.","هذه معادلة تكوين SO₃ نفسه من عناصره، لا معادلة تكوّن الحمض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-03T20:38:11.841Z"}'::jsonb),
('mcq', 5, 0, 'حمض الكبريتيك حمض قوي يصل إلى الأرض على شكل مطر حمضي، فيدمّر الأشجار والممتلكات ببطء.', '["","المطر الحمضي يضر الأشجار ويدمّرها، ولا يزيد نمو الغابات.","الحمض القوي يُتلف الممتلكات والمباني ولا يحميها.","أثر المطر الحمضي هو إتلاف الأشجار والممتلكات، ولا علاقة له بخفض حرارة الجو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-03T20:38:11.841Z"}'::jsonb),
('mcq', 6, 2, 'H₂SO₄ حمض قوي يصل إلى الأرض على شكل مطر حمضي، فيدمّر الأشجار والممتلكات ببطء.', '["H₂SO₄ حمض قوي لا ضعيف، وهو يؤثر في الأشجار والممتلكات.","H₂SO₄ حمض، ولذلك يسمى المطر الناتج عنه مطرًا حمضيًّا.","","H₂SO₄ حمض لا قاعدة، رغم أنه يتلف الأشجار فعلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.842Z"}'::jsonb),
('mcq', 7, 1, 'يتكون SO₃ من تفاعل الكبريت مع الأكسجين، ثم يتحد SO₃ مع الماء (الرطوبة) في الجو مكونًا حمض الكبريتيك القوي H₂SO₄ الذي يصل إلى الأرض على شكل مطر حمضي.', '["الترتيب معكوس؛ فـ SO₃ هو الذي يتكون أولًا ثم يتحول إلى H₂SO₄، لا العكس.","","SO₃ لا يتحول إلى كبريت؛ والكبريت هو المادة الأولية التي تتأكسد إلى SO₃.","SO₃ يتكون من الكبريت والأكسجين ويتحول إلى حمض في الجو لا في التربة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-03T20:38:11.842Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينتج ثالث أكسيد الكبريت SO₃ من تفاعل الكبريت مع الأكسجين. وعندما يختلط SO₃ بالرطوبة الموجودة في الجو يتكون حمض الكبريتيك H₂SO₄، وهو حمض قوي يصل إلى الأرض على شكل مطر حمضي، فيدمّر الأشجار والممتلكات ببطء.', '["SO₃ ينتج من تفاعل الكبريت مع الأكسجين","يتكون حمض الكبريتيك H₂SO₄ (حمض قوي)","يصل إلى الأرض مطرًا حمضيًّا يدمّر الأشجار والممتلكات ببطء"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر تفاعل الكبريت مع الأكسجين","marks":1},{"element":"تسمية الحمض H₂SO₄ ووصفه بأنه قوي","marks":1},{"element":"ذكر أثر المطر الحمضي في الأشجار والممتلكات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ذكر التفاعل والحمض والأثر البيئي صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان من الثلاثة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الحمض حمض الكبريتوز H₂SO₃","القول إن SO₃ ينتج من الكبريت والهيدروجين","إغفال الأثر البيئي أو وصفه بأثر مفيد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-03T20:38:11.842Z"}'::jsonb),
('essay', 2, null::int, null, null, 'معادلة التكوين: S(s) + 3/2O₂(g) → SO₃(g)  ΔH°f = −396 kJ. ومعادلة اتحاده مع الماء: SO₃(g) + H₂O(l) → H₂SO₄(aq). دور SO₃: يتكون غاز SO₃ الخانق من تفاعل الكبريت مع الأكسجين، ثم يختلط بالرطوبة الموجودة في الجو فيتكون حمض الكبريتيك، وهو حمض قوي يسقط على الأرض على شكل مطر حمضي يدمّر الأشجار والممتلكات ببطء.', '["S(s) + 3/2O₂(g) → SO₃(g)  ΔH°f = −396 kJ","SO₃(g) + H₂O(l) → H₂SO₄(aq)","SO₃ غاز خانق يختلط برطوبة الجو","H₂SO₄ حمض قوي يسقط مطرًا حمضيًّا ويدمّر الأشجار والممتلكات"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة تكوين SO₃ بالمعاملات والحالات و ΔH","marks":1},{"element":"معادلة اتحاد SO₃ مع الماء موزونة","marks":1},{"element":"وصف دور SO₃ في تكوين المطر الحمضي","marks":1},{"element":"ذكر أثر المطر الحمضي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلتان صحيحتان، ووصف كامل لدور SO₃ وأثر المطر الحمضي"},{"level":"2–3 درجات","description":"معادلة واحدة صحيحة مع وصف صحيح، أو معادلتان مع وصف ناقص"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة معامل O₂ عددًا صحيحًا وتكوين 2 mol من SO₃","كتابة SO₂ بدل SO₃ في معادلة تكوين الحمض","إعطاء ΔH إشارة موجبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:38:11.842Z"}'::jsonb),
('essay', 3, null::int, null, null, '1) يتصاعد غاز SO₃ (وهو ناتج عن تفاعل الكبريت مع الأكسجين) إلى الجو. 2) يختلط SO₃ بالرطوبة الموجودة في الجو فيتحد مع الماء مكونًا حمض الكبريتيك: SO₃ + H₂O → H₂SO₄. 3) حمض الكبريتيك حمض قوي يصل إلى الأرض على شكل مطر حمضي. 4) يدمّر المطر الحمضي الأشجار والممتلكات (المنشآت) ببطء، ولذلك ظهرت النتائج بعد سنوات.', '["انبعاث SO₃ إلى الجو","اتحاده برطوبة الجو مكونًا H₂SO₄","H₂SO₄ حمض قوي يسقط مطرًا حمضيًّا","تدمير الأشجار والممتلكات ببطء (تفسير تأخر ظهور الأثر)"]'::jsonb, '[]'::jsonb, '[{"element":"انبعاث SO₃ ومصدره","marks":1},{"element":"تكوّن H₂SO₄ من SO₃ والرطوبة","marks":1},{"element":"سقوط المطر الحمضي","marks":1},{"element":"ربط النتائج بتدمير الأشجار والممتلكات ببطء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسلسل كامل وصحيح للمراحل الأربع مع الربط بالنتائج"},{"level":"2–3 درجات","description":"تسلسل صحيح مع إغفال مرحلة أو عدم الربط بالنتائج"},{"level":"1 درجة","description":"ذكر المطر الحمضي فقط دون تسلسل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن SO₃ نفسه يسقط على الأشجار دون تكوّن حمض","إغفال دور الرطوبة في الجو","عكس ترتيب المراحل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-03T20:38:11.843Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
