insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L4-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'إذا علمت أن ΔHcomb للأوكتان C₈H₁₈ = −5471 kJ/mol، و ΔHcomb للإيثانول C₂H₅OH = −1367 kJ/mol، فأيّ الوقودين يطلق كمية أكبر من الطاقة عند احتراق 1 mol منه احتراقًا كاملًا؟', null, '["الإيثانول C₂H₅OH، لأنه يحتوي على الأكسجين","الكميتان متساويتان، لأن كليهما يحترق كاملًا","الأوكتان C₈H₁₈، لأن مقدار ΔHcomb له أكبر","الإيثانول C₂H₅OH، لأن كتلته المولية أصغر"]'::jsonb, 'فهم', 'مقارنة لكل مول', 'سهل', 'الكتاب ص 39 — الكتابة في الكيمياء (الأوكتان والإيثانول)'),
('mcq', 2, 'ما كمية الطاقة المنطلقة عند احتراق 1 kg من الأوكتان C₈H₁₈ احتراقًا كاملًا؟ (ΔHcomb = −5471 kJ/mol، الكتلة المولية = 114.22 g/mol)', null, '["47.90 kJ","4.790×10⁴ kJ","5471 kJ","6.249×10⁸ kJ"]'::jsonb, 'تطبيق', 'حساب طاقة لكل كيلوجرام', 'متوسط', 'الكتاب ص 39 — الكتابة في الكيمياء (الطاقة لكل 1 kg)'),
('mcq', 3, 'يطلق 1 kg من الأوكتان 4.790×10⁴ kJ، ويطلق 1 kg من الإيثانول 2.967×10⁴ kJ عند احتراقهما. كم مرة تقريبًا تزيد طاقة الأوكتان لكل كيلوجرام على طاقة الإيثانول؟', null, '["1.61 مرة","4.00 مرات","0.62 مرة","2.48 مرة"]'::jsonb, 'تحليل', 'مقارنة نسبية', 'صعب', 'الكتاب ص 39 — الكتابة في الكيمياء (المقارنة لكل 1 kg)'),
('mcq', 4, 'قارن طالب بين الأوكتان (ΔHcomb = −5471 kJ/mol، الكتلة المولية 114.22 g/mol) والإيثانول (ΔHcomb = −1367 kJ/mol، الكتلة المولية 46.07 g/mol). ما الاستنتاج الصحيح؟', null, '["الأوكتان أكبر طاقة لكل مول، والإيثانول أكبر طاقة لكل كيلوجرام","الإيثانول أكبر طاقة لكل مول ولكل كيلوجرام","الوقودان متساويان لكل كيلوجرام ويختلفان لكل مول","الأوكتان أكبر طاقة لكل مول ولكل كيلوجرام، والفرق لكل كيلوجرام أصغر"]'::jsonb, 'تحليل', 'استنتاج مقارنة', 'متوسط', 'الكتاب ص 39 — الكتابة في الكيمياء (الأوكتان والإيثانول)'),
('mcq', 5, 'ما مكونات وقود E85 الذي تستعمله المركبات ذات المرونة في استعمال الوقود FFV؟', null, '["85% جازولين و 15% إيثانول","85% إيثانول و 15% جازولين","10% إيثانول و 90% جازولين","100% إيثانول دون جازولين"]'::jsonb, 'تذكر', 'تذكر مكونات', 'سهل', 'الكتاب ص 39 — كيف تعمل الأشياء؟ (المركبات ذات المرونة ووقود E85)'),
('mcq', 6, 'يلزم لخزان وقود المركبة التي تحرق E85 أن يتسع لكمية وقود أكبر بنحو 30% من خزان المركبة التقليدية. ما التفسير الأنسب لذلك إذا علمت أن 1 kg من الإيثانول يطلق 2.967×10⁴ kJ و 1 kg من الأوكتان يطلق 4.790×10⁴ kJ؟', null, '["لأن الإيثانول يطلق طاقة أكبر لكل مول فيحترق أسرع من الجازولين","لأن E85 يتبخر بسرعة فيُفقد جزء كبير منه قبل الاحتراق","لأن الإيثانول يتفاعل مع جدار الخزان فيستهلك جزءًا من الوقود","لأن الإيثانول يطلق طاقة أقل لكل كيلوجرام، فيلزم وقود أكثر لإنتاج الطاقة نفسها"]'::jsonb, 'تحليل', 'تفسير تطبيق حياتي', 'متوسط', 'الكتاب ص 39 — كيف تعمل الأشياء؟ (متطلبات الاحتراق في FFV)'),
('mcq', 7, 'ما كمية الحرارة المنطلقة عند احتراق 5.0 kg من الفحم إذا كانت نسبة كتلة الكربون فيه 96.2%، والمواد الأخرى فيه لا تتفاعل؟ (ΔHcomb للكربون = −394 kJ/mol، الكتلة المولية للكربون = 12.01 g/mol)', null, '["1.6×10⁵ kJ","1.6×10² kJ","1.9×10⁶ kJ","2.3×10⁷ kJ"]'::jsonb, 'تطبيق', 'حساب طاقة وقود', 'صعب', 'الكتاب ص 43 — مسألة 74 (التدفئة باستعمال الفحم)'),
('essay', 1, 'اكتب المعادلة الكيميائية الحرارية لاحتراق 1 mol من الأوكتان C₈H₁₈(l) احتراقًا كاملًا (ΔHcomb = −5471 kJ/mol)، والمعادلة الكيميائية الحرارية لاحتراق 1 mol من الإيثانول C₂H₅OH(l) (ΔHcomb = −1367 kJ/mol)، ثم بيّن أيهما يطلق طاقة أكبر لكل 1 mol.', null, null, 'تطبيق', 'كتابة معادلات حرارية ومقارنة', 'سهل', 'الكتاب ص 30 و ص 39 — احتراق الأوكتان، والكتابة في الكيمياء'),
('essay', 2, 'احسب الطاقة المنطلقة عند احتراق 1 kg من كل من الأوكتان (ΔHcomb = −5471 kJ/mol) والإيثانول (ΔHcomb = −1367 kJ/mol)، مستعملًا الكتل الذرية C = 12.01 و H = 1.008 و O = 16.00، ثم قارن بين نتيجة المقارنة لكل كيلوجرام ونتيجتها لكل مول، وفسّر الفرق.', null, null, 'تحليل', 'حساب ومقارنة وتفسير', 'صعب', 'الكتاب ص 39 — الكتابة في الكيمياء (لكل 1 mol ولكل 1 kg)'),
('essay', 3, 'قال شخص: «وقود E85 أفضل من الجازولين في كل شيء». قوّم هذه العبارة من حيث الطاقة المنطلقة لكل كيلوجرام، والأثر البيئي، ومصدر الوقود، ومتطلبات المركبة، علمًا بأن 1 kg من الإيثانول يطلق 2.967×10⁴ kJ و 1 kg من الأوكتان يطلق 4.790×10⁴ kJ.', null, null, 'تقويم', 'تقويم عبارة', 'متوسط', 'الكتاب ص 39 — كيف تعمل الأشياء؟ (المركبات ذات المرونة ووقود E85)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
