from (values
('mcq', 1, 2, 'لكل 1 mol يطلق الأوكتان 5471 kJ والإيثانول 1367 kJ، فالأوكتان يطلق طاقة أكبر لكل مول (نحو أربعة أضعاف).', '["وجود الأكسجين في الإيثانول لا يزيد الطاقة المنطلقة؛ والقيم المعطاة تبين أن 1367 kJ أقل من 5471 kJ.","الاحتراق الكامل لا يعني تساوي الطاقة؛ فكل وقود له قيمة ΔHcomb خاصة به.","","الكتلة المولية الأصغر لا تزيد الطاقة لكل مول؛ والمقارنة لكل مول تكون بقيمتي ΔHcomb مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-03T20:38:11.844Z"}'::jsonb),
('mcq', 2, 1, 'عدد المولات في 1000 g = 1000 g ÷ 114.22 g/mol = 8.755 mol، والطاقة = 8.755 mol × 5471 kJ/mol = 4.790×10⁴ kJ.', '["هذه الطاقة لكل 1 g (5471 ÷ 114.2)، إذ لم يُحوَّل 1 kg إلى 1000 g.","","هذه الطاقة لكل 1 mol، لا لكل 1 kg؛ إذ لم تُحسب عدد المولات في الكيلوجرام.","ضُربت ΔHcomb في الكتلة المولية وفي 1000 بدل قسمة الكتلة على الكتلة المولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-03T20:38:11.844Z"}'::jsonb),
('mcq', 3, 0, 'النسبة = 4.790×10⁴ ÷ 2.967×10⁴ = 1.61؛ فالأوكتان يطلق لكل كيلوجرام نحو 1.6 ضعف ما يطلقه الإيثانول، وهو فرق أصغر من الفرق لكل مول.', '["","4.00 هي النسبة لكل مول (5471 ÷ 1367)، لا لكل كيلوجرام.","هذه النسبة مقلوبة (طاقة الإيثانول ÷ طاقة الأوكتان).","2.48 هي نسبة الكتلتين الموليتين (114.2 ÷ 46.07)، لا نسبة الطاقتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:38:11.845Z"}'::jsonb),
('mcq', 4, 3, 'لكل مول: 5471 kJ مقابل 1367 kJ (4.00 أضعاف). لكل كيلوجرام: 4.790×10⁴ kJ مقابل 2.967×10⁴ kJ (1.61 ضعف). فالأوكتان أكبر في الحالتين، لكن الفرق يقل لكل كيلوجرام لأن الإيثانول أخف (عدد مولاته في 1 kg أكبر: 21.71 mol مقابل 8.755 mol).', '["خفة الإيثانول تقلل الفرق لكنها لا تعكسه؛ فالأوكتان يطلق 4.790×10⁴ kJ/kg مقابل 2.967×10⁴ kJ/kg للإيثانول.","الإيثانول أقل طاقة في الحالتين: 1367 kJ/mol و 2.967×10⁴ kJ/kg.","الطاقتان لكل كيلوجرام غير متساويتين (4.790×10⁴ kJ و 2.967×10⁴ kJ).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-03T20:38:11.845Z"}'::jsonb),
('mcq', 5, 1, 'وقود E85 يتكون من 85% إيثانول C₂H₅OH و 15% جازولين من حيث الحجم، ولذلك يسمى E85.', '["النسبتان معكوستان؛ فالرقم 85 يدل على نسبة الإيثانول لا الجازولين.","","هذا الخليط (10% إيثانول و 90% جازولين) تعمل عليه المركبات التقليدية، وليس E85.","E85 يحتوي على 15% جازولين، وليس إيثانولًا خالصًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-03T20:38:11.845Z"}'::jsonb),
('mcq', 6, 3, 'الإيثانول (المكون الرئيس في E85) يطلق طاقة أقل لكل كيلوجرام من الأوكتان (2.967×10⁴ kJ مقابل 4.790×10⁴ kJ)، فيلزم حرق كمية أكبر من الوقود للحصول على الطاقة نفسها وقطع المسافة نفسها، لذا يحتاج الخزان إلى سعة أكبر.', '["الإيثانول يطلق طاقة أقل لكل مول (1367 kJ مقابل 5471 kJ)، لا أكبر.","البيانات المعطاة عن الطاقة لكل كيلوجرام هي التي تفسر الحاجة إلى وقود أكثر، لا التبخر.","تآكل بعض المواد بالإيثانول يُعالَج باستعمال الفولاذ الذي لا يصدأ، ولا يفسر الحاجة إلى سعة أكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-03T20:38:11.846Z"}'::jsonb),
('mcq', 7, 0, 'كتلة الكربون = 5000 g × 0.962 = 4810 g، وعدد مولاته = 4810 g ÷ 12.01 g/mol = 400.5 mol، والحرارة = 400.5 mol × 394 kJ/mol = 1.578×10⁵ kJ ≈ 1.6×10⁵ kJ (رقمان معنويان).', '["","لم تُحوَّل الكتلة من kg إلى g، فاستُعمل 4.81 بدل 4810 g.","ضُربت كتلة الكربون بالجرام (4810 g) في 394 kJ/mol مباشرة دون تحويلها إلى مولات.","ضُربت كتلة الكربون في الكتلة المولية بدل القسمة عليها، ثم في 394 kJ/mol."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-03T20:38:11.846Z"}'::jsonb),
('essay', 1, null::int, null, null, 'C₈H₁₈(l) + 25/2O₂(g) → 8CO₂(g) + 9H₂O(l)  ΔHcomb = −5471 kJ
C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l)  ΔHcomb = −1367 kJ
الأوكتان يطلق طاقة أكبر لكل 1 mol (5471 kJ مقابل 1367 kJ، أي نحو 4 أضعاف).', '["معادلة احتراق الأوكتان موزونة بمعامل 25/2 لـ O₂ مع ΔH","معادلة احتراق الإيثانول موزونة بمعامل 3 لـ O₂ مع ΔH","الأوكتان يطلق طاقة أكبر لكل مول"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة احتراق الأوكتان موزونة بالحالات و ΔH","marks":2},{"element":"معادلة احتراق الإيثانول موزونة بالحالات و ΔH","marks":2},{"element":"المقارنة الصحيحة لكل مول","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان موزونتان صحيحتان بالحالات والإشارة، ومقارنة صحيحة"},{"level":"3–4 درجات","description":"معادلة واحدة صحيحة كاملة مع خطأ في الأخرى، أو نقص في الحالات أو ΔH"},{"level":"1–2 درجة","description":"المقارنة الصحيحة فقط أو معادلة غير موزونة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 25 O₂ وتكوين 2 mol من الأوكتان بدل 25/2","نسيان ذرة الأكسجين في الإيثانول عند موازنة O₂ فيُكتب 7/2","كتابة ΔH بإشارة موجبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-03T20:38:11.847Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكتلة المولية للأوكتان C₈H₁₈ = 8(12.01) + 18(1.008) = 114.22 g/mol، وفي 1000 g منه 8.755 mol، فالطاقة = 8.755 × 5471 = 4.790×10⁴ kJ. الكتلة المولية للإيثانول C₂H₅OH = 2(12.01) + 6(1.008) + 16.00 = 46.07 g/mol، وفي 1000 g منه 21.71 mol، فالطاقة = 21.71 × 1367 = 2.967×10⁴ kJ. الأوكتان أكبر في الحالتين، لكن النسبة لكل مول 4.00 بينما لكل كيلوجرام 1.61 فقط؛ لأن الإيثانول أخف كتلة مولية، فيحتوي الكيلوجرام منه على عدد مولات أكبر (21.71 مقابل 8.755 mol)، فيقل الفرق.', '["الكتلة المولية للأوكتان 114.22 g/mol والطاقة 4.790×10⁴ kJ/kg","الكتلة المولية للإيثانول 46.07 g/mol والطاقة 2.967×10⁴ kJ/kg","الأوكتان أكبر لكل مول (4.00 أضعاف) ولكل كيلوجرام (1.61 ضعف)","التفسير: الإيثانول أخف فعدد مولاته في 1 kg أكبر"]'::jsonb, '["M(C₈H₁₈) = 8×12.01 + 18×1.008 = 114.22 g/mol","n(C₈H₁₈) = 1000 g ÷ 114.22 g/mol = 8.755 mol","q(الأوكتان) = 8.755 mol × 5471 kJ/mol = 4.790×10⁴ kJ","M(C₂H₅OH) = 2×12.01 + 6×1.008 + 16.00 = 46.07 g/mol","n(C₂H₅OH) = 1000 g ÷ 46.07 g/mol = 21.71 mol","q(الإيثانول) = 21.71 mol × 1367 kJ/mol = 2.967×10⁴ kJ","النسبة لكل مول = 5471 ÷ 1367 = 4.00، ولكل كيلوجرام = 4.790×10⁴ ÷ 2.967×10⁴ = 1.61"]'::jsonb, '[{"element":"حساب الكتلتين الموليتين","marks":1},{"element":"حساب طاقة 1 kg من الأوكتان","marks":1},{"element":"حساب طاقة 1 kg من الإيثانول","marks":1},{"element":"المقارنة لكل مول ولكل كيلوجرام بالنسب","marks":1},{"element":"تفسير قلة الفرق لكل كيلوجرام","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة بالوحدات والأرقام المعنوية، ومقارنة وتفسير سليمان"},{"level":"3–4 درجات","description":"حسابات صحيحة مع نقص في المقارنة أو التفسير، أو خطأ حسابي واحد"},{"level":"1–2 درجة","description":"حساب الكتلتين الموليتين أو إحدى الطاقتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل 1 kg إلى 1000 g","ضرب ΔHcomb في الكتلة المولية بدل القسمة","استنتاج أن الإيثانول أكبر طاقة لكل كيلوجرام لأنه أخف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-03T20:38:11.847Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير دقيقة. من حيث الطاقة: الإيثانول المكون الرئيس في E85 (85% إيثانول) يطلق طاقة أقل لكل كيلوجرام من الأوكتان (2.967×10⁴ kJ مقابل 4.790×10⁴ kJ)، فيلزم وقود أكثر، ولذلك يحتاج خزان المركبة إلى سعة أكبر بنحو 30% وخليط أغنى بالوقود. من حيث البيئة: احتراق E85 يقلل انطلاق غازات تسبب الاحتباس الحراري مثل ثاني أكسيد الكربون وأكاسيد النيتروجين مقارنة بالجازولين. من حيث المصدر: E85 مصدر متجدد يمكن إنتاجه محليًّا، ويقلل الاعتماد على الوقود الأحفوري. من حيث المركبة: الإيثانول يُتلف بعض المواد، فتُصنع خزانات وأنابيب FFV من الفولاذ الذي لا يصدأ. إذن E85 أفضل بيئيًّا ومن حيث تجدد المصدر، لكنه أقل طاقة لكل كيلوجرام ويتطلب مركبات خاصة.', '["الحكم: العبارة غير دقيقة","طاقة أقل لكل كيلوجرام ← وقود أكثر وخزان أكبر بنحو 30%","أثر بيئي أفضل: غازات احتباس حراري أقل (CO₂ وأكاسيد النيتروجين)","مصدر متجدد ويقلل الاعتماد على الوقود الأحفوري","يتلف بعض المواد فيحتاج إلى فولاذ لا يصدأ في FFV"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم المعلل على العبارة","marks":1},{"element":"المقارنة من حيث الطاقة لكل كيلوجرام ونتيجتها","marks":1},{"element":"الأثر البيئي","marks":1},{"element":"مصدر الوقود","marks":1},{"element":"متطلبات المركبة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم متوازن معلل يتناول الجوانب الأربعة بدقة"},{"level":"3–4 درجات","description":"حكم صحيح يتناول ثلاثة جوانب أو أقل بدقة"},{"level":"1–2 درجة","description":"تناول جانب واحد أو حكم دون تعليل"},{"level":"صفر","description":"تأييد العبارة دون نقد أو لا إجابة"}]'::jsonb, '["القول إن E85 يطلق طاقة أكبر لكل كيلوجرام","إغفال المزايا البيئية ومصدره المتجدد","إغفال حاجة المركبة إلى خزان أكبر ومواد لا تتآكل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-03T20:38:11.848Z"}'::jsonb)
